window.HT = window.HT || {}; HT.CDF = HT.CDF || {};
HT.CDF["G00"] = {"bang":[{"i":0,"tieu_de_bang":"Sảnh Hành trình","tieu_de":"Bảy mươi chín năm, một con đường: bản đồ cuộc đời Chủ tịch Hồ Chí Minh","sapo":"Cuộc đời ấy bắt đầu dưới một mái nhà tranh ở Nam Đàn và khép lại bên một ngôi nhà sàn gỗ nhỏ giữa Hà Nội. Ở giữa là bảy mươi chín năm với những bến cảng, thủ đô, nhà tù và hang núi trên nhiều châu lục. Sảnh Hành trình mở tấm bản đồ ấy ra trước mắt người xem: mười bảy vòm cửa là mười bảy nơi chốn có thật, đi hết là đi trọn một đời người.","bia":{"src":"textures/bai/G00_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai ngôi nhà nhỏ ở hai đầu một đời người","text":"Ở làng Hoàng Trù, còn gọi là làng Chùa, thuộc xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, có một ngôi nhà tranh ba gian dựng bên nếp nhà của cụ đồ Hoàng Xuân Đường. Ngày 19 tháng 5 năm 1890, trong ngôi nhà ấy, con gái cụ là bà Hoàng Thị Loan sinh người con thứ ba. Người cha, nhà nho nghèo Nguyễn Sinh Sắc, đặt tên con là Nguyễn Sinh Cung. Gần tám mươi năm sau, cách đó chừng ba trăm cây số về phía bắc, cậu bé ấy đã là vị Chủ tịch nước, sống trong một ngôi nhà sàn gỗ nhỏ bên ao cá trong khu Phủ Chủ tịch. Tầng trên của ngôi nhà chỉ có hai căn phòng nhỏ, một để làm việc, một để nghỉ; tầng dưới để trống, kê một chiếc bàn họp mộc mạc.\n\nGiữa hai ngôi nhà nhỏ ấy là bảy mươi chín năm. Đó là những con tàu viễn dương và những căn phòng trọ ở Paris, London; những nhà giam ở Hồng Kông và Quảng Tây; một hang đá ở Pác Bó, một lán nứa ở Tân Trào, một lễ đài giữa Quảng trường Ba Đình. Sảnh Hành trình được dựng lên để người xem nhìn thấy trọn tấm bản đồ ấy trước khi bước vào từng chặng đường riêng.","doc":1},{"loai":"anh","src":"textures/bang_w/G00_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sảnh Hành trình”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vùng đất và mái nhà của tuổi thơ","text":"Nam Đàn là vùng đất có núi Chung, có dòng sông Lam chảy qua, có truyền thống hiếu học và yêu nước lâu đời. Đây là quê hương của Mai Thúc Loan, người lãnh đạo cuộc khởi nghĩa chống ách đô hộ nhà Đường ở thế kỷ VIII, và của nhà chí sĩ Phan Bội Châu, người cùng thời với ông Nguyễn Sinh Sắc. Ông Sắc mồ côi từ nhỏ, được cụ đồ Hoàng Xuân Đường nhận về nuôi dạy rồi gả con gái cho. Ông đỗ cử nhân năm 1894 và đỗ Phó bảng năm 1901. Bà Hoàng Thị Loan đảm đang, tần tảo, dệt vải, làm ruộng để chồng yên tâm đèn sách và nuôi các con khôn lớn.\n\nTuổi thơ của cậu bé Cung sớm gắn với những chuyến đi. Năm 1895, cậu theo cha mẹ vào kinh thành Huế, nơi người cha chuẩn bị dự kỳ thi Hội. Đầu năm 1901, bà Loan qua đời ở Huế khi người con út mới sinh được ít lâu. Cũng năm ấy, ông Sắc đỗ Phó bảng, đưa các con về làng Sen, quê nội, sống trong ngôi nhà tranh năm gian do dân làng góp công góp của dựng mừng ông tân khoa. Cậu bé được cha đặt tên mới là Nguyễn Tất Thành, cái tên đầu tiên trong một chuỗi dài những tên gọi về sau (xem chuyên đề Một đời người, nhiều tên gọi).","doc":2},{"loai":"doan","tieu_de":"Chặng thứ nhất: hai mươi mốt năm trên đất nước mình","text":"Nhìn từ trên cao, đời Người chia thành bốn chặng lớn. Chặng thứ nhất kéo dài hai mươi mốt năm, từ 1890 đến 1911, trải dọc chiều dài đất nước. Năm 1906, người thiếu niên theo cha vào Huế lần thứ hai, học trường tiểu học Pháp – Việt Đông Ba rồi vào Trường Quốc học. Ở kinh đô, anh thấy tận mắt một triều đình chỉ còn là cái bóng bên cạnh bộ máy cai trị thuộc địa. Mùa xuân năm 1908, phong trào nông dân chống thuế lan tới Huế. Anh Thành đứng vào đoàn người biểu tình, làm phiên dịch cho đồng bào, và từ đó bị mật thám để ý.\n\nNăm 1909, anh theo cha vào Bình Định, nơi ông Sắc nhận chức tri huyện Bình Khê, rồi tiếp tục đi về phương Nam. Năm 1910, anh dừng chân ở Phan Thiết, dạy chữ Hán và chữ quốc ngữ ở trường Dục Thanh, ngôi trường do các con của nhà thơ yêu nước Nguyễn Thông lập nên. Đầu năm 1911, anh vào Sài Gòn. Thành phố cảng với những con tàu lớn đi Pháp là cánh cửa cuối cùng của chặng đầu đời. Ngày 5/6/1911, cánh cửa ấy mở ra (xem chuyên đề Lời hứa năm 1911 và ngày trở về 1941).","doc":3},{"loai":"anh","src":"textures/bai/G00_v0.jpg","chu_thich":"Không gian 3D tái hiện toàn cảnh Sảnh Hành trình, điểm khởi đầu của cả vòng tham quan.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Chặng thứ hai: ba mươi năm trên bốn châu lục","text":"Chặng thứ hai dài ba mươi năm, từ 1911 đến 1941, và cũng là chặng rộng nhất về không gian. Những năm đầu, người phụ bếp Văn Ba theo tàu qua nhiều hải cảng châu Phi, sang tận bờ Đông nước Mỹ, rồi dừng chân ở London. Cuối năm 1917, Người trở lại Pháp, sống giữa Paris những năm sôi động sau chiến tranh. Ở đây, Người làm thợ sửa ảnh, đọc sách trong thư viện, viết báo, và ký tên Nguyễn Ái Quốc dưới bản yêu sách gửi Hội nghị Versailles năm 1919. Tháng 7/1920, bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin chỉ cho Người con đường giải phóng dân tộc. Tháng 12/1920, tại Đại hội Tours, Người bỏ phiếu tán thành gia nhập Quốc tế Cộng sản.\n\nTừ đó, bản đồ hành trình dịch dần sang phương Đông. Năm 1923, Người bí mật rời Paris sang Moskva. Cuối năm 1924, Người tới Quảng Châu, lập Hội Việt Nam Cách mạng Thanh niên và mở các lớp huấn luyện cán bộ. Những năm 1928 – 1929, Người sống giữa kiều bào ở vùng Đông Bắc Xiêm. Đầu năm 1930, tại Cửu Long, Hương Cảng, Người chủ trì hội nghị hợp nhất thành lập Đảng Cộng sản Việt Nam. Tiếp theo là gần hai năm bị giam ở Hồng Kông, những năm học tập và nghiên cứu ở Liên Xô, rồi con đường vòng qua Trung Quốc để về gần biên giới Tổ quốc.","doc":4},{"loai":"ban_co_biet","text":"Năm 1987, Đại hội đồng UNESCO khóa họp thứ 24 thông qua nghị quyết kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh vào năm 1990. Nghị quyết ghi nhận Người là “Anh hùng giải phóng dân tộc và nhà văn hóa kiệt xuất của Việt Nam”.","nguon_ten":"Nghị quyết của Đại hội đồng UNESCO, khóa họp thứ 24, 1987","doc":5},{"loai":"doan","tieu_de":"Chặng thứ ba: mười ba năm giành và giữ nước","text":"Chặng thứ ba bắt đầu ngày 28/1/1941, khi Người vượt cột mốc 108 về Pác Bó, Cao Bằng. Bốn năm ở Pác Bó rồi Tân Trào là bốn năm chuẩn bị: thành lập Mặt trận Việt Minh, mở lớp huấn luyện cán bộ, xây dựng căn cứ, lập đội Việt Nam Tuyên truyền Giải phóng quân. Giữa chặng ấy còn hơn một năm Người bị giam giữ ở Quảng Tây, từ tháng 8/1942 đến tháng 9/1943. Giữa tháng 8/1945, tại Tân Trào, Người cùng Trung ương Đảng quyết định Tổng khởi nghĩa. Chiều 2/9/1945, tại Quảng trường Ba Đình, Người đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa.\n\nNền độc lập ấy lập tức bị thử thách. Sau hơn một năm tìm mọi cách giữ hòa bình, ngày 19/12/1946 Người ra Lời kêu gọi toàn quốc kháng chiến. Chín năm tiếp theo, bản đồ đời Người thu lại trong những cánh rừng Việt Bắc thuộc Tuyên Quang, Thái Nguyên, Bắc Kạn. Người sống trong những lán nhỏ, thường xuyên di chuyển để giữ bí mật, đi thăm các đơn vị và trực tiếp ra mặt trận Biên giới năm 1950. Chặng đường này khép lại bằng chiến thắng Điện Biên Phủ ngày 7/5/1954 và ngày giải phóng Thủ đô 10/10/1954.","doc":6},{"loai":"anh","src":"textures/bang_w/G00_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sảnh Hành trình”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Chặng cuối: mười lăm năm ở Hà Nội","text":"Chặng cuối kéo dài mười lăm năm, từ khi Người trở về Thủ đô sau ngày giải phóng đến ngày 2/9/1969. Người không ở trong tòa nhà lớn của Phủ Toàn quyền cũ mà chọn ngôi nhà nhỏ của người thợ điện ngay bên cạnh. Từ tháng 5/1958, Người chuyển sang ngôi nhà sàn gỗ dựng theo kiểu nhà sàn Việt Bắc, bên ao cá và vườn cây. Từ những căn nhà giản dị ấy, Người lãnh đạo công cuộc xây dựng miền Bắc và cuộc đấu tranh thống nhất đất nước. Người đi thăm hợp tác xã, nhà máy, trường học, công trường ở khắp các tỉnh, và nhiều lần đi thăm các nước bạn.\n\nNgày 10/5/1965, Người bắt đầu viết Di chúc, rồi nhiều lần sửa chữa, bổ sung trong những năm sau. Những tháng cuối đời, dù sức khỏe đã rất yếu, Người vẫn theo dõi từng tin tức từ chiến trường miền Nam và hỏi han công việc của các cơ quan. Người từ trần lúc 9 giờ 47 phút ngày 2/9/1969 tại Nhà 67 trong khu Phủ Chủ tịch, đúng ngày kỷ niệm hai mươi bốn năm Quốc khánh. Ngày 9/9/1969, tại lễ truy điệu ở Quảng trường Ba Đình, bản Di chúc được công bố trước toàn dân.","doc":7},{"loai":"ban_co_biet","text":"Ngày 25/8/1969, chỉ hơn một tuần trước khi qua đời, Chủ tịch Hồ Chí Minh ký thư trả lời Tổng thống Mỹ Richard Nixon, kiên quyết đòi Mỹ chấm dứt chiến tranh xâm lược và rút quân khỏi miền Nam Việt Nam.","nguon_ten":"Hồ Chí Minh Toàn tập, tập 15; Hồ Chí Minh – Biên niên tiểu sử","doc":8},{"loai":"doan","tieu_de":"Vì sao kể bằng nơi chốn","text":"Bảo tàng này không xếp hiện vật theo chủ đề mà theo nơi chốn. Sảnh Hành trình là một không gian tròn với mười tám mặt vòm, mười bảy vòm cửa mở vào mười bảy gian. Mười sáu gian đầu, mỗi gian là một nơi Người đã thực sự sống hoặc hoạt động. Đó là Làng Sen – Kim Liên, Huế, Phan Thiết, Sài Gòn; rồi Pháp, Anh, Mỹ, Liên Xô, Trung Quốc, Thái Lan, Hồng Kông; sau đó là Pác Bó, Tân Trào, Hà Nội năm 1945, Việt Bắc, Phủ Chủ tịch. Gian thứ mười bảy dành cho Di sản của Người. Mặt vòm thứ mười tám không dẫn vào gian nào. Đó là tường danh dự, nơi treo chân dung Chủ tịch Hồ Chí Minh năm 1946 cùng lời Người về “ham muốn tột bậc” (xem chuyên đề Lời Bác).\n\nCó gian chỉ ứng với một năm ngắn ngủi, như Phan Thiết năm 1910; có gian trải dài mười lăm năm, như Phủ Chủ tịch. Có gian là cả một quốc gia rộng lớn, có gian chỉ là một thung lũng nhỏ bên biên giới. Sự chênh lệch ấy là có chủ ý. Nó giúp người xem cảm nhận điều mà những trang tiểu sử khó diễn tả hết. Đó là khoảng cách địa lý mênh mông của hành trình, nhịp nhanh chậm của từng giai đoạn, và niềm vui trở về của một người con đã đi qua nhiều châu lục. Giữa nền sảnh, bản đồ hành trình khảm đá lấy Hà Nội làm tâm, nối các chặng đường bằng những đường chỉ vàng.","doc":9},{"loai":"anh","src":"textures/bang_w/G00_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sảnh Hành trình”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Một đời, một ước nguyện","text":"Điều làm nên sự thống nhất của hành trình ấy không nằm ở các địa danh, mà ở một ước nguyện xuyên suốt. Năm 1911, người thanh niên ra đi vì muốn xem các nước bên ngoài làm thế nào, để trở về giúp đồng bào. Năm 1946, trên cương vị Chủ tịch nước, Người nói mình chỉ có một ham muốn tột bậc: nước được hoàn toàn độc lập, dân được hoàn toàn tự do, ai cũng có cơm ăn áo mặc, ai cũng được học hành. Năm 1969, trong Di chúc, Người dặn lại mong muốn cuối cùng về một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh.\n\nBa mốc thời gian ấy cách nhau gần sáu mươi năm. Người thanh niên hai mươi mốt tuổi ở bến cảng Sài Gòn và cụ già bảy mươi chín tuổi bên ngôi nhà sàn nói cùng một điều bằng những lời khác nhau. Trong Di chúc, Người còn dặn không nên tổ chức điếu phúng linh đình, để khỏi lãng phí thì giờ và tiền bạc của nhân dân. Ngay cả khi nghĩ về ngày mình đi xa, Người vẫn nghĩ trước hết đến đồng bào.","doc":10},{"loai":"trich","text":"Điều mong muốn cuối cùng của tôi là: Toàn Đảng, toàn dân ta đoàn kết phấn đấu, xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh, và góp phần xứng đáng vào sự nghiệp cách mạng thế giới.","nguoi":"Hồ Chí Minh","nguon_ten":"Di chúc, công bố tại lễ truy điệu ngày 9/9/1969","doc":11},{"loai":"doan","tieu_de":"Dấu tích hôm nay: tấm bản đồ ngoài đời thực","text":"Tấm bản đồ trong sảnh có thể đối chiếu với những địa chỉ có thật mà khách hôm nay vẫn tìm đến. Ở Nghệ An, Khu di tích Kim Liên gìn giữ ngôi nhà tranh ở Hoàng Trù và ngôi nhà năm gian ở làng Sen. Ở Thành phố Hồ Chí Minh, tòa nhà Nhà Rồng bên bến cảng xưa nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Ở Cao Bằng, Khu di tích Pác Bó được xếp hạng di tích quốc gia đặc biệt năm 2012; cột mốc 108 năm xưa nay mang số hiệu 675. Ở Tuyên Quang và Thái Nguyên, nhiều lán trại, nhà sàn thời kháng chiến được giữ gìn trong Khu di tích Tân Trào và ATK Định Hóa.\n\nỞ Hà Nội, Khu di tích Phủ Chủ tịch giữ nguyên ngôi nhà sàn, ao cá, Nhà 67 và nhiều kỷ vật. Lăng Chủ tịch Hồ Chí Minh khánh thành ngày 29/8/1975 trên Quảng trường Ba Đình. Gần đó, Bảo tàng Hồ Chí Minh khánh thành ngày 19/5/1990, dịp kỷ niệm một trăm năm ngày sinh của Người. Ở nước ngoài, nhiều nơi Người từng sống vẫn còn biển ghi nhớ hoặc tượng đài, như căn nhà ở ngõ Compoint, Paris, hay quảng trường mang tên Người ở Moskva. Mỗi địa chỉ ấy là một điểm trên tấm bản đồ, và mỗi gian trong bảo tàng này là một lời mời tìm đến với nó.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia Sự thật","Khu Di tích Kim Liên, Nghệ An","Cục Di sản văn hóa – Di tích lịch sử Pác Bó: https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Nghị quyết của Đại hội đồng UNESCO, khóa họp thứ 24 (1987)","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch"],"doc":[{"t":"Bảy mươi chín năm, một con đường: bản đồ cuộc đời Chủ tịch Hồ Chí Minh. Cuộc đời ấy bắt đầu dưới một mái nhà tranh ở Nam Đàn và khép lại bên một ngôi nhà sàn gỗ nhỏ giữa Hà Nội. Ở giữa là bảy mươi chín năm với những bến cảng, thủ đô, nhà tù và hang núi trên nhiều châu lục. Sảnh Hành trình mở tấm bản đồ ấy ra trước mắt người xem: mười bảy vòm cửa là mười bảy nơi chốn có thật, đi hết là đi trọn một đời người."},{"t":"Hai ngôi nhà nhỏ ở hai đầu một đời người. Ở làng Hoàng Trù, còn gọi là làng Chùa, thuộc xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, có một ngôi nhà tranh ba gian dựng bên nếp nhà của cụ đồ Hoàng Xuân Đường. Ngày 19 tháng 5 năm 1890, trong ngôi nhà ấy, con gái cụ là bà Hoàng Thị Loan sinh người con thứ ba. Người cha, nhà nho nghèo Nguyễn Sinh Sắc, đặt tên con là Nguyễn Sinh Cung. Gần tám mươi năm sau, cách đó chừng ba trăm cây số về phía bắc, cậu bé ấy đã là vị Chủ tịch nước, sống trong một ngôi nhà sàn gỗ nhỏ bên ao cá trong khu Phủ Chủ tịch. Tầng trên của ngôi nhà chỉ có hai căn phòng nhỏ, một để làm việc, một để nghỉ; tầng dưới để trống, kê một chiếc bàn họp mộc mạc. Giữa hai ngôi nhà nhỏ ấy là bảy mươi chín năm. Đó là những con tàu viễn dương và những căn phòng trọ ở Paris, London; những nhà giam ở Hồng Kông và Quảng Tây; một hang đá ở Pác Bó, một lán nứa ở Tân Trào, một lễ đài giữa Quảng trường Ba Đình. Sảnh Hành trình được dựng lên để người xem nhìn thấy trọn tấm bản đồ ấy trước khi bước vào từng chặng đường riêng."},{"t":"Vùng đất và mái nhà của tuổi thơ. Nam Đàn là vùng đất có núi Chung, có dòng sông Lam chảy qua, có truyền thống hiếu học và yêu nước lâu đời. Đây là quê hương của Mai Thúc Loan, người lãnh đạo cuộc khởi nghĩa chống ách đô hộ nhà Đường ở thế kỷ VIII, và của nhà chí sĩ Phan Bội Châu, người cùng thời với ông Nguyễn Sinh Sắc. Ông Sắc mồ côi từ nhỏ, được cụ đồ Hoàng Xuân Đường nhận về nuôi dạy rồi gả con gái cho. Ông đỗ cử nhân năm 1894 và đỗ Phó bảng năm 1901. Bà Hoàng Thị Loan đảm đang, tần tảo, dệt vải, làm ruộng để chồng yên tâm đèn sách và nuôi các con khôn lớn. Tuổi thơ của cậu bé Cung sớm gắn với những chuyến đi. Năm 1895, cậu theo cha mẹ vào kinh thành Huế, nơi người cha chuẩn bị dự kỳ thi Hội. Đầu năm 1901, bà Loan qua đời ở Huế khi người con út mới sinh được ít lâu. Cũng năm ấy, ông Sắc đỗ Phó bảng, đưa các con về làng Sen, quê nội, sống trong ngôi nhà tranh năm gian do dân làng góp công góp của dựng mừng ông tân khoa. Cậu bé được cha đặt tên mới là Nguyễn Tất Thành, cái tên đầu tiên trong một chuỗi dài những tên gọi về sau (xem chuyên đề Một đời người, nhiều tên gọi)."},{"t":"Chặng thứ nhất: hai mươi mốt năm trên đất nước mình. Nhìn từ trên cao, đời Người chia thành bốn chặng lớn. Chặng thứ nhất kéo dài hai mươi mốt năm, từ 1890 đến 1911, trải dọc chiều dài đất nước. Năm 1906, người thiếu niên theo cha vào Huế lần thứ hai, học trường tiểu học Pháp – Việt Đông Ba rồi vào Trường Quốc học. Ở kinh đô, anh thấy tận mắt một triều đình chỉ còn là cái bóng bên cạnh bộ máy cai trị thuộc địa. Mùa xuân năm 1908, phong trào nông dân chống thuế lan tới Huế. Anh Thành đứng vào đoàn người biểu tình, làm phiên dịch cho đồng bào, và từ đó bị mật thám để ý. Năm 1909, anh theo cha vào Bình Định, nơi ông Sắc nhận chức tri huyện Bình Khê, rồi tiếp tục đi về phương Nam. Năm 1910, anh dừng chân ở Phan Thiết, dạy chữ Hán và chữ quốc ngữ ở trường Dục Thanh, ngôi trường do các con của nhà thơ yêu nước Nguyễn Thông lập nên. Đầu năm 1911, anh vào Sài Gòn. Thành phố cảng với những con tàu lớn đi Pháp là cánh cửa cuối cùng của chặng đầu đời. Ngày 5/6/1911, cánh cửa ấy mở ra (xem chuyên đề Lời hứa năm 1911 và ngày trở về 1941)."},{"t":"Chặng thứ hai: ba mươi năm trên bốn châu lục. Chặng thứ hai dài ba mươi năm, từ 1911 đến 1941, và cũng là chặng rộng nhất về không gian. Những năm đầu, người phụ bếp Văn Ba theo tàu qua nhiều hải cảng châu Phi, sang tận bờ Đông nước Mỹ, rồi dừng chân ở London. Cuối năm 1917, Người trở lại Pháp, sống giữa Paris những năm sôi động sau chiến tranh. Ở đây, Người làm thợ sửa ảnh, đọc sách trong thư viện, viết báo, và ký tên Nguyễn Ái Quốc dưới bản yêu sách gửi Hội nghị Versailles năm 1919. Tháng 7/1920, bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin chỉ cho Người con đường giải phóng dân tộc. Tháng 12/1920, tại Đại hội Tours, Người bỏ phiếu tán thành gia nhập Quốc tế Cộng sản. Từ đó, bản đồ hành trình dịch dần sang phương Đông. Năm 1923, Người bí mật rời Paris sang Moskva. Cuối năm 1924, Người tới Quảng Châu, lập Hội Việt Nam Cách mạng Thanh niên và mở các lớp huấn luyện cán bộ. Những năm 1928 – 1929, Người sống giữa kiều bào ở vùng Đông Bắc Xiêm. Đầu năm 1930, tại Cửu Long, Hương Cảng, Người chủ trì hội nghị hợp nhất thành lập Đảng Cộng sản Việt Nam. Tiếp theo là gần hai năm bị giam ở Hồng Kông, những năm học tập và nghiên cứu ở Liên Xô, rồi con đường vòng qua Trung Quốc để về gần biên giới Tổ quốc."},{"t":"Bạn có biết? Năm 1987, Đại hội đồng UNESCO khóa họp thứ 24 thông qua nghị quyết kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh vào năm 1990. Nghị quyết ghi nhận Người là “Anh hùng giải phóng dân tộc và nhà văn hóa kiệt xuất của Việt Nam”."},{"t":"Chặng thứ ba: mười ba năm giành và giữ nước. Chặng thứ ba bắt đầu ngày 28/1/1941, khi Người vượt cột mốc 108 về Pác Bó, Cao Bằng. Bốn năm ở Pác Bó rồi Tân Trào là bốn năm chuẩn bị: thành lập Mặt trận Việt Minh, mở lớp huấn luyện cán bộ, xây dựng căn cứ, lập đội Việt Nam Tuyên truyền Giải phóng quân. Giữa chặng ấy còn hơn một năm Người bị giam giữ ở Quảng Tây, từ tháng 8/1942 đến tháng 9/1943. Giữa tháng 8/1945, tại Tân Trào, Người cùng Trung ương Đảng quyết định Tổng khởi nghĩa. Chiều 2/9/1945, tại Quảng trường Ba Đình, Người đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Nền độc lập ấy lập tức bị thử thách. Sau hơn một năm tìm mọi cách giữ hòa bình, ngày 19/12/1946 Người ra Lời kêu gọi toàn quốc kháng chiến. Chín năm tiếp theo, bản đồ đời Người thu lại trong những cánh rừng Việt Bắc thuộc Tuyên Quang, Thái Nguyên, Bắc Kạn. Người sống trong những lán nhỏ, thường xuyên di chuyển để giữ bí mật, đi thăm các đơn vị và trực tiếp ra mặt trận Biên giới năm 1950. Chặng đường này khép lại bằng chiến thắng Điện Biên Phủ ngày 7/5/1954 và ngày giải phóng Thủ đô 10/10/1954."},{"t":"Chặng cuối: mười lăm năm ở Hà Nội. Chặng cuối kéo dài mười lăm năm, từ khi Người trở về Thủ đô sau ngày giải phóng đến ngày 2/9/1969. Người không ở trong tòa nhà lớn của Phủ Toàn quyền cũ mà chọn ngôi nhà nhỏ của người thợ điện ngay bên cạnh. Từ tháng 5/1958, Người chuyển sang ngôi nhà sàn gỗ dựng theo kiểu nhà sàn Việt Bắc, bên ao cá và vườn cây. Từ những căn nhà giản dị ấy, Người lãnh đạo công cuộc xây dựng miền Bắc và cuộc đấu tranh thống nhất đất nước. Người đi thăm hợp tác xã, nhà máy, trường học, công trường ở khắp các tỉnh, và nhiều lần đi thăm các nước bạn. Ngày 10/5/1965, Người bắt đầu viết Di chúc, rồi nhiều lần sửa chữa, bổ sung trong những năm sau. Những tháng cuối đời, dù sức khỏe đã rất yếu, Người vẫn theo dõi từng tin tức từ chiến trường miền Nam và hỏi han công việc của các cơ quan. Người từ trần lúc 9 giờ 47 phút ngày 2/9/1969 tại Nhà 67 trong khu Phủ Chủ tịch, đúng ngày kỷ niệm hai mươi bốn năm Quốc khánh. Ngày 9/9/1969, tại lễ truy điệu ở Quảng trường Ba Đình, bản Di chúc được công bố trước toàn dân."},{"t":"Bạn có biết? Ngày 25/8/1969, chỉ hơn một tuần trước khi qua đời, Chủ tịch Hồ Chí Minh ký thư trả lời Tổng thống Mỹ Richard Nixon, kiên quyết đòi Mỹ chấm dứt chiến tranh xâm lược và rút quân khỏi miền Nam Việt Nam."},{"t":"Vì sao kể bằng nơi chốn. Bảo tàng này không xếp hiện vật theo chủ đề mà theo nơi chốn. Sảnh Hành trình là một không gian tròn với mười tám mặt vòm, mười bảy vòm cửa mở vào mười bảy gian. Mười sáu gian đầu, mỗi gian là một nơi Người đã thực sự sống hoặc hoạt động. Đó là Làng Sen – Kim Liên, Huế, Phan Thiết, Sài Gòn; rồi Pháp, Anh, Mỹ, Liên Xô, Trung Quốc, Thái Lan, Hồng Kông; sau đó là Pác Bó, Tân Trào, Hà Nội năm 1945, Việt Bắc, Phủ Chủ tịch. Gian thứ mười bảy dành cho Di sản của Người. Mặt vòm thứ mười tám không dẫn vào gian nào. Đó là tường danh dự, nơi treo chân dung Chủ tịch Hồ Chí Minh năm 1946 cùng lời Người về “ham muốn tột bậc” (xem chuyên đề Lời Bác). Có gian chỉ ứng với một năm ngắn ngủi, như Phan Thiết năm 1910; có gian trải dài mười lăm năm, như Phủ Chủ tịch. Có gian là cả một quốc gia rộng lớn, có gian chỉ là một thung lũng nhỏ bên biên giới. Sự chênh lệch ấy là có chủ ý. Nó giúp người xem cảm nhận điều mà những trang tiểu sử khó diễn tả hết. Đó là khoảng cách địa lý mênh mông của hành trình, nhịp nhanh chậm của từng giai đoạn, và niềm vui trở về của một người con đã đi qua nhiều châu lục. Giữa nền sảnh, bản đồ hành trình khảm đá lấy Hà Nội làm tâm, nối các chặng đường bằng những đường chỉ vàng."},{"t":"Một đời, một ước nguyện. Điều làm nên sự thống nhất của hành trình ấy không nằm ở các địa danh, mà ở một ước nguyện xuyên suốt. Năm 1911, người thanh niên ra đi vì muốn xem các nước bên ngoài làm thế nào, để trở về giúp đồng bào. Năm 1946, trên cương vị Chủ tịch nước, Người nói mình chỉ có một ham muốn tột bậc: nước được hoàn toàn độc lập, dân được hoàn toàn tự do, ai cũng có cơm ăn áo mặc, ai cũng được học hành. Năm 1969, trong Di chúc, Người dặn lại mong muốn cuối cùng về một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh. Ba mốc thời gian ấy cách nhau gần sáu mươi năm. Người thanh niên hai mươi mốt tuổi ở bến cảng Sài Gòn và cụ già bảy mươi chín tuổi bên ngôi nhà sàn nói cùng một điều bằng những lời khác nhau. Trong Di chúc, Người còn dặn không nên tổ chức điếu phúng linh đình, để khỏi lãng phí thì giờ và tiền bạc của nhân dân. Ngay cả khi nghĩ về ngày mình đi xa, Người vẫn nghĩ trước hết đến đồng bào."},{"t":"Điều mong muốn cuối cùng của tôi là: Toàn Đảng, toàn dân ta đoàn kết phấn đấu, xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh, và góp phần xứng đáng vào sự nghiệp cách mạng thế giới. — Hồ Chí Minh"},{"t":"Dấu tích hôm nay: tấm bản đồ ngoài đời thực. Tấm bản đồ trong sảnh có thể đối chiếu với những địa chỉ có thật mà khách hôm nay vẫn tìm đến. Ở Nghệ An, Khu di tích Kim Liên gìn giữ ngôi nhà tranh ở Hoàng Trù và ngôi nhà năm gian ở làng Sen. Ở Thành phố Hồ Chí Minh, tòa nhà Nhà Rồng bên bến cảng xưa nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Ở Cao Bằng, Khu di tích Pác Bó được xếp hạng di tích quốc gia đặc biệt năm 2012; cột mốc 108 năm xưa nay mang số hiệu 675. Ở Tuyên Quang và Thái Nguyên, nhiều lán trại, nhà sàn thời kháng chiến được giữ gìn trong Khu di tích Tân Trào và ATK Định Hóa. Ở Hà Nội, Khu di tích Phủ Chủ tịch giữ nguyên ngôi nhà sàn, ao cá, Nhà 67 và nhiều kỷ vật. Lăng Chủ tịch Hồ Chí Minh khánh thành ngày 29/8/1975 trên Quảng trường Ba Đình. Gần đó, Bảo tàng Hồ Chí Minh khánh thành ngày 19/5/1990, dịp kỷ niệm một trăm năm ngày sinh của Người. Ở nước ngoài, nhiều nơi Người từng sống vẫn còn biển ghi nhớ hoặc tượng đài, như căn nhà ở ngõ Compoint, Paris, hay quảng trường mang tên Người ở Moskva. Mỗi địa chỉ ấy là một điểm trên tấm bản đồ, và mỗi gian trong bảo tàng này là một lời mời tìm đến với nó."}],"so_chu":2297},{"i":1,"tieu_de_bang":"Một đời người, nhiều tên gọi","tieu_de":"Từ Nguyễn Sinh Cung đến Hồ Chí Minh: những cái tên theo suốt hành trình","sapo":"Người mà cả thế giới biết đến với tên Hồ Chí Minh từng được gọi là anh Ba, ông Thầu Chín, ông Vương, ông Ké… Các nhà nghiên cứu đã sưu tầm được hơn một trăm tên gọi, bí danh và bút danh của Người. Mỗi cái tên là một vỏ bọc, một chặng đường, và cũng là một câu chuyện còn nhiều điều để kể.","bia":{"src":"textures/bai/G00_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Cái tên của làng Hoàng Trù và cái tên của làng Sen","text":"Cái tên đầu tiên, Nguyễn Sinh Cung, do cha mẹ đặt khi cậu bé chào đời ở làng Hoàng Trù ngày 19/5/1890. Anh trai cậu là Nguyễn Sinh Khiêm, chị gái là Nguyễn Thị Thanh. Năm 1901, ông Nguyễn Sinh Sắc đỗ Phó bảng và đưa các con về làng Sen, quê nội. Theo lệ nhà nho, khi con trai bước vào tuổi thiếu niên, cha đặt cho con một tên mới. Nguyễn Sinh Khiêm trở thành Nguyễn Tất Đạt, còn Nguyễn Sinh Cung trở thành Nguyễn Tất Thành. Hai chữ “Tất Thành” mang ý “ắt sẽ thành công”, gửi gắm mong ước của người cha đối với đứa con trai nhỏ.\n\nVới tên Nguyễn Tất Thành, người thiếu niên học ở Huế, tham gia phong trào chống thuế năm 1908, rồi dạy học ở trường Dục Thanh, Phan Thiết. Khi ra nước ngoài, Người vẫn dùng tên ấy trong những lá thư chính thức đầu tiên. Ngày 15/9/1911, từ Marseille, Người ký tên Nguyễn Tất Thành dưới lá đơn gửi Tổng thống Pháp xin vào học Trường Thuộc địa. Lá đơn không được chấp nhận. Nhưng nó cho thấy khát khao học hỏi của chàng trai hai mươi mốt tuổi, người muốn hiểu tận gốc nước Pháp để tìm cách giúp dân tộc mình.","doc":1},{"loai":"doan","tieu_de":"Văn Ba, người phụ bếp","text":"Ở bến cảng Sài Gòn tháng 6/1911, người thanh niên ấy không xưng tên Nguyễn Tất Thành. Để xin việc trên tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis, anh dùng một cái tên bình dị: Văn Ba. Theo Trần Dân Tiên, anh Ba được nhận làm phụ bếp, ngày ngày dậy từ khi trời chưa sáng, làm việc liên tục đến tối mịt. Cái tên của một người lao động xa xứ ấy mở đầu một thói quen kéo dài suốt ba mươi năm: mỗi chặng đường, một tên gọi; mỗi tên gọi, một vỏ bọc. Đó là cách để một người không tiền bạc, không chỗ dựa, đi qua những vùng đất đầy mật thám.\n\nNhững người bạn ở Sài Gòn khi ấy gọi anh thân mật là anh Ba. Cuộc trò chuyện nổi tiếng về đôi bàn tay lao động cũng diễn ra dưới cái tên ấy (xem chuyên đề Lời hứa năm 1911 và ngày trở về 1941). Người thanh niên con quan Phó bảng tự nguyện bước vào đời sống của tầng lớp làm thuê. Chính cái tên giản dị ấy mở cho anh cánh cửa hiểu biết về những người cùng khổ ở khắp các bến tàu, bếp lò, xưởng thợ trên thế giới.","doc":2},{"loai":"anh","src":"textures/bang_w/G00_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Một đời người, nhiều tên gọi”, nhìn từ xa."},{"loai":"doan","tieu_de":"Nguyễn Ái Quốc: cái tên khiến nhà cầm quyền Pháp phải truy tìm","text":"Mùa hè năm 1919, các nước thắng trận trong Chiến tranh thế giới thứ nhất họp hội nghị ở Versailles, gần Paris. Ngày 18/6/1919, một văn bản ngắn được gửi tới các phái đoàn: bản “Yêu sách của nhân dân An Nam” gồm tám điểm. Văn bản chưa đòi độc lập, mà đòi những quyền tối thiểu cho người Việt. Đó là ân xá tù chính trị, tự do báo chí, tự do hội họp, tự do đi lại, được học hành, được có đại biểu trong nghị viện Pháp. Bên dưới là chữ ký thay mặt Hội những người An Nam yêu nước: Nguyễn Ái Quốc, nghĩa là “Nguyễn yêu nước”.\n\nHội nghị không trả lời. Nhưng bản yêu sách được in thành truyền đơn, gửi tới các nghị sĩ, các tờ báo, phân phát trong cộng đồng người Việt ở Pháp và bí mật đưa về nước. Để đến được với đồng bào không biết tiếng Pháp, bản yêu sách còn được chuyển thành thơ lục bát với tên “Việt Nam yêu cầu ca”. Nhà cầm quyền Pháp lập tức cho mật thám truy tìm người ký tên. Từ đó, Nguyễn Ái Quốc là tên gọi gắn với những năm hoạt động công khai ở Pháp. Đó là tên của đại biểu Đông Dương tại Đại hội Tours năm 1920, của người chủ bút tờ Le Paria, của tác giả cuốn “Bản án chế độ thực dân Pháp” xuất bản tại Paris năm 1925.","doc":3},{"loai":"ban_co_biet","text":"Các nhà nghiên cứu đã sưu tầm được hơn một trăm tên gọi, bí danh và bút danh Chủ tịch Hồ Chí Minh từng dùng; có bản thống kê nêu con số 175. Nhiều cái tên chỉ được giải mã sau này, nhờ hồ sơ lưu trữ và hồi ức của những người từng sát cánh bên Người.","nguon_ten":"Bảo tàng Hồ Chí Minh; Tạp chí Tòa án nhân dân, bài “175 tên gọi, bút danh và bí danh của Chủ tịch Hồ Chí Minh”","doc":4},{"loai":"doan","tieu_de":"Từ Paris đến Moskva: những cái tên trên hồ sơ bí mật","text":"Tháng 6/1923, Nguyễn Ái Quốc bí mật rời Paris, đi qua nước Đức rồi xuống tàu sang Liên Xô. Ở Moskva, Người làm việc trong Quốc tế Cộng sản, dự Đại hội V của Quốc tế Cộng sản năm 1924 và viết bài cho nhiều tờ báo. Cuối năm 1923, nhà thơ trẻ Osip Mandelstam tìm gặp Người và viết bài cho tạp chí Ogoniok. Những dòng ông viết về người thanh niên Đông Dương đã trở thành một trong những chân dung văn học sớm nhất về Nguyễn Ái Quốc.\n\nHơn mười năm sau, trong những năm 1934 – 1938, Người trở lại Liên Xô. Người học tại Trường Quốc tế Lênin, rồi theo học lớp nghiên cứu sinh về các vấn đề dân tộc và thuộc địa, với cái tên Lin. Những cái tên ở Moskva thường ngắn gọn, đứng trên hồ sơ học viên và các báo cáo gửi Quốc tế Cộng sản. Chúng ít được biết đến ở trong nước. Nhưng hôm nay, đó là những dấu vết quý giúp các nhà nghiên cứu lần theo hành trình của Người trong lưu trữ nước ngoài.","doc":5},{"loai":"trich","text":"Từ Nguyễn Ái Quốc đã tỏa ra một thứ văn hóa, không phải văn hóa châu Âu, mà có lẽ là một nền văn hóa tương lai.","nguoi":"Nhà thơ Nga Osip Mandelstam","nguon_ten":"Bài viết về cuộc gặp Nguyễn Ái Quốc, tạp chí Ogoniok (Ngọn lửa nhỏ), Moskva, 1923","doc":6},{"loai":"doan","tieu_de":"Lý Thụy, Thầu Chín, Tống Văn Sơ","text":"Từ cuối năm 1924, Nguyễn Ái Quốc bước vào những năm hoạt động bí mật ở châu Á, và mỗi vùng đất gắn với một cái tên. Ở Quảng Châu, Người lấy tên Lý Thụy, làm phiên dịch cho phái đoàn cố vấn Liên Xô do Mikhail Borodin đứng đầu. Dưới vỏ bọc ấy, Người lập Hội Việt Nam Cách mạng Thanh niên, mở các lớp huấn luyện, ra báo Thanh niên. Những bài giảng ở các lớp học này được in thành cuốn “Đường Kách mệnh” năm 1927.\n\nTháng 7/1928, Người đến vùng Đông Bắc Xiêm, nơi có đông kiều bào Việt sinh sống. Người sống như một người lao động bình thường, cùng bà con làm ruộng, đi bộ rất xa giữa các làng kiều bào để tuyên truyền, tổ chức. Kiều bào gọi Người là ông Thầu Chín. Năm 1931, khi bị cảnh sát Anh bắt ở Hồng Kông, Người mang tên Tống Văn Sơ. Nhờ sự giúp đỡ tận tình của luật sư Frank Loseby, vụ án được đưa lên tới Hội đồng Cơ mật ở London. Cuối cùng, Tống Văn Sơ được trả tự do, thoát khỏi nguy cơ bị trao cho nhà cầm quyền Pháp.","doc":7},{"loai":"ban_co_biet","text":"Năm 1929, tòa án Nam triều ở Vinh đã kết án tử hình vắng mặt Nguyễn Ái Quốc. Vì thế, việc giữ kín tên thật khi bị bắt ở Hồng Kông năm 1931 có ý nghĩa sống còn.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":8},{"loai":"anh","src":"textures/bang_w/G00_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Một đời người, nhiều tên gọi”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hồ Quang, ông Vương, Già Thu, ông Ké","text":"Năm 1938, rời Liên Xô trở lại Trung Quốc, Người mặc quân phục Bát lộ quân, mang tên Hồ Quang, làm việc ở Quế Lâm. Theo hồi ký của Đại tướng Võ Nguyên Giáp, năm 1940 ở Côn Minh, ông và đồng chí Phạm Văn Đồng được gặp một người mà anh em gọi là ông Vương. Người ấy chính là Nguyễn Ái Quốc mà những thanh niên yêu nước trong nước hằng mong gặp. Chỉ trong mấy năm ở Trung Quốc, Người đã thay nhiều tên, tùy nơi ở và công việc.\n\nVề nước năm 1941, sống trong hang Cốc Bó, Người lại có những tên gọi mới. Các đồng chí gọi Người là Già Thu. Đồng bào Tày, Nùng ở Pác Bó gọi Người là ông Ké, nghĩa là ông cụ, theo dáng vẻ một ông già miền núi. Những cái tên ấy giản dị như chính cuộc sống cháo bẹ rau măng ở đầu nguồn. Chúng cũng cho thấy một điều: ở đâu, Người cũng hòa vào đời sống của những người xung quanh, để đồng bào coi Người như người nhà.","doc":9},{"loai":"doan","tieu_de":"Hồ Chí Minh: cái tên đi vào lịch sử","text":"Tháng 8/1942, Người rời Pác Bó sang Trung Quốc để tranh thủ sự ủng hộ quốc tế cho cách mạng Việt Nam. Lần này, Người mang giấy tờ với một cái tên mới: Hồ Chí Minh. Ngày 29/8/1942, tới Túc Vinh, huyện Đức Bảo, tỉnh Quảng Tây, Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ. Người bị giải qua nhiều nhà giam của tỉnh Quảng Tây trong hơn một năm, đến tháng 9/1943 mới được trả tự do. Tập thơ chữ Hán “Ngục trung nhật ký” ra đời trong những ngày tháng ấy.\n\nCái tên mới dần trở nên quen thuộc. Tháng 8/1945, Quốc dân Đại hội ở Tân Trào bầu Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch. Ngày 2/9/1945, cái tên Hồ Chí Minh đứng dưới bản Tuyên ngôn Độc lập và trở thành tên gọi chính thức của vị Chủ tịch nước. Nhiều người khi ấy chưa biết vị Chủ tịch chính là Nguyễn Ái Quốc mà họ đã nghe danh từ lâu. Với nhân dân, cái tên ấy còn được gọi bằng hai tiếng thân thương hơn nữa: Bác Hồ.","doc":10},{"loai":"anh","src":"textures/ht/ht_anh_portrait_of_ho_chi_minh_from_the_book_trang_su_m.jpg","chu_thich":"Chân dung Chủ tịch Hồ Chí Minh in trong sách “Trang sử mới” do Hội Văn hóa cứu quốc Việt Nam ấn hành năm 1945, khi cái tên Hồ Chí Minh vừa trở thành tên gọi chính thức của vị Chủ tịch nước.","credit":"Ảnh: Hội Văn hóa cứu quốc Việt Nam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những bút danh trên trang sách, trang báo","text":"Sau năm 1945, Người vẫn tiếp tục đặt những cái tên mới, nhưng lần này là bút danh trên trang sách, trang báo. Năm 1947, cuốn “Đời sống mới” ký tên Tân Sinh. Cũng năm ấy, tác phẩm “Sửa đổi lối làm việc” ký tên X.Y.Z. Bài báo ngắn “Dân vận” năm 1949 cũng mang bút danh X.Y.Z. Từ năm 1951, khi báo Nhân Dân ra đời, hàng trăm bài viết ngắn của Người đăng trên báo được ký bút danh C.B. Những bài báo ấy viết bằng lời lẽ giản dị, ai đọc cũng hiểu, bàn về những chuyện rất cụ thể như tiết kiệm, chống tham ô, lãng phí, chăm lo cho trẻ em.\n\nCó những cuốn sách kể về chính cuộc đời Người mà không ký tên thật. Cuốn “Vừa đi đường vừa kể chuyện” ký tên T. Lan, ghi lại những câu chuyện kể trên đường đi công tác thời kháng chiến, qua lời một người cùng đi. Cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” ký tên Trần Dân Tiên; nhiều nhà nghiên cứu cho rằng đó cũng là bút danh của chính Người. Kể về mình qua lời một người khác, Người tránh được sự đề cao cá nhân mà vẫn để lại cho hậu thế những tư liệu quý.","doc":11},{"loai":"anh","src":"textures/bang_w/G00_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Một đời người, nhiều tên gọi”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Vì sao nhiều tên đến thế","text":"Nhìn lại, hơn một trăm cái tên không phải là chuyện ngẫu nhiên. Trong ba mươi năm hoạt động ở nước ngoài, Người luôn bị mật thám nhiều nước theo dõi, có lúc bị bắt, có lúc bị kết án vắng mặt. Đổi tên là cách giữ an toàn cho mình, cho tổ chức và cho những người che chở mình. Mỗi tên gọi còn giúp Người hòa vào một cộng đồng: người phụ bếp giữa đám thủy thủ, ông Thầu Chín giữa kiều bào, ông Ké giữa đồng bào miền núi.\n\nHôm nay, những cái tên ấy trở thành đầu mối để các nhà nghiên cứu lần theo hành trình của Người trong lưu trữ nhiều nước. Lá đơn năm 1911 ký tên Nguyễn Tất Thành được tìm thấy trong kho lưu trữ ở Pháp. Các bài báo ký Nguyễn Ái Quốc, các tác phẩm ký Tân Sinh, X.Y.Z., C.B. được tập hợp trong bộ Hồ Chí Minh Toàn tập. Còn giữa ngần ấy tên gọi, cái tên ở lại lâu bền nhất trong lòng người Việt là hai tiếng giản dị: Bác Hồ.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia Sự thật","Bảo tàng Hồ Chí Minh","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","Võ Nguyên Giáp, Những chặng đường lịch sử (hồi ký)","Tạp chí Tòa án nhân dân, “175 tên gọi, bút danh và bí danh của Chủ tịch Hồ Chí Minh”"],"doc":[{"t":"Từ Nguyễn Sinh Cung đến Hồ Chí Minh: những cái tên theo suốt hành trình. Người mà cả thế giới biết đến với tên Hồ Chí Minh từng được gọi là anh Ba, ông Thầu Chín, ông Vương, ông Ké… Các nhà nghiên cứu đã sưu tầm được hơn một trăm tên gọi, bí danh và bút danh của Người. Mỗi cái tên là một vỏ bọc, một chặng đường, và cũng là một câu chuyện còn nhiều điều để kể."},{"t":"Cái tên của làng Hoàng Trù và cái tên của làng Sen. Cái tên đầu tiên, Nguyễn Sinh Cung, do cha mẹ đặt khi cậu bé chào đời ở làng Hoàng Trù ngày 19/5/1890. Anh trai cậu là Nguyễn Sinh Khiêm, chị gái là Nguyễn Thị Thanh. Năm 1901, ông Nguyễn Sinh Sắc đỗ Phó bảng và đưa các con về làng Sen, quê nội. Theo lệ nhà nho, khi con trai bước vào tuổi thiếu niên, cha đặt cho con một tên mới. Nguyễn Sinh Khiêm trở thành Nguyễn Tất Đạt, còn Nguyễn Sinh Cung trở thành Nguyễn Tất Thành. Hai chữ “Tất Thành” mang ý “ắt sẽ thành công”, gửi gắm mong ước của người cha đối với đứa con trai nhỏ. Với tên Nguyễn Tất Thành, người thiếu niên học ở Huế, tham gia phong trào chống thuế năm 1908, rồi dạy học ở trường Dục Thanh, Phan Thiết. Khi ra nước ngoài, Người vẫn dùng tên ấy trong những lá thư chính thức đầu tiên. Ngày 15/9/1911, từ Marseille, Người ký tên Nguyễn Tất Thành dưới lá đơn gửi Tổng thống Pháp xin vào học Trường Thuộc địa. Lá đơn không được chấp nhận. Nhưng nó cho thấy khát khao học hỏi của chàng trai hai mươi mốt tuổi, người muốn hiểu tận gốc nước Pháp để tìm cách giúp dân tộc mình."},{"t":"Văn Ba, người phụ bếp. Ở bến cảng Sài Gòn tháng 6/1911, người thanh niên ấy không xưng tên Nguyễn Tất Thành. Để xin việc trên tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis, anh dùng một cái tên bình dị: Văn Ba. Theo Trần Dân Tiên, anh Ba được nhận làm phụ bếp, ngày ngày dậy từ khi trời chưa sáng, làm việc liên tục đến tối mịt. Cái tên của một người lao động xa xứ ấy mở đầu một thói quen kéo dài suốt ba mươi năm: mỗi chặng đường, một tên gọi; mỗi tên gọi, một vỏ bọc. Đó là cách để một người không tiền bạc, không chỗ dựa, đi qua những vùng đất đầy mật thám. Những người bạn ở Sài Gòn khi ấy gọi anh thân mật là anh Ba. Cuộc trò chuyện nổi tiếng về đôi bàn tay lao động cũng diễn ra dưới cái tên ấy (xem chuyên đề Lời hứa năm 1911 và ngày trở về 1941). Người thanh niên con quan Phó bảng tự nguyện bước vào đời sống của tầng lớp làm thuê. Chính cái tên giản dị ấy mở cho anh cánh cửa hiểu biết về những người cùng khổ ở khắp các bến tàu, bếp lò, xưởng thợ trên thế giới."},{"t":"Nguyễn Ái Quốc: cái tên khiến nhà cầm quyền Pháp phải truy tìm. Mùa hè năm 1919, các nước thắng trận trong Chiến tranh thế giới thứ nhất họp hội nghị ở Versailles, gần Paris. Ngày 18/6/1919, một văn bản ngắn được gửi tới các phái đoàn: bản “Yêu sách của nhân dân An Nam” gồm tám điểm. Văn bản chưa đòi độc lập, mà đòi những quyền tối thiểu cho người Việt. Đó là ân xá tù chính trị, tự do báo chí, tự do hội họp, tự do đi lại, được học hành, được có đại biểu trong nghị viện Pháp. Bên dưới là chữ ký thay mặt Hội những người An Nam yêu nước: Nguyễn Ái Quốc, nghĩa là “Nguyễn yêu nước”. Hội nghị không trả lời. Nhưng bản yêu sách được in thành truyền đơn, gửi tới các nghị sĩ, các tờ báo, phân phát trong cộng đồng người Việt ở Pháp và bí mật đưa về nước. Để đến được với đồng bào không biết tiếng Pháp, bản yêu sách còn được chuyển thành thơ lục bát với tên “Việt Nam yêu cầu ca”. Nhà cầm quyền Pháp lập tức cho mật thám truy tìm người ký tên. Từ đó, Nguyễn Ái Quốc là tên gọi gắn với những năm hoạt động công khai ở Pháp. Đó là tên của đại biểu Đông Dương tại Đại hội Tours năm 1920, của người chủ bút tờ Le Paria, của tác giả cuốn “Bản án chế độ thực dân Pháp” xuất bản tại Paris năm 1925."},{"t":"Bạn có biết? Các nhà nghiên cứu đã sưu tầm được hơn một trăm tên gọi, bí danh và bút danh Chủ tịch Hồ Chí Minh từng dùng; có bản thống kê nêu con số 175. Nhiều cái tên chỉ được giải mã sau này, nhờ hồ sơ lưu trữ và hồi ức của những người từng sát cánh bên Người."},{"t":"Từ Paris đến Moskva: những cái tên trên hồ sơ bí mật. Tháng 6/1923, Nguyễn Ái Quốc bí mật rời Paris, đi qua nước Đức rồi xuống tàu sang Liên Xô. Ở Moskva, Người làm việc trong Quốc tế Cộng sản, dự Đại hội V của Quốc tế Cộng sản năm 1924 và viết bài cho nhiều tờ báo. Cuối năm 1923, nhà thơ trẻ Osip Mandelstam tìm gặp Người và viết bài cho tạp chí Ogoniok. Những dòng ông viết về người thanh niên Đông Dương đã trở thành một trong những chân dung văn học sớm nhất về Nguyễn Ái Quốc. Hơn mười năm sau, trong những năm 1934 – 1938, Người trở lại Liên Xô. Người học tại Trường Quốc tế Lênin, rồi theo học lớp nghiên cứu sinh về các vấn đề dân tộc và thuộc địa, với cái tên Lin. Những cái tên ở Moskva thường ngắn gọn, đứng trên hồ sơ học viên và các báo cáo gửi Quốc tế Cộng sản. Chúng ít được biết đến ở trong nước. Nhưng hôm nay, đó là những dấu vết quý giúp các nhà nghiên cứu lần theo hành trình của Người trong lưu trữ nước ngoài."},{"t":"Từ Nguyễn Ái Quốc đã tỏa ra một thứ văn hóa, không phải văn hóa châu Âu, mà có lẽ là một nền văn hóa tương lai. — Nhà thơ Nga Osip Mandelstam"},{"t":"Lý Thụy, Thầu Chín, Tống Văn Sơ. Từ cuối năm 1924, Nguyễn Ái Quốc bước vào những năm hoạt động bí mật ở châu Á, và mỗi vùng đất gắn với một cái tên. Ở Quảng Châu, Người lấy tên Lý Thụy, làm phiên dịch cho phái đoàn cố vấn Liên Xô do Mikhail Borodin đứng đầu. Dưới vỏ bọc ấy, Người lập Hội Việt Nam Cách mạng Thanh niên, mở các lớp huấn luyện, ra báo Thanh niên. Những bài giảng ở các lớp học này được in thành cuốn “Đường Kách mệnh” năm 1927. Tháng 7/1928, Người đến vùng Đông Bắc Xiêm, nơi có đông kiều bào Việt sinh sống. Người sống như một người lao động bình thường, cùng bà con làm ruộng, đi bộ rất xa giữa các làng kiều bào để tuyên truyền, tổ chức. Kiều bào gọi Người là ông Thầu Chín. Năm 1931, khi bị cảnh sát Anh bắt ở Hồng Kông, Người mang tên Tống Văn Sơ. Nhờ sự giúp đỡ tận tình của luật sư Frank Loseby, vụ án được đưa lên tới Hội đồng Cơ mật ở London. Cuối cùng, Tống Văn Sơ được trả tự do, thoát khỏi nguy cơ bị trao cho nhà cầm quyền Pháp."},{"t":"Bạn có biết? Năm 1929, tòa án Nam triều ở Vinh đã kết án tử hình vắng mặt Nguyễn Ái Quốc. Vì thế, việc giữ kín tên thật khi bị bắt ở Hồng Kông năm 1931 có ý nghĩa sống còn."},{"t":"Hồ Quang, ông Vương, Già Thu, ông Ké. Năm 1938, rời Liên Xô trở lại Trung Quốc, Người mặc quân phục Bát lộ quân, mang tên Hồ Quang, làm việc ở Quế Lâm. Theo hồi ký của Đại tướng Võ Nguyên Giáp, năm 1940 ở Côn Minh, ông và đồng chí Phạm Văn Đồng được gặp một người mà anh em gọi là ông Vương. Người ấy chính là Nguyễn Ái Quốc mà những thanh niên yêu nước trong nước hằng mong gặp. Chỉ trong mấy năm ở Trung Quốc, Người đã thay nhiều tên, tùy nơi ở và công việc. Về nước năm 1941, sống trong hang Cốc Bó, Người lại có những tên gọi mới. Các đồng chí gọi Người là Già Thu. Đồng bào Tày, Nùng ở Pác Bó gọi Người là ông Ké, nghĩa là ông cụ, theo dáng vẻ một ông già miền núi. Những cái tên ấy giản dị như chính cuộc sống cháo bẹ rau măng ở đầu nguồn. Chúng cũng cho thấy một điều: ở đâu, Người cũng hòa vào đời sống của những người xung quanh, để đồng bào coi Người như người nhà."},{"t":"Hồ Chí Minh: cái tên đi vào lịch sử. Tháng 8/1942, Người rời Pác Bó sang Trung Quốc để tranh thủ sự ủng hộ quốc tế cho cách mạng Việt Nam. Lần này, Người mang giấy tờ với một cái tên mới: Hồ Chí Minh. Ngày 29/8/1942, tới Túc Vinh, huyện Đức Bảo, tỉnh Quảng Tây, Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ. Người bị giải qua nhiều nhà giam của tỉnh Quảng Tây trong hơn một năm, đến tháng 9/1943 mới được trả tự do. Tập thơ chữ Hán “Ngục trung nhật ký” ra đời trong những ngày tháng ấy. Cái tên mới dần trở nên quen thuộc. Tháng 8/1945, Quốc dân Đại hội ở Tân Trào bầu Ủy ban Dân tộc giải phóng Việt Nam do Hồ Chí Minh làm Chủ tịch. Ngày 2/9/1945, cái tên Hồ Chí Minh đứng dưới bản Tuyên ngôn Độc lập và trở thành tên gọi chính thức của vị Chủ tịch nước. Nhiều người khi ấy chưa biết vị Chủ tịch chính là Nguyễn Ái Quốc mà họ đã nghe danh từ lâu. Với nhân dân, cái tên ấy còn được gọi bằng hai tiếng thân thương hơn nữa: Bác Hồ."},{"t":"Những bút danh trên trang sách, trang báo. Sau năm 1945, Người vẫn tiếp tục đặt những cái tên mới, nhưng lần này là bút danh trên trang sách, trang báo. Năm 1947, cuốn “Đời sống mới” ký tên Tân Sinh. Cũng năm ấy, tác phẩm “Sửa đổi lối làm việc” ký tên X.Y.Z. Bài báo ngắn “Dân vận” năm 1949 cũng mang bút danh X.Y.Z. Từ năm 1951, khi báo Nhân Dân ra đời, hàng trăm bài viết ngắn của Người đăng trên báo được ký bút danh C.B. Những bài báo ấy viết bằng lời lẽ giản dị, ai đọc cũng hiểu, bàn về những chuyện rất cụ thể như tiết kiệm, chống tham ô, lãng phí, chăm lo cho trẻ em. Có những cuốn sách kể về chính cuộc đời Người mà không ký tên thật. Cuốn “Vừa đi đường vừa kể chuyện” ký tên T. Lan, ghi lại những câu chuyện kể trên đường đi công tác thời kháng chiến, qua lời một người cùng đi. Cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” ký tên Trần Dân Tiên; nhiều nhà nghiên cứu cho rằng đó cũng là bút danh của chính Người. Kể về mình qua lời một người khác, Người tránh được sự đề cao cá nhân mà vẫn để lại cho hậu thế những tư liệu quý."},{"t":"Vì sao nhiều tên đến thế. Nhìn lại, hơn một trăm cái tên không phải là chuyện ngẫu nhiên. Trong ba mươi năm hoạt động ở nước ngoài, Người luôn bị mật thám nhiều nước theo dõi, có lúc bị bắt, có lúc bị kết án vắng mặt. Đổi tên là cách giữ an toàn cho mình, cho tổ chức và cho những người che chở mình. Mỗi tên gọi còn giúp Người hòa vào một cộng đồng: người phụ bếp giữa đám thủy thủ, ông Thầu Chín giữa kiều bào, ông Ké giữa đồng bào miền núi. Hôm nay, những cái tên ấy trở thành đầu mối để các nhà nghiên cứu lần theo hành trình của Người trong lưu trữ nhiều nước. Lá đơn năm 1911 ký tên Nguyễn Tất Thành được tìm thấy trong kho lưu trữ ở Pháp. Các bài báo ký Nguyễn Ái Quốc, các tác phẩm ký Tân Sinh, X.Y.Z., C.B. được tập hợp trong bộ Hồ Chí Minh Toàn tập. Còn giữa ngần ấy tên gọi, cái tên ở lại lâu bền nhất trong lòng người Việt là hai tiếng giản dị: Bác Hồ."}],"so_chu":2034},{"i":2,"tieu_de_bang":"Lời hứa năm 1911 và ngày trở về 1941","tieu_de":"“Tôi sẽ trở về giúp đồng bào”: ba mươi năm giữ một lời hứa","sapo":"Theo Trần Dân Tiên, năm 1911, trước khi xuống tàu, người thanh niên Nguyễn Tất Thành nói với một người bạn rằng anh muốn ra nước ngoài xem người ta làm thế nào, rồi sẽ trở về giúp đồng bào. Ba mươi năm sau, vào ngày mồng 2 Tết Tân Tỵ, lời hứa ấy thành hiện thực bên một cột mốc biên giới Cao Bằng. Giữa hai mốc ấy là cả một hành trình qua nhiều châu lục, với đôi bàn tay trắng và một ý chí không đổi.","bia":{"src":"textures/bai/G00_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Cuộc trò chuyện ở Sài Gòn","text":"Theo cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên, những ngày ở Sài Gòn năm 1911, anh Ba rủ một người bạn trẻ tên Lê cùng ra nước ngoài. Anh hỏi bạn có yêu nước không, có giữ được bí mật không, rồi mới nói rõ ý định của mình. Người bạn băn khoăn không biết lấy đâu ra tiền mà đi. Anh Ba giơ hai bàn tay lên và nói: “Đây, tiền đây”. Anh giải thích rằng họ sẽ làm bất cứ việc gì để sống và để đi. Theo lời kể ấy, người bạn cuối cùng không đủ can đảm lên đường, và anh Ba ra đi một mình.\n\nMẩu đối thoại ngắn tóm gọn cả hành trang của người ra đi. Không tiền bạc, không người đỡ đầu, không giấy tờ bảo trợ, chỉ có đôi bàn tay lao động, vốn tiếng Pháp học được ở trường Đông Ba, trường Quốc học và một mục đích rõ ràng. Năm ấy, người thanh niên vừa tròn hai mươi mốt tuổi. Người cha đã bị cách chức tri huyện từ năm trước, gia đình không còn chỗ dựa. Anh chọn con đường khó nhất: tự đi, tự làm, tự học.","doc":1},{"loai":"trich","text":"Tôi muốn đi ra ngoài, xem nước Pháp và các nước khác. Sau khi xem xét họ làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta.","nguoi":"Nguyễn Tất Thành, theo lời kể của Trần Dân Tiên","nguon_ten":"Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","doc":2},{"loai":"doan","tieu_de":"Vì sao lại là phương Tây","text":"Đầu thế kỷ XX, những người Việt yêu nước đã thử nhiều con đường. Phong trào Đông Du của Phan Bội Châu đưa thanh niên sang Nhật Bản học tập, mong dựa vào nước Nhật để đánh Pháp. Phan Châu Trinh chủ trương duy tân, mở mang dân trí, mong nhà cầm quyền Pháp cải cách. Ở vùng rừng núi Yên Thế, nghĩa quân Hoàng Hoa Thám kiên trì cầm súng. Người thanh niên Nguyễn Tất Thành khâm phục các bậc tiền bối, nhưng không đi theo con đường nào trong số đó.\n\nAnh muốn tận mắt nhìn thấy nước Pháp. Năm 1923, trò chuyện với nhà thơ Osip Mandelstam ở Moskva, Người kể rằng khoảng mười ba tuổi đã lần đầu nghe ba chữ Pháp tự do, bình đẳng, bác ái. Từ đó, Người muốn tìm hiểu nền văn minh Pháp, xem những gì ẩn giấu đằng sau những chữ ấy. Người thanh niên muốn biết vì sao một đất nước nói nhiều về tự do lại đi cai trị dân tộc khác. Người muốn hiểu kẻ đang cai trị dân tộc mình từ bên trong. Vì thế, anh chọn đi về phía Tây, đến tận nơi xuất phát của chế độ thuộc địa.","doc":3},{"loai":"anh","src":"textures/bang_w/G00_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời hứa năm 1911 và ngày trở về 1941”, nhìn từ xa."},{"loai":"doan","tieu_de":"Đôi bàn tay trên những con tàu","text":"Ngày 5/6/1911, tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis rời cảng Sài Gòn, mang theo người phụ bếp Văn Ba. Trần Dân Tiên kể lại công việc nặng nhọc từ sáng sớm đến tối mịt: quét dọn nhà bếp, nhóm lò, khuân than, xuống hầm lấy thực phẩm giữa những cơn sóng lớn. Tàu ghé Singapore, Colombo, Port Said, rồi cập cảng Marseille ngày 6/7/1911. Theo Trần Dân Tiên, lần đầu đặt chân lên đất Pháp, người thanh niên nhận ra ở chính nước Pháp cũng có người nghèo khổ. Anh cũng thấy nhiều người Pháp ở chính quốc tử tế, lịch sự hơn những kẻ thực dân ở Đông Dương.\n\nNhững năm sau đó, Người làm đủ nghề để sống và học hỏi. Người làm phụ bếp trên tàu biển, làm thuê ở Mỹ, cào tuyết, đốt lò, phụ bếp khách sạn ở Anh, rồi sửa ảnh và vẽ thuê ở Paris. Những năm lao động ấy giúp người thanh niên xứ thuộc địa hiểu rằng ở đâu người lao động nghèo cũng bị áp bức. Nỗi khổ của người Việt nằm trong nỗi khổ chung của các dân tộc thuộc địa, và con đường giải phóng cũng phải tìm trong mối liên hệ ấy.","doc":4},{"loai":"doan","tieu_de":"Ba mươi năm không về","text":"Suốt ba mươi năm ấy, người con xứ Nghệ không một lần được trở về quê hương. Tin nhà đến với Người thưa thớt và muộn màng. Năm 1929, người cha Nguyễn Sinh Sắc qua đời ở Cao Lãnh, vùng Đồng Tháp Mười, khi người con trai đang hoạt động bí mật ở nước ngoài. Người chị Nguyễn Thị Thanh và người anh Nguyễn Sinh Khiêm đều từng bị thực dân bắt giam, tù đày vì hoạt động yêu nước. Mật thám Pháp theo dõi ráo riết từng bước đi của Nguyễn Ái Quốc, khiến con đường về nước luôn đầy hiểm nguy.\n\nNhưng xa quê không có nghĩa là xa đất nước. Từ Paris, Người viết báo tố cáo tội ác của chế độ thực dân ở Đông Dương. Từ Quảng Châu, Người đào tạo những lớp thanh niên rồi đưa họ trở về nước hoạt động. Từ Hương Cảng, Người thống nhất các tổ chức cộng sản trong nước thành một Đảng. Ở vùng Đông Bắc Xiêm, Người sống giữa kiều bào bên bờ sông Mê Kông, bên kia là đất Lào, xa hơn là dãy Trường Sơn và quê hương. Mỗi bước đi đều hướng về một điểm: ngày được trở về trực tiếp lãnh đạo cách mạng trong nước.","doc":5},{"loai":"anh","src":"textures/bai/G00_v4.jpg","chu_thich":"Không gian 3D tái hiện Sảnh Hành trình, với các vòm cửa dẫn tới những chặng đường xa xứ của Người.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Đường về vòng qua phương Bắc","text":"Cuối năm 1938, Người rời Liên Xô trở lại Trung Quốc, bắt đầu tìm đường về gần biên giới. Tháng 6/1940, nước Pháp đầu hàng phát xít Đức. Theo hồi ký của Đại tướng Võ Nguyên Giáp, Người nhận định Pháp mất nước là cơ hội rất thuận lợi cho cách mạng Việt Nam. Người dặn phải tìm mọi cách về nước ngay, vì chậm trễ lúc này là có tội với cách mạng. Cuối năm 1940, Người đến vùng Tĩnh Tây, tỉnh Quảng Tây, sát biên giới Cao Bằng.\n\nNhững tuần trước khi về nước, tại Nậm Quang bên kia biên giới, Người mở lớp huấn luyện chính trị cho 43 cán bộ để chuẩn bị đưa về hoạt động. Người chọn Cao Bằng làm nơi đặt chân đầu tiên. Đây là vùng có phong trào cách mạng tốt từ trước, lại sát biên giới, thuận lợi cho việc liên lạc quốc tế và rút lui khi cần. Những ngày cuối năm Canh Thìn, mọi việc chuẩn bị cho chuyến trở về đã sẵn sàng. Mùa xuân Tân Tỵ năm ấy sẽ là mùa xuân đầu tiên sau gần ba mươi năm Người được sống trên đất nước mình.","doc":6},{"loai":"doan","tieu_de":"Ngày mồng 2 Tết Tân Tỵ","text":"Ngày 28/1/1941, tức mồng 2 Tết Tân Tỵ, Nguyễn Ái Quốc cùng năm đồng chí vượt biên giới Việt – Trung ở cột mốc 108, đặt chân lên đất Pác Bó, huyện Hà Quảng, tỉnh Cao Bằng. Người thanh niên hai mươi mốt tuổi năm nào giờ đã năm mươi tuổi. Người đã đi qua nhiều châu lục, đã tìm thấy con đường cứu nước và sáng lập Đảng Cộng sản Việt Nam. Những ngày đầu, từ ngày 28/1 đến ngày 7/2/1941, Người ở nhà ông Lý Quốc Súng trong bản Pác Bó.\n\nNgày 8/2/1941, Người chuyển vào hang Cốc Bó, một hang đá rộng khoảng tám mươi mét vuông sát biên giới. Người đặt tên cho dòng suối trong vắt trước hang là suối Lênin và ngọn núi bên cạnh là núi Các Mác. Hằng ngày, Người làm việc bên một phiến đá cạnh suối, dịch sách, viết tài liệu huấn luyện, soạn bài cho cán bộ. Đến giữa tháng 3/1941, Người chuyển sang ở lán Khuổi Nặm gần đó. Cuộc sống thiếu thốn, ẩm thấp, nhưng Người vẫn giữ nếp sinh hoạt đều đặn và tinh thần lạc quan.","doc":7},{"loai":"trich","text":"Sáng ra bờ suối, tối vào hang, / Cháo bẹ rau măng vẫn sẵn sàng. / Bàn đá chông chênh dịch sử Đảng, / Cuộc đời cách mạng thật là sang.","nguoi":"Hồ Chí Minh","nguon_ten":"Bài thơ “Tức cảnh Pác Bó”, 1941","doc":8},{"loai":"ban_co_biet","text":"Ở Pác Bó, Người soạn tập diễn ca “Lịch sử nước ta” bằng thơ lục bát, mở đầu bằng hai câu “Dân ta phải biết sử ta / Cho tường gốc tích nước nhà Việt Nam”. Tập sách được Việt Minh ấn hành đầu năm 1942. Cuối sách, trong bảng những năm quan trọng, Người ghi một dòng như lời tiên đoán: “1945 Việt Nam độc lập”.","nguon_ten":"Hồ Chí Minh Toàn tập, tập 3; Khu di tích Pác Bó","doc":9},{"loai":"anh","src":"textures/bang_w/G00_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời hứa năm 1911 và ngày trở về 1941”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ hang đá, một mặt trận ra đời","text":"Chỉ hơn ba tháng sau ngày về nước, từ ngày 10 đến ngày 19/5/1941, Người chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng tại lán Khuổi Nặm. Hội nghị đặt nhiệm vụ giải phóng dân tộc lên hàng đầu và quyết định thành lập Việt Nam Độc lập Đồng minh, gọi tắt là Việt Minh. Mặt trận ra đời ngày 19/5/1941, đúng ngày Người tròn năm mươi mốt tuổi. Ngày 6/6/1941, Người viết thư “Kính cáo đồng bào”, ký tên Nguyễn Ái Quốc. Trong thư, Người kêu gọi mọi tầng lớp đồng bào đoàn kết lại, bởi việc cứu quốc là việc chung, ai là người Việt Nam cũng phải gánh vác một phần trách nhiệm.\n\nNgày 1/8/1941, số đầu tiên của báo Việt Nam Độc lập ra đời ở Pác Bó. Tờ báo in đá, khổ nhỏ, viết bằng lời lẽ giản dị để đồng bào các dân tộc đọc là hiểu. Người còn viết nhiều bài ca, bài vè theo thể thơ dân gian để tuyên truyền cách mạng. Từ một hang đá nơi đầu nguồn, những sợi dây liên lạc đầu tiên của cuộc Tổng khởi nghĩa bắt đầu được giăng ra khắp các tỉnh.","doc":10},{"loai":"doan","tieu_de":"Một vòng tròn khép lại","text":"Đặt hai mốc 1911 và 1941 cạnh nhau, ta thấy một vòng tròn trọn vẹn. Người ra đi từ bến cảng phương Nam và trở về ở vùng biên cương phương Bắc. Người ra đi với tên một người phụ bếp và trở về với tư cách người lãnh đạo cách mạng. Người ra đi bằng đường biển, trên một con tàu viễn dương, và trở về bằng đôi chân, qua một lối mòn giữa núi đá. Nhưng lời hứa ở Sài Gòn năm 1911 không chỉ là trở về quê hương, mà là trở về “giúp đồng bào”.\n\nBốn năm sau ngày về Pác Bó, lời hứa ấy được thực hiện bằng buổi chiều 2/9/1945 ở Quảng trường Ba Đình, khi Người đọc bản Tuyên ngôn Độc lập (xem chuyên đề Sảnh Hành trình). Ngay cả khi đã là Chủ tịch nước, Người vẫn chưa về thăm quê nội. Người đi khắp các tỉnh, các vùng kháng chiến, còn làng Sen phải đợi thêm nhiều năm nữa. Với Người, trở về giúp đồng bào là trở về với cả đất nước, chứ không riêng một mái nhà.","doc":11},{"loai":"ban_co_biet","text":"Tháng 6/1957, Chủ tịch Hồ Chí Minh mới về thăm quê nội làng Sen lần đầu tiên sau hơn năm mươi năm xa cách, khi cha mẹ, anh chị của Người đều đã qua đời.","nguon_ten":"Khu Di tích Kim Liên; Hồ Chí Minh – Biên niên tiểu sử","doc":12},{"loai":"anh","src":"textures/bang_w/G00_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời hứa năm 1911 và ngày trở về 1941”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hai đầu của vòng tròn ấy hôm nay đều là nơi lưu giữ ký ức. Ở Thành phố Hồ Chí Minh, tòa nhà Nhà Rồng bên sông Sài Gòn, trụ sở cũ của hãng tàu Messageries Maritimes, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Các phòng trưng bày ở đây kể lại những năm tháng Người ở Sài Gòn và cuộc ra đi năm 1911. Khách tham quan có thể đứng trên bến cảng xưa, nhìn ra dòng sông mà con tàu đã xuôi ra biển.\n\nỞ Cao Bằng, Khu di tích Pác Bó được Thủ tướng Chính phủ xếp hạng di tích quốc gia đặc biệt ngày 10/5/2012. Cột mốc 108 năm xưa nay mang số hiệu 675. Hang Cốc Bó, suối Lênin, núi Các Mác, lán Khuổi Nặm vẫn còn đó giữa núi rừng biên cương. Người rời Pác Bó ngày 4/5/1945 để về Tân Trào, chuẩn bị cho cuộc Tổng khởi nghĩa. Giữa hai địa danh cách nhau gần trọn chiều dài đất nước là ba mươi năm của một lời hứa được giữ trọn.","doc":13}],"nguon":["Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia Sự thật","Cục Di sản văn hóa – Di tích lịch sử Pác Bó: https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Võ Nguyên Giáp, Những chặng đường lịch sử (hồi ký)","Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh"],"doc":[{"t":"“Tôi sẽ trở về giúp đồng bào”: ba mươi năm giữ một lời hứa. Theo Trần Dân Tiên, năm 1911, trước khi xuống tàu, người thanh niên Nguyễn Tất Thành nói với một người bạn rằng anh muốn ra nước ngoài xem người ta làm thế nào, rồi sẽ trở về giúp đồng bào. Ba mươi năm sau, vào ngày mồng 2 Tết Tân Tỵ, lời hứa ấy thành hiện thực bên một cột mốc biên giới Cao Bằng. Giữa hai mốc ấy là cả một hành trình qua nhiều châu lục, với đôi bàn tay trắng và một ý chí không đổi."},{"t":"Cuộc trò chuyện ở Sài Gòn. Theo cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên, những ngày ở Sài Gòn năm 1911, anh Ba rủ một người bạn trẻ tên Lê cùng ra nước ngoài. Anh hỏi bạn có yêu nước không, có giữ được bí mật không, rồi mới nói rõ ý định của mình. Người bạn băn khoăn không biết lấy đâu ra tiền mà đi. Anh Ba giơ hai bàn tay lên và nói: “Đây, tiền đây”. Anh giải thích rằng họ sẽ làm bất cứ việc gì để sống và để đi. Theo lời kể ấy, người bạn cuối cùng không đủ can đảm lên đường, và anh Ba ra đi một mình. Mẩu đối thoại ngắn tóm gọn cả hành trang của người ra đi. Không tiền bạc, không người đỡ đầu, không giấy tờ bảo trợ, chỉ có đôi bàn tay lao động, vốn tiếng Pháp học được ở trường Đông Ba, trường Quốc học và một mục đích rõ ràng. Năm ấy, người thanh niên vừa tròn hai mươi mốt tuổi. Người cha đã bị cách chức tri huyện từ năm trước, gia đình không còn chỗ dựa. Anh chọn con đường khó nhất: tự đi, tự làm, tự học."},{"t":"Tôi muốn đi ra ngoài, xem nước Pháp và các nước khác. Sau khi xem xét họ làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta. — Nguyễn Tất Thành, theo lời kể của Trần Dân Tiên"},{"t":"Vì sao lại là phương Tây. Đầu thế kỷ XX, những người Việt yêu nước đã thử nhiều con đường. Phong trào Đông Du của Phan Bội Châu đưa thanh niên sang Nhật Bản học tập, mong dựa vào nước Nhật để đánh Pháp. Phan Châu Trinh chủ trương duy tân, mở mang dân trí, mong nhà cầm quyền Pháp cải cách. Ở vùng rừng núi Yên Thế, nghĩa quân Hoàng Hoa Thám kiên trì cầm súng. Người thanh niên Nguyễn Tất Thành khâm phục các bậc tiền bối, nhưng không đi theo con đường nào trong số đó. Anh muốn tận mắt nhìn thấy nước Pháp. Năm 1923, trò chuyện với nhà thơ Osip Mandelstam ở Moskva, Người kể rằng khoảng mười ba tuổi đã lần đầu nghe ba chữ Pháp tự do, bình đẳng, bác ái. Từ đó, Người muốn tìm hiểu nền văn minh Pháp, xem những gì ẩn giấu đằng sau những chữ ấy. Người thanh niên muốn biết vì sao một đất nước nói nhiều về tự do lại đi cai trị dân tộc khác. Người muốn hiểu kẻ đang cai trị dân tộc mình từ bên trong. Vì thế, anh chọn đi về phía Tây, đến tận nơi xuất phát của chế độ thuộc địa."},{"t":"Đôi bàn tay trên những con tàu. Ngày 5/6/1911, tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis rời cảng Sài Gòn, mang theo người phụ bếp Văn Ba. Trần Dân Tiên kể lại công việc nặng nhọc từ sáng sớm đến tối mịt: quét dọn nhà bếp, nhóm lò, khuân than, xuống hầm lấy thực phẩm giữa những cơn sóng lớn. Tàu ghé Singapore, Colombo, Port Said, rồi cập cảng Marseille ngày 6/7/1911. Theo Trần Dân Tiên, lần đầu đặt chân lên đất Pháp, người thanh niên nhận ra ở chính nước Pháp cũng có người nghèo khổ. Anh cũng thấy nhiều người Pháp ở chính quốc tử tế, lịch sự hơn những kẻ thực dân ở Đông Dương. Những năm sau đó, Người làm đủ nghề để sống và học hỏi. Người làm phụ bếp trên tàu biển, làm thuê ở Mỹ, cào tuyết, đốt lò, phụ bếp khách sạn ở Anh, rồi sửa ảnh và vẽ thuê ở Paris. Những năm lao động ấy giúp người thanh niên xứ thuộc địa hiểu rằng ở đâu người lao động nghèo cũng bị áp bức. Nỗi khổ của người Việt nằm trong nỗi khổ chung của các dân tộc thuộc địa, và con đường giải phóng cũng phải tìm trong mối liên hệ ấy."},{"t":"Ba mươi năm không về. Suốt ba mươi năm ấy, người con xứ Nghệ không một lần được trở về quê hương. Tin nhà đến với Người thưa thớt và muộn màng. Năm 1929, người cha Nguyễn Sinh Sắc qua đời ở Cao Lãnh, vùng Đồng Tháp Mười, khi người con trai đang hoạt động bí mật ở nước ngoài. Người chị Nguyễn Thị Thanh và người anh Nguyễn Sinh Khiêm đều từng bị thực dân bắt giam, tù đày vì hoạt động yêu nước. Mật thám Pháp theo dõi ráo riết từng bước đi của Nguyễn Ái Quốc, khiến con đường về nước luôn đầy hiểm nguy. Nhưng xa quê không có nghĩa là xa đất nước. Từ Paris, Người viết báo tố cáo tội ác của chế độ thực dân ở Đông Dương. Từ Quảng Châu, Người đào tạo những lớp thanh niên rồi đưa họ trở về nước hoạt động. Từ Hương Cảng, Người thống nhất các tổ chức cộng sản trong nước thành một Đảng. Ở vùng Đông Bắc Xiêm, Người sống giữa kiều bào bên bờ sông Mê Kông, bên kia là đất Lào, xa hơn là dãy Trường Sơn và quê hương. Mỗi bước đi đều hướng về một điểm: ngày được trở về trực tiếp lãnh đạo cách mạng trong nước."},{"t":"Đường về vòng qua phương Bắc. Cuối năm 1938, Người rời Liên Xô trở lại Trung Quốc, bắt đầu tìm đường về gần biên giới. Tháng 6/1940, nước Pháp đầu hàng phát xít Đức. Theo hồi ký của Đại tướng Võ Nguyên Giáp, Người nhận định Pháp mất nước là cơ hội rất thuận lợi cho cách mạng Việt Nam. Người dặn phải tìm mọi cách về nước ngay, vì chậm trễ lúc này là có tội với cách mạng. Cuối năm 1940, Người đến vùng Tĩnh Tây, tỉnh Quảng Tây, sát biên giới Cao Bằng. Những tuần trước khi về nước, tại Nậm Quang bên kia biên giới, Người mở lớp huấn luyện chính trị cho 43 cán bộ để chuẩn bị đưa về hoạt động. Người chọn Cao Bằng làm nơi đặt chân đầu tiên. Đây là vùng có phong trào cách mạng tốt từ trước, lại sát biên giới, thuận lợi cho việc liên lạc quốc tế và rút lui khi cần. Những ngày cuối năm Canh Thìn, mọi việc chuẩn bị cho chuyến trở về đã sẵn sàng. Mùa xuân Tân Tỵ năm ấy sẽ là mùa xuân đầu tiên sau gần ba mươi năm Người được sống trên đất nước mình."},{"t":"Ngày mồng 2 Tết Tân Tỵ. Ngày 28/1/1941, tức mồng 2 Tết Tân Tỵ, Nguyễn Ái Quốc cùng năm đồng chí vượt biên giới Việt – Trung ở cột mốc 108, đặt chân lên đất Pác Bó, huyện Hà Quảng, tỉnh Cao Bằng. Người thanh niên hai mươi mốt tuổi năm nào giờ đã năm mươi tuổi. Người đã đi qua nhiều châu lục, đã tìm thấy con đường cứu nước và sáng lập Đảng Cộng sản Việt Nam. Những ngày đầu, từ ngày 28/1 đến ngày 7/2/1941, Người ở nhà ông Lý Quốc Súng trong bản Pác Bó. Ngày 8/2/1941, Người chuyển vào hang Cốc Bó, một hang đá rộng khoảng tám mươi mét vuông sát biên giới. Người đặt tên cho dòng suối trong vắt trước hang là suối Lênin và ngọn núi bên cạnh là núi Các Mác. Hằng ngày, Người làm việc bên một phiến đá cạnh suối, dịch sách, viết tài liệu huấn luyện, soạn bài cho cán bộ. Đến giữa tháng 3/1941, Người chuyển sang ở lán Khuổi Nặm gần đó. Cuộc sống thiếu thốn, ẩm thấp, nhưng Người vẫn giữ nếp sinh hoạt đều đặn và tinh thần lạc quan."},{"t":"Sáng ra bờ suối, tối vào hang, / Cháo bẹ rau măng vẫn sẵn sàng. / Bàn đá chông chênh dịch sử Đảng, / Cuộc đời cách mạng thật là sang. — Hồ Chí Minh"},{"t":"Bạn có biết? Ở Pác Bó, Người soạn tập diễn ca “Lịch sử nước ta” bằng thơ lục bát, mở đầu bằng hai câu “Dân ta phải biết sử ta / Cho tường gốc tích nước nhà Việt Nam”. Tập sách được Việt Minh ấn hành đầu năm 1942. Cuối sách, trong bảng những năm quan trọng, Người ghi một dòng như lời tiên đoán: “1945 Việt Nam độc lập”."},{"t":"Từ hang đá, một mặt trận ra đời. Chỉ hơn ba tháng sau ngày về nước, từ ngày 10 đến ngày 19/5/1941, Người chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng tại lán Khuổi Nặm. Hội nghị đặt nhiệm vụ giải phóng dân tộc lên hàng đầu và quyết định thành lập Việt Nam Độc lập Đồng minh, gọi tắt là Việt Minh. Mặt trận ra đời ngày 19/5/1941, đúng ngày Người tròn năm mươi mốt tuổi. Ngày 6/6/1941, Người viết thư “Kính cáo đồng bào”, ký tên Nguyễn Ái Quốc. Trong thư, Người kêu gọi mọi tầng lớp đồng bào đoàn kết lại, bởi việc cứu quốc là việc chung, ai là người Việt Nam cũng phải gánh vác một phần trách nhiệm. Ngày 1/8/1941, số đầu tiên của báo Việt Nam Độc lập ra đời ở Pác Bó. Tờ báo in đá, khổ nhỏ, viết bằng lời lẽ giản dị để đồng bào các dân tộc đọc là hiểu. Người còn viết nhiều bài ca, bài vè theo thể thơ dân gian để tuyên truyền cách mạng. Từ một hang đá nơi đầu nguồn, những sợi dây liên lạc đầu tiên của cuộc Tổng khởi nghĩa bắt đầu được giăng ra khắp các tỉnh."},{"t":"Một vòng tròn khép lại. Đặt hai mốc 1911 và 1941 cạnh nhau, ta thấy một vòng tròn trọn vẹn. Người ra đi từ bến cảng phương Nam và trở về ở vùng biên cương phương Bắc. Người ra đi với tên một người phụ bếp và trở về với tư cách người lãnh đạo cách mạng. Người ra đi bằng đường biển, trên một con tàu viễn dương, và trở về bằng đôi chân, qua một lối mòn giữa núi đá. Nhưng lời hứa ở Sài Gòn năm 1911 không chỉ là trở về quê hương, mà là trở về “giúp đồng bào”. Bốn năm sau ngày về Pác Bó, lời hứa ấy được thực hiện bằng buổi chiều 2/9/1945 ở Quảng trường Ba Đình, khi Người đọc bản Tuyên ngôn Độc lập (xem chuyên đề Sảnh Hành trình). Ngay cả khi đã là Chủ tịch nước, Người vẫn chưa về thăm quê nội. Người đi khắp các tỉnh, các vùng kháng chiến, còn làng Sen phải đợi thêm nhiều năm nữa. Với Người, trở về giúp đồng bào là trở về với cả đất nước, chứ không riêng một mái nhà."},{"t":"Bạn có biết? Tháng 6/1957, Chủ tịch Hồ Chí Minh mới về thăm quê nội làng Sen lần đầu tiên sau hơn năm mươi năm xa cách, khi cha mẹ, anh chị của Người đều đã qua đời."},{"t":"Dấu tích hôm nay. Hai đầu của vòng tròn ấy hôm nay đều là nơi lưu giữ ký ức. Ở Thành phố Hồ Chí Minh, tòa nhà Nhà Rồng bên sông Sài Gòn, trụ sở cũ của hãng tàu Messageries Maritimes, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Các phòng trưng bày ở đây kể lại những năm tháng Người ở Sài Gòn và cuộc ra đi năm 1911. Khách tham quan có thể đứng trên bến cảng xưa, nhìn ra dòng sông mà con tàu đã xuôi ra biển. Ở Cao Bằng, Khu di tích Pác Bó được Thủ tướng Chính phủ xếp hạng di tích quốc gia đặc biệt ngày 10/5/2012. Cột mốc 108 năm xưa nay mang số hiệu 675. Hang Cốc Bó, suối Lênin, núi Các Mác, lán Khuổi Nặm vẫn còn đó giữa núi rừng biên cương. Người rời Pác Bó ngày 4/5/1945 để về Tân Trào, chuẩn bị cho cuộc Tổng khởi nghĩa. Giữa hai địa danh cách nhau gần trọn chiều dài đất nước là ba mươi năm của một lời hứa được giữ trọn."}],"so_chu":2053},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Ba mươi hai mốc son trên hành trình 79 năm","sapo":"Từ làng Hoàng Trù năm 1890 đến Nhà 67 trong khu Phủ Chủ tịch năm 1969, ba mươi hai mốc thời gian dưới đây là xương sống của cả bảo tàng. Có quãng ba mươi năm chỉ lác đác vài mốc, có tháng tám năm 1945 dồn dập những sự kiện đổi thay vận nước. Nhiều mốc trong số ấy nay đã thành ngày lễ của cả dân tộc.","bia":{"src":"textures/bai/G00_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Đọc dòng thời gian thế nào","text":"Dòng thời gian dưới đây chọn ba mươi hai mốc đã được ghi nhận trong bộ “Hồ Chí Minh – Biên niên tiểu sử” do Nhà xuất bản Chính trị quốc gia ấn hành. Bộ sách nhiều tập ấy ghi lại hoạt động của Người theo từng năm, từng tháng, có khi từng ngày. Nguồn của nó là văn kiện, báo chí, hồ sơ lưu trữ trong và ngoài nước, cùng hồi ức của các nhân chứng. Mỗi mốc trong dòng thời gian gắn với một nơi chốn, và mỗi nơi chốn là một gian trong bảo tàng này.\n\nHãy để ý hai nhịp khác nhau của dòng thời gian. Quãng từ năm 1911 đến năm 1941 kéo dài ba mươi năm nhưng các mốc thưa hơn, vì Người sống và hoạt động bí mật ở nước ngoài. Từ năm 1941 trở đi, các mốc dồn dập hơn, vì mỗi quyết định của Người lúc này gắn trực tiếp với vận mệnh của cả dân tộc. Đọc chậm từng mốc, người xem sẽ thấy cả một đời người hiện lên như một con đường liền mạch.","doc":1},{"loai":"moc","items":[["19/5/1890","Sinh tại làng Hoàng Trù, quê ngoại, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An; tên khai sinh là Nguyễn Sinh Cung."],["1895","Theo cha mẹ vào kinh thành Huế lần thứ nhất, khi người cha vào kinh chuẩn bị dự kỳ thi Hội."],["1901","Mẹ là bà Hoàng Thị Loan mất ở Huế; cha đỗ Phó bảng; gia đình về làng Sen, cậu mang tên Nguyễn Tất Thành."],["1906","Theo cha vào Huế lần thứ hai; học trường tiểu học Pháp – Việt Đông Ba, sau đó vào Trường Quốc học Huế."],["1908","Tham gia phong trào chống thuế của nông dân Trung Kỳ tại Huế, làm phiên dịch cho đồng bào."],["1910","Dạy chữ Hán và chữ quốc ngữ tại trường Dục Thanh, Phan Thiết; đầu năm 1911 vào Sài Gòn."],["5/6/1911","Với tên Văn Ba, rời bến cảng Nhà Rồng trên tàu Amiral Latouche-Tréville, ra đi tìm đường cứu nước."],["6/7/1911","Tàu cập cảng Marseille; người thanh niên lần đầu đặt chân lên đất Pháp."],["Khoảng 1912 – 1917","Sang Mỹ, rồi sang Anh, làm nhiều nghề để sống và học hỏi; cuối năm 1917 trở lại Pháp."],["18/6/1919","Ký tên Nguyễn Ái Quốc dưới bản Yêu sách của nhân dân An Nam gửi Hội nghị Versailles."],["7/1920","Đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin, tìm thấy con đường cứu nước."],["12/1920","Tại Đại hội Tours, bỏ phiếu tán thành gia nhập Quốc tế Cộng sản, tham gia sáng lập Đảng Cộng sản Pháp."],["6/1923","Bí mật rời Paris sang Liên Xô, làm việc trong Quốc tế Cộng sản."],["11/11/1924","Đến Quảng Châu, lấy tên Lý Thụy, chuẩn bị thành lập tổ chức cách mạng cho thanh niên Việt Nam."],["6/1925","Thành lập Hội Việt Nam Cách mạng Thanh niên; ngày 21/6/1925 ra số đầu tiên báo Thanh niên."],["7/1928","Đến vùng Đông Bắc Xiêm, hoạt động trong cộng đồng kiều bào với tên Thầu Chín."],["6/1 – 7/2/1930","Chủ trì hội nghị hợp nhất các tổ chức cộng sản tại Cửu Long, Hương Cảng, thành lập Đảng Cộng sản Việt Nam."],["6/6/1931","Bị cảnh sát Anh bắt ở Hồng Kông với tên Tống Văn Sơ; gần hai năm sau được trả tự do."],["1934 – 1938","Học tập và nghiên cứu ở Moskva; cuối năm 1938 trở lại Trung Quốc, tìm đường về nước."],["28/1/1941","Vượt cột mốc 108 về nước, sống và làm việc ở Pác Bó, huyện Hà Quảng, tỉnh Cao Bằng."],["19/5/1941","Kết thúc Hội nghị Trung ương lần thứ tám do Người chủ trì; Mặt trận Việt Minh ra đời."],["8/1942 – 9/1943","Lấy tên Hồ Chí Minh, sang Trung Quốc; từ ngày 29/8/1942 bị giam giữ hơn một năm ở Quảng Tây, viết Ngục trung nhật ký."],["22/12/1944","Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập theo chỉ thị của Người."],["16/8/1945","Quốc dân Đại hội Tân Trào bầu Ủy ban Dân tộc giải phóng Việt Nam do Người làm Chủ tịch."],["2/9/1945","Đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, khai sinh nước Việt Nam Dân chủ Cộng hòa."],["19/12/1946","Ra Lời kêu gọi toàn quốc kháng chiến; sau đó lên chiến khu Việt Bắc lãnh đạo cuộc kháng chiến."],["7/5/1954","Chiến dịch Điện Biên Phủ toàn thắng, mở đường cho Hiệp định Genève về Đông Dương."],["10/10/1954","Thủ đô Hà Nội được giải phóng; ít lâu sau Người trở về Hà Nội, làm việc trong khu Phủ Chủ tịch."],["5/1958","Chuyển sang ở và làm việc tại ngôi nhà sàn trong khu Phủ Chủ tịch."],["10/5/1965","Bắt đầu viết Di chúc; những năm sau tiếp tục bổ sung, sửa chữa."],["2/9/1969","Từ trần lúc 9 giờ 47 phút tại Nhà 67 trong khu Phủ Chủ tịch, hưởng thọ 79 tuổi."],["9/9/1969","Lễ truy điệu tại Quảng trường Ba Đình; bản Di chúc được công bố trước toàn dân."]],"doc":2},{"loai":"anh","src":"textures/bang_w/G00_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"Hai mươi mốt năm, năm vùng đất","text":"Nhìn vào các mốc từ 1890 đến 1911, có thể thấy tuổi trẻ của Người đã là một hành trình. Trước khi rời Tổ quốc, người thanh niên đã sống và học tập ở Nghệ An, Huế, Bình Định, Phan Thiết rồi Sài Gòn. Hai lần vào Huế, năm 1895 và năm 1906, cho cậu thấy tận mắt một triều đình đã mất quyền tự chủ. Năm 1901, mất mẹ khi mới mười một tuổi, cậu sớm biết đến nỗi đau và trách nhiệm. Năm 1908, cuộc biểu tình chống thuế đưa người học trò Quốc học vào hàng ngũ những người đấu tranh.\n\nNhững mốc ấy cho thấy quyết định ra đi năm 1911 không phải là một bước ngoặt bất chợt. Đó là kết quả của hai mươi mốt năm chứng kiến cảnh nước mất, dân khổ dọc chiều dài đất nước. Người thanh niên đến bến cảng Sài Gòn với một câu hỏi đã chín muồi: phải làm gì để cứu nước, cứu dân.","doc":3},{"loai":"doan","tieu_de":"Ba mươi năm và những khoảng trống trong hồ sơ","text":"Quãng thời gian từ 1911 đến 1941 là phần khó dựng lại nhất của dòng thời gian. Người đi qua nhiều nước, đổi nhiều tên, thường xuyên phải giữ kín hành tung. Nhiều mốc của giai đoạn này được xác định nhờ hồ sơ của mật thám Pháp, báo chí đương thời, lưu trữ của Quốc tế Cộng sản và hồ sơ tòa án ở Hồng Kông. Lá đơn ngày 15/9/1911 xin vào Trường Thuộc địa hay bản Yêu sách ngày 18/6/1919 đều là những văn bản đã được tìm thấy và công bố.\n\nNhưng cũng có những quãng mà tài liệu còn thưa, như những năm Người ở Mỹ và ở Anh. Vì thế, dòng thời gian ghi những năm ấy bằng chữ “khoảng”. Cách ghi này không làm giảm giá trị của tư liệu. Ngược lại, nó cho thấy sự thận trọng của các nhà nghiên cứu, những người đến nay vẫn tiếp tục tìm thêm dấu vết của Người trong kho lưu trữ nhiều nước.","doc":4},{"loai":"ban_co_biet","text":"Bộ “Hồ Chí Minh Toàn tập” xuất bản lần thứ ba năm 2011 gồm 15 tập, sắp xếp các bài viết, bài nói, thư từ của Người theo trình tự thời gian. Đây là nguồn quan trọng để đối chiếu từng mốc trong dòng thời gian.","nguon_ten":"Hồ Chí Minh Toàn tập, xuất bản lần thứ ba, NXB Chính trị quốc gia Sự thật, 2011","doc":5},{"loai":"anh","src":"textures/bang_w/G00_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Nhịp dồn dập sau năm 1941","text":"Từ ngày về nước, nhịp của dòng thời gian thay đổi hẳn. Chỉ trong bốn năm 1941 – 1945, các mốc nối nhau liên tục: Pác Bó, Mặt trận Việt Minh, hơn một năm tù ở Quảng Tây, đội Việt Nam Tuyên truyền Giải phóng quân, Tân Trào. Riêng tháng 8/1945, chỉ trong hơn hai tuần đã diễn ra Hội nghị toàn quốc của Đảng, Quốc dân Đại hội Tân Trào và cuộc khởi nghĩa giành chính quyền ở Hà Nội ngày 19/8. Hai tuần sau đó là ngày 2/9 lịch sử.\n\nSau năm 1945, mỗi mốc thời gian gắn với một quyết định hệ trọng của cả dân tộc. Có lúc là ký kết để giữ hòa bình, có lúc là đứng lên kháng chiến, có lúc là dốc sức xây dựng và đấu tranh thống nhất đất nước. Nhìn vào khoảng cách giữa các mốc, người xem có thể hình dung sức nặng mà vị Chủ tịch nước phải gánh vác. Có những năm, như năm 1946, gần như tháng nào cũng có một quyết định hệ trọng.","doc":6},{"loai":"doan","tieu_de":"Từ mốc đời Người thành ngày lễ của đất nước","text":"Nhiều mốc trong dòng thời gian này đã trở thành ngày lễ, ngày kỷ niệm của cả nước. Ngày 19/5 là ngày sinh của Người. Ngày 5/6 được kỷ niệm là ngày Bác Hồ ra đi tìm đường cứu nước. Ngày 21/6, ngày ra số đầu tiên của báo Thanh niên năm 1925, trở thành Ngày Báo chí cách mạng Việt Nam. Ngày 3/2 được chọn làm ngày kỷ niệm thành lập Đảng Cộng sản Việt Nam, dù hội nghị hợp nhất họp từ ngày 6/1 đến ngày 7/2/1930.\n\nNgày 22/12, ngày thành lập đội Việt Nam Tuyên truyền Giải phóng quân năm 1944, là ngày thành lập Quân đội nhân dân Việt Nam. Ngày 19/12 là Ngày toàn quốc kháng chiến. Ngày 10/10 là Ngày giải phóng Thủ đô. Ngày 2/9 là ngày Quốc khánh, ngày Người đọc bản Tuyên ngôn Độc lập năm 1945. Nhiều ngày lễ lớn của nước Việt Nam hiện đại gắn trực tiếp với những mốc thời gian trong cuộc đời Người.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_1946_and_signature_cropped.jpg","chu_thich":"Chủ tịch Hồ Chí Minh năm 1946 và chữ ký của Người, năm thứ hai trong hai mươi tư năm Người đứng đầu nước Việt Nam Dân chủ Cộng hòa.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những con số của một hành trình","text":"Từ những mốc ấy có thể rút ra vài con số đáng nhớ. Người rời Tổ quốc năm hai mươi mốt tuổi và trở về năm năm mươi tuổi. Như vậy, gần ba mươi năm, hơn một phần ba cuộc đời, Người sống ở nước ngoài. Trên cương vị Chủ tịch nước, Người lãnh đạo đất nước tròn hai mươi tư năm, từ ngày 2/9/1945 đến ngày 2/9/1969. Trong đó, chín năm kháng chiến chống thực dân Pháp, Người sống và làm việc chủ yếu ở chiến khu Việt Bắc.\n\nTừ tháng 5/1958 đến những năm cuối đời, hơn mười một năm, Người sống và làm việc ở ngôi nhà sàn nhỏ bên ao cá trong khu Phủ Chủ tịch. Người bắt đầu viết Di chúc khi sắp bước sang tuổi bảy mươi lăm và còn bổ sung, sửa chữa đến năm 1969. Và Người ra đi đúng vào ngày kỷ niệm hai mươi bốn năm Quốc khánh, ngày chính Người đã đọc bản Tuyên ngôn Độc lập.","doc":8},{"loai":"doan","tieu_de":"Những ngày cuối cùng và lễ truy điệu","text":"Những mốc cuối của dòng thời gian được ghi lại tỉ mỉ đến từng giờ, từng phút. Tháng 8/1969, sức khỏe của Người suy giảm nhanh. Các bác sĩ trong nước cùng các chuyên gia y tế nước bạn tận tình cứu chữa. Người từ trần lúc 9 giờ 47 phút sáng ngày 2/9/1969 tại Nhà 67, một ngôi nhà nhỏ trong khu Phủ Chủ tịch, hưởng thọ 79 tuổi.\n\nNgày 9/9/1969, lễ truy điệu được tổ chức trọng thể tại Quảng trường Ba Đình, chính nơi Người đọc bản Tuyên ngôn Độc lập hai mươi bốn năm trước. Tại buổi lễ, bản Di chúc của Người được công bố trước toàn dân. Sáu năm sau, ngày 29/8/1975, Lăng Chủ tịch Hồ Chí Minh được khánh thành trên quảng trường ấy. Mốc thời gian cuối cùng của một đời người trở thành điểm khởi đầu cho những cuộc hành hương của nhiều thế hệ.","doc":9},{"loai":"ban_co_biet","text":"Ngày Chủ tịch Hồ Chí Minh từ trần, 2/9/1969, lúc đầu được công bố là ngày 3/9 để ngày mất không trùng với ngày Quốc khánh. Đến năm 1989, Bộ Chính trị mới công bố đính chính, xác nhận Người mất lúc 9 giờ 47 phút ngày 2/9/1969.","nguon_ten":"Thông báo của Bộ Chính trị năm 1989; Hồ Chí Minh – Biên niên tiểu sử","doc":10},{"loai":"anh","src":"textures/bang_w/G00_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay: nơi dòng thời gian được lưu giữ","text":"Người muốn đi lại dòng thời gian này có thể bắt đầu từ Bảo tàng Hồ Chí Minh ở Hà Nội, khánh thành ngày 19/5/1990, nơi phần trưng bày chính được sắp xếp theo các giai đoạn cuộc đời Người. Khu di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch còn giữ ngôi nhà sàn, Nhà 67, ao cá và những kỷ vật của mười lăm năm cuối đời. Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh công bố phần biên niên tiểu sử, cho phép tra cứu từng mốc thời gian.\n\nTrong bảo tàng này, mỗi mốc thời gian là một cánh cửa. Từ mốc năm 1890, người xem bước vào gian Làng Sen – Kim Liên. Từ mốc năm 1911, người xem đi tiếp tới Sài Gòn rồi ra biển lớn. Từ mốc năm 1941, cánh cửa mở vào Pác Bó. Và từ mốc năm 1969, người xem đến với gian Di sản, nơi hành trình của Người tiếp tục trong đời sống của những thế hệ hôm nay.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia Sự thật, 2011","Biên niên tiểu sử Hồ Chí Minh – Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh: https://hochiminh.vn/cuoc-doi-su-nghiep/bien-nien-tieu-su-ho-chi-minh","Bảo tàng Hồ Chí Minh","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch"],"doc":[{"t":"Ba mươi hai mốc son trên hành trình 79 năm. Từ làng Hoàng Trù năm 1890 đến Nhà 67 trong khu Phủ Chủ tịch năm 1969, ba mươi hai mốc thời gian dưới đây là xương sống của cả bảo tàng. Có quãng ba mươi năm chỉ lác đác vài mốc, có tháng tám năm 1945 dồn dập những sự kiện đổi thay vận nước. Nhiều mốc trong số ấy nay đã thành ngày lễ của cả dân tộc."},{"t":"Đọc dòng thời gian thế nào. Dòng thời gian dưới đây chọn ba mươi hai mốc đã được ghi nhận trong bộ “Hồ Chí Minh – Biên niên tiểu sử” do Nhà xuất bản Chính trị quốc gia ấn hành. Bộ sách nhiều tập ấy ghi lại hoạt động của Người theo từng năm, từng tháng, có khi từng ngày. Nguồn của nó là văn kiện, báo chí, hồ sơ lưu trữ trong và ngoài nước, cùng hồi ức của các nhân chứng. Mỗi mốc trong dòng thời gian gắn với một nơi chốn, và mỗi nơi chốn là một gian trong bảo tàng này. Hãy để ý hai nhịp khác nhau của dòng thời gian. Quãng từ năm 1911 đến năm 1941 kéo dài ba mươi năm nhưng các mốc thưa hơn, vì Người sống và hoạt động bí mật ở nước ngoài. Từ năm 1941 trở đi, các mốc dồn dập hơn, vì mỗi quyết định của Người lúc này gắn trực tiếp với vận mệnh của cả dân tộc. Đọc chậm từng mốc, người xem sẽ thấy cả một đời người hiện lên như một con đường liền mạch."},{"t":"Các mốc thời gian. 19/5/1890: Sinh tại làng Hoàng Trù, quê ngoại, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An; tên khai sinh là Nguyễn Sinh Cung. 1895: Theo cha mẹ vào kinh thành Huế lần thứ nhất, khi người cha vào kinh chuẩn bị dự kỳ thi Hội. 1901: Mẹ là bà Hoàng Thị Loan mất ở Huế; cha đỗ Phó bảng; gia đình về làng Sen, cậu mang tên Nguyễn Tất Thành. 1906: Theo cha vào Huế lần thứ hai; học trường tiểu học Pháp – Việt Đông Ba, sau đó vào Trường Quốc học Huế. 1908: Tham gia phong trào chống thuế của nông dân Trung Kỳ tại Huế, làm phiên dịch cho đồng bào. 1910: Dạy chữ Hán và chữ quốc ngữ tại trường Dục Thanh, Phan Thiết; đầu năm 1911 vào Sài Gòn. 5/6/1911: Với tên Văn Ba, rời bến cảng Nhà Rồng trên tàu Amiral Latouche-Tréville, ra đi tìm đường cứu nước. 6/7/1911: Tàu cập cảng Marseille; người thanh niên lần đầu đặt chân lên đất Pháp. Khoảng 1912 – 1917: Sang Mỹ, rồi sang Anh, làm nhiều nghề để sống và học hỏi; cuối năm 1917 trở lại Pháp. 18/6/1919: Ký tên Nguyễn Ái Quốc dưới bản Yêu sách của nhân dân An Nam gửi Hội nghị Versailles. 7/1920: Đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin, tìm thấy con đường cứu nước. 12/1920: Tại Đại hội Tours, bỏ phiếu tán thành gia nhập Quốc tế Cộng sản, tham gia sáng lập Đảng Cộng sản Pháp. 6/1923: Bí mật rời Paris sang Liên Xô, làm việc trong Quốc tế Cộng sản. 11/11/1924: Đến Quảng Châu, lấy tên Lý Thụy, chuẩn bị thành lập tổ chức cách mạng cho thanh niên Việt Nam. 6/1925: Thành lập Hội Việt Nam Cách mạng Thanh niên; ngày 21/6/1925 ra số đầu tiên báo Thanh niên. 7/1928: Đến vùng Đông Bắc Xiêm, hoạt động trong cộng đồng kiều bào với tên Thầu Chín. 6/1 – 7/2/1930: Chủ trì hội nghị hợp nhất các tổ chức cộng sản tại Cửu Long, Hương Cảng, thành lập Đảng Cộng sản Việt Nam. 6/6/1931: Bị cảnh sát Anh bắt ở Hồng Kông với tên Tống Văn Sơ; gần hai năm sau được trả tự do. 1934 – 1938: Học tập và nghiên cứu ở Moskva; cuối năm 1938 trở lại Trung Quốc, tìm đường về nước. 28/1/1941: Vượt cột mốc 108 về nước, sống và làm việc ở Pác Bó, huyện Hà Quảng, tỉnh Cao Bằng. 19/5/1941: Kết thúc Hội nghị Trung ương lần thứ tám do Người chủ trì; Mặt trận Việt Minh ra đời. 8/1942 – 9/1943: Lấy tên Hồ Chí Minh, sang Trung Quốc; từ ngày 29/8/1942 bị giam giữ hơn một năm ở Quảng Tây, viết Ngục trung nhật ký. 22/12/1944: Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập theo chỉ thị của Người. 16/8/1945: Quốc dân Đại hội Tân Trào bầu Ủy ban Dân tộc giải phóng Việt Nam do Người làm Chủ tịch. 2/9/1945: Đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, khai sinh nước Việt Nam Dân chủ Cộng hòa. 19/12/1946: Ra Lời kêu gọi toàn quốc kháng chiến; sau đó lên chiến khu Việt Bắc lãnh đạo cuộc kháng chiến. 7/5/1954: Chiến dịch Điện Biên Phủ toàn thắng, mở đường cho Hiệp định Genève về Đông Dương. 10/10/1954: Thủ đô Hà Nội được giải phóng; ít lâu sau Người trở về Hà Nội, làm việc trong khu Phủ Chủ tịch. 5/1958: Chuyển sang ở và làm việc tại ngôi nhà sàn trong khu Phủ Chủ tịch. 10/5/1965: Bắt đầu viết Di chúc; những năm sau tiếp tục bổ sung, sửa chữa. 2/9/1969: Từ trần lúc 9 giờ 47 phút tại Nhà 67 trong khu Phủ Chủ tịch, hưởng thọ 79 tuổi. 9/9/1969: Lễ truy điệu tại Quảng trường Ba Đình; bản Di chúc được công bố trước toàn dân."},{"t":"Hai mươi mốt năm, năm vùng đất. Nhìn vào các mốc từ 1890 đến 1911, có thể thấy tuổi trẻ của Người đã là một hành trình. Trước khi rời Tổ quốc, người thanh niên đã sống và học tập ở Nghệ An, Huế, Bình Định, Phan Thiết rồi Sài Gòn. Hai lần vào Huế, năm 1895 và năm 1906, cho cậu thấy tận mắt một triều đình đã mất quyền tự chủ. Năm 1901, mất mẹ khi mới mười một tuổi, cậu sớm biết đến nỗi đau và trách nhiệm. Năm 1908, cuộc biểu tình chống thuế đưa người học trò Quốc học vào hàng ngũ những người đấu tranh. Những mốc ấy cho thấy quyết định ra đi năm 1911 không phải là một bước ngoặt bất chợt. Đó là kết quả của hai mươi mốt năm chứng kiến cảnh nước mất, dân khổ dọc chiều dài đất nước. Người thanh niên đến bến cảng Sài Gòn với một câu hỏi đã chín muồi: phải làm gì để cứu nước, cứu dân."},{"t":"Ba mươi năm và những khoảng trống trong hồ sơ. Quãng thời gian từ 1911 đến 1941 là phần khó dựng lại nhất của dòng thời gian. Người đi qua nhiều nước, đổi nhiều tên, thường xuyên phải giữ kín hành tung. Nhiều mốc của giai đoạn này được xác định nhờ hồ sơ của mật thám Pháp, báo chí đương thời, lưu trữ của Quốc tế Cộng sản và hồ sơ tòa án ở Hồng Kông. Lá đơn ngày 15/9/1911 xin vào Trường Thuộc địa hay bản Yêu sách ngày 18/6/1919 đều là những văn bản đã được tìm thấy và công bố. Nhưng cũng có những quãng mà tài liệu còn thưa, như những năm Người ở Mỹ và ở Anh. Vì thế, dòng thời gian ghi những năm ấy bằng chữ “khoảng”. Cách ghi này không làm giảm giá trị của tư liệu. Ngược lại, nó cho thấy sự thận trọng của các nhà nghiên cứu, những người đến nay vẫn tiếp tục tìm thêm dấu vết của Người trong kho lưu trữ nhiều nước."},{"t":"Bạn có biết? Bộ “Hồ Chí Minh Toàn tập” xuất bản lần thứ ba năm 2011 gồm 15 tập, sắp xếp các bài viết, bài nói, thư từ của Người theo trình tự thời gian. Đây là nguồn quan trọng để đối chiếu từng mốc trong dòng thời gian."},{"t":"Nhịp dồn dập sau năm 1941. Từ ngày về nước, nhịp của dòng thời gian thay đổi hẳn. Chỉ trong bốn năm 1941 – 1945, các mốc nối nhau liên tục: Pác Bó, Mặt trận Việt Minh, hơn một năm tù ở Quảng Tây, đội Việt Nam Tuyên truyền Giải phóng quân, Tân Trào. Riêng tháng 8/1945, chỉ trong hơn hai tuần đã diễn ra Hội nghị toàn quốc của Đảng, Quốc dân Đại hội Tân Trào và cuộc khởi nghĩa giành chính quyền ở Hà Nội ngày 19/8. Hai tuần sau đó là ngày 2/9 lịch sử. Sau năm 1945, mỗi mốc thời gian gắn với một quyết định hệ trọng của cả dân tộc. Có lúc là ký kết để giữ hòa bình, có lúc là đứng lên kháng chiến, có lúc là dốc sức xây dựng và đấu tranh thống nhất đất nước. Nhìn vào khoảng cách giữa các mốc, người xem có thể hình dung sức nặng mà vị Chủ tịch nước phải gánh vác. Có những năm, như năm 1946, gần như tháng nào cũng có một quyết định hệ trọng."},{"t":"Từ mốc đời Người thành ngày lễ của đất nước. Nhiều mốc trong dòng thời gian này đã trở thành ngày lễ, ngày kỷ niệm của cả nước. Ngày 19/5 là ngày sinh của Người. Ngày 5/6 được kỷ niệm là ngày Bác Hồ ra đi tìm đường cứu nước. Ngày 21/6, ngày ra số đầu tiên của báo Thanh niên năm 1925, trở thành Ngày Báo chí cách mạng Việt Nam. Ngày 3/2 được chọn làm ngày kỷ niệm thành lập Đảng Cộng sản Việt Nam, dù hội nghị hợp nhất họp từ ngày 6/1 đến ngày 7/2/1930. Ngày 22/12, ngày thành lập đội Việt Nam Tuyên truyền Giải phóng quân năm 1944, là ngày thành lập Quân đội nhân dân Việt Nam. Ngày 19/12 là Ngày toàn quốc kháng chiến. Ngày 10/10 là Ngày giải phóng Thủ đô. Ngày 2/9 là ngày Quốc khánh, ngày Người đọc bản Tuyên ngôn Độc lập năm 1945. Nhiều ngày lễ lớn của nước Việt Nam hiện đại gắn trực tiếp với những mốc thời gian trong cuộc đời Người."},{"t":"Những con số của một hành trình. Từ những mốc ấy có thể rút ra vài con số đáng nhớ. Người rời Tổ quốc năm hai mươi mốt tuổi và trở về năm năm mươi tuổi. Như vậy, gần ba mươi năm, hơn một phần ba cuộc đời, Người sống ở nước ngoài. Trên cương vị Chủ tịch nước, Người lãnh đạo đất nước tròn hai mươi tư năm, từ ngày 2/9/1945 đến ngày 2/9/1969. Trong đó, chín năm kháng chiến chống thực dân Pháp, Người sống và làm việc chủ yếu ở chiến khu Việt Bắc. Từ tháng 5/1958 đến những năm cuối đời, hơn mười một năm, Người sống và làm việc ở ngôi nhà sàn nhỏ bên ao cá trong khu Phủ Chủ tịch. Người bắt đầu viết Di chúc khi sắp bước sang tuổi bảy mươi lăm và còn bổ sung, sửa chữa đến năm 1969. Và Người ra đi đúng vào ngày kỷ niệm hai mươi bốn năm Quốc khánh, ngày chính Người đã đọc bản Tuyên ngôn Độc lập."},{"t":"Những ngày cuối cùng và lễ truy điệu. Những mốc cuối của dòng thời gian được ghi lại tỉ mỉ đến từng giờ, từng phút. Tháng 8/1969, sức khỏe của Người suy giảm nhanh. Các bác sĩ trong nước cùng các chuyên gia y tế nước bạn tận tình cứu chữa. Người từ trần lúc 9 giờ 47 phút sáng ngày 2/9/1969 tại Nhà 67, một ngôi nhà nhỏ trong khu Phủ Chủ tịch, hưởng thọ 79 tuổi. Ngày 9/9/1969, lễ truy điệu được tổ chức trọng thể tại Quảng trường Ba Đình, chính nơi Người đọc bản Tuyên ngôn Độc lập hai mươi bốn năm trước. Tại buổi lễ, bản Di chúc của Người được công bố trước toàn dân. Sáu năm sau, ngày 29/8/1975, Lăng Chủ tịch Hồ Chí Minh được khánh thành trên quảng trường ấy. Mốc thời gian cuối cùng của một đời người trở thành điểm khởi đầu cho những cuộc hành hương của nhiều thế hệ."},{"t":"Bạn có biết? Ngày Chủ tịch Hồ Chí Minh từ trần, 2/9/1969, lúc đầu được công bố là ngày 3/9 để ngày mất không trùng với ngày Quốc khánh. Đến năm 1989, Bộ Chính trị mới công bố đính chính, xác nhận Người mất lúc 9 giờ 47 phút ngày 2/9/1969."},{"t":"Dấu tích hôm nay: nơi dòng thời gian được lưu giữ. Người muốn đi lại dòng thời gian này có thể bắt đầu từ Bảo tàng Hồ Chí Minh ở Hà Nội, khánh thành ngày 19/5/1990, nơi phần trưng bày chính được sắp xếp theo các giai đoạn cuộc đời Người. Khu di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch còn giữ ngôi nhà sàn, Nhà 67, ao cá và những kỷ vật của mười lăm năm cuối đời. Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh công bố phần biên niên tiểu sử, cho phép tra cứu từng mốc thời gian. Trong bảo tàng này, mỗi mốc thời gian là một cánh cửa. Từ mốc năm 1890, người xem bước vào gian Làng Sen – Kim Liên. Từ mốc năm 1911, người xem đi tiếp tới Sài Gòn rồi ra biển lớn. Từ mốc năm 1941, cánh cửa mở vào Pác Bó. Và từ mốc năm 1969, người xem đến với gian Di sản, nơi hành trình của Người tiếp tục trong đời sống của những thế hệ hôm nay."}],"so_chu":1530},{"i":4,"tieu_de_bang":"Chủ tịch Hồ Chí Minh năm 1946 và chữ ký của Người","tieu_de":"Năm 1946 qua một gương mặt và một nét bút","sapo":"Người chụp bức ảnh này không để lại tên, nhưng năm 1946 thì để lại rất nhiều dấu vết của vị Chủ tịch 56 tuổi. Có một pho tượng được nặn trong hơn hai mươi buổi sáng ở Bắc Bộ phủ, rồi nằm dưới gầm bàn thờ suốt những năm kháng chiến. Có những bản sắc lệnh còn nguyên nét mực, một trang sổ vàng ở Paris, một tấm ảnh ký tặng người họa sĩ xa quê. Lần theo chữ ký “Hồ Chí Minh”, ta đi lại một năm đầy giông bão.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_1946_and_signature_cropped.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một gương mặt, một nét bút","text":"Bức ảnh trên bảng được lưu hành rộng rãi với một chú thích ngắn: Chủ tịch Hồ Chí Minh, chụp khoảng năm 1946. Người bấm máy không để lại tên, và bức ảnh nay thuộc phạm vi công cộng, ai cũng có thể in lại. Đi cùng gương mặt ấy là chữ ký của Người, chính là ba chữ Hồ Chí Minh. Cái tên này mới được dùng từ tháng 8/1942, vậy mà chỉ vài năm sau đã đứng dưới những văn bản quyết định vận mệnh một quốc gia. Năm 1946, Người bước sang tuổi 56. Sinh nhật ngày 19 tháng 5 năm ấy rơi vào quãng bận rộn nhất, chưa đầy hai tuần trước khi Người lên đường sang Pháp.\n\nĐặt gương mặt và chữ ký cạnh nhau, bảng ảnh gợi một cách đọc lại năm 1946: không chỉ qua các sự kiện lớn, mà qua những dấu vết vật chất còn giữ được đến hôm nay. Đó là một pho tượng đồng, một tập sắc lệnh, một trang sổ vàng, một tấm ảnh ký tặng.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_1946_and_signature_cropped.jpg","chu_thich":"Chủ tịch Hồ Chí Minh, ảnh chụp khoảng năm 1946, không rõ người chụp, nay thuộc phạm vi công cộng. Năm ấy Người bước sang tuổi 56.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Năm thứ hai của nước Việt Nam mới","text":"Năm 1946 mở ra khi nước Việt Nam Dân chủ Cộng hòa mới tròn bốn tháng tuổi. Ở miền Bắc, khoảng hai mươi vạn quân Tưởng Giới Thạch đóng quân với danh nghĩa giải giáp quân Nhật, kéo theo các nhóm chính trị đối lập. Ở Nam Bộ, cuộc kháng chiến chống thực dân Pháp trở lại xâm lược đã sang tháng thứ tư. Nạn đói năm trước vừa qua, ngân khố gần như trống rỗng, phần đông dân chúng chưa biết chữ.\n\nTrong hoàn cảnh ấy, Người lần lượt nhận những trọng trách mới. Ngày 1/1/1946, Chính phủ lâm thời được mở rộng thành Chính phủ liên hiệp lâm thời. Ngày 2/3/1946, tại kỳ họp thứ nhất của Quốc hội khóa I, Người được bầu làm Chủ tịch Chính phủ Liên hiệp kháng chiến. Từ đó đến cuối năm, Người vừa điều hành việc nước, vừa đàm phán, vừa xa Tổ quốc gần năm tháng trên đường sang Pháp và trở về. Một pho tượng nặn giữa năm ấy đã giữ lại dấu vết của chúng trên gương mặt Người: nét mặt đăm chiêu, vầng trán rộng hơi nhíu lại.","doc":2},{"loai":"anh","src":"textures/bang_w/G00_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh năm 1946 và chữ ký của Người”, nhìn từ xa."},{"loai":"doan","tieu_de":"Hơn hai mươi buổi sáng ở Bắc Bộ phủ","text":"Tháng 5/1946, Ban lãnh đạo Hội Văn hóa cứu quốc cử các họa sĩ Tô Ngọc Vân, Nguyễn Đỗ Cung và Nguyễn Thị Kim đến Bắc Bộ phủ để vẽ và nặn tượng Chủ tịch Hồ Chí Minh. Bắc Bộ phủ, nay là Nhà khách Chính phủ trên phố Ngô Quyền, Hà Nội, khi ấy là nơi Người làm việc. Bà Nguyễn Thị Kim, người được coi là nữ điêu khắc gia đầu tiên của Việt Nam, được ngồi gần Người ngay trong phòng làm việc. Hơn hai mươi ngày liền, mỗi ngày hai tiếng, từ sáu giờ đến tám giờ sáng, bà quan sát và nặn.\n\nPho tượng ghi lại một tư thế rất thật: đầu hơi cúi về phía trước, thể hiện sự tập trung cao độ vào công việc. Bà nặn tượng bằng đất sét, sau đó làm khuôn thạch cao, khuôn âm bản rồi đổ đồng. Tượng đúc liền khối, rỗng ruột, cao 46 cm, rộng vai 45 cm, nặng 17 kg. Dưới vai phải, tác giả khắc chữ Hán “Kim” và dòng chữ Việt “Ng.T. Kim – 1946”, như một chữ ký của nghệ sĩ đặt cạnh chân dung vị Chủ tịch.","doc":3},{"loai":"ban_co_biet","text":"Pho tượng chân dung Chủ tịch Hồ Chí Minh năm 1946 của nhà điêu khắc Nguyễn Thị Kim đã được công nhận là bảo vật quốc gia trong đợt thứ 11, theo Quyết định số 41/QĐ-TTg ngày 30/1/2023 của Thủ tướng Chính phủ.","nguon_ten":"Bảo tàng Lịch sử quốc gia, bài “Tượng Chân dung Chủ tịch Hồ Chí Minh – năm 1946, bảo vật quốc gia”, 2/2/2023","doc":4},{"loai":"doan","tieu_de":"Pho tượng dưới gầm bàn thờ","text":"Chỉ vài tháng sau những buổi sáng ở Bắc Bộ phủ, chiến tranh lan ra cả nước. Tháng 12/1946, cũng là tháng cuộc kháng chiến toàn quốc bùng nổ, chồng bà Kim đào một cái hầm ngay dưới gầm bàn thờ họ của gia đình để chôn giấu bức tượng. Suốt những năm kháng chiến chống Pháp, gương mặt vị Chủ tịch bằng đồng nằm lặng lẽ dưới lòng đất.\n\nSau chiến thắng Điện Biên Phủ, gia đình nhà điêu khắc tìm lại đúng vị trí cất giấu và đào bức tượng lên. Năm 1959, khi Bảo tàng Cách mạng Việt Nam được thành lập, vợ chồng bà quyết định trao tặng bức tượng cho bảo tàng. Ngày nay, tượng thuộc sưu tập của Bảo tàng Lịch sử quốc gia ở Hà Nội. Qua bàn tay nhà điêu khắc, gương mặt Người hiện lên với chòm râu dài và vầng trán rộng của tuổi năm mươi sáu.","doc":5},{"loai":"doan","tieu_de":"Chữ ký tươi trên những sắc lệnh đầu tiên","text":"Nếu pho tượng giữ lại gương mặt, thì các kho lưu trữ giữ lại nét bút. Tại Trung tâm Lưu trữ quốc gia III ở Hà Nội, trong một tầng hầm sâu khoảng mười hai mét, nhiệt độ luôn được giữ trong khoảng 18 đến 22 độ C, có một tập hồ sơ đặc biệt. Đó là Tập Sắc lệnh của Chủ tịch Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa, gồm 118 sắc lệnh ban hành trong khoảng nửa năm đầu tiên của chính quyền mới, từ mùa thu 1945 sang đầu năm 1946.\n\nHơn tám mươi sắc lệnh trong đó do chính Chủ tịch Hồ Chí Minh ký; 25 sắc lệnh do Bộ trưởng Bộ Nội vụ Võ Nguyên Giáp thay mặt Chủ tịch ký. Các bản đều đánh máy, nhiều bản còn bút tích sửa chữa câu chữ, và mang chữ ký “tươi”, tức chữ ký viết tay trực tiếp của người có thẩm quyền. Nội dung là những việc nền móng: tổng tuyển cử, chống đói, chống nạn mù chữ, tổ chức bộ máy nhà nước. Trong những năm 1990, cả tập được tu bổ, gia cố bằng giấy và keo chuyên dụng. Ngày 22/12/2016, tập sắc lệnh được công nhận là bảo vật quốc gia.","doc":6},{"loai":"anh","src":"textures/bang_w/G00_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh năm 1946 và chữ ký của Người”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Trang sổ vàng Paris và tấm ảnh ký tặng","text":"Mùa hè năm 1946, chữ ký của Người theo Người sang nước Pháp. Ngày 22/6/1946, Chủ tịch Hồ Chí Minh tới Paris; mười ngày sau, chính phủ Pháp mới tổ chức lễ đón chính thức kéo dài ba ngày, từ 2 đến 4/7/1946, theo nghi thức dành cho nguyên thủ quốc gia. Ngày 4/7, tại Tòa Thị chính Paris, Người viết mười bốn dòng chữ tiếng Pháp vào sổ vàng của thành phố. Lời đề gửi tới ông Chủ tịch Hội đồng thành phố, ông Tỉnh trưởng thành Seine, ông Tỉnh trưởng cảnh sát cùng các đại diện, rồi kết thúc bằng chữ ký Hồ Chí Minh. Trang sổ dài 30 cm, rộng 23 cm ấy là tài liệu Bảo tàng Hồ Chí Minh thu thập được trong chuyến công tác nghiên cứu tại Paris cuối năm 2024.\n\nCũng năm ấy ở Paris, nhiếp ảnh gia Laure Albin Guillot, một tên tuổi của ảnh chân dung Pháp, đã chụp chân dung Người. Bức ảnh được in thành nhiều bản để Chủ tịch ký tặng kiều bào và khách mời trong các cuộc tiếp xúc. Một bản mang dòng đề tặng họa sĩ Lê Phổ: “Tặng chú Lê Phổ, Chào thân ái! Tháng 8/1946”. Chân dung kèm chữ ký từng là một cử chỉ thân tình của vị Chủ tịch nơi đất khách.","doc":7},{"loai":"ban_co_biet","text":"Năm 2015, Bảo tàng Hồ Chí Minh – Chi nhánh Gia Lai – Kon Tum giới thiệu sưu tập 79 chữ ký của Chủ tịch Hồ Chí Minh thời kỳ 1945 – 1969. Các chữ ký được chọn lọc từ hàng nghìn văn bản lưu tại Cục Văn thư và Lưu trữ nhà nước; con số 79 trùng với tuổi thọ của Người.","nguon_ten":"VietnamPlus, “Bộ sưu tập 79 chữ ký của Chủ tịch Hồ Chí Minh thời kỳ 1945 – 1969”","doc":8},{"loai":"doan","tieu_de":"Những chữ ký của sự nhân nhượng có nguyên tắc","text":"Có những chữ ký năm 1946 được đặt xuống sau những tính toán rất nặng nề. Chiều 6/3/1946, Người cùng ông Vũ Hồng Khanh ký Hiệp định Sơ bộ với đại diện Chính phủ Pháp là ông Jean Sainteny. Chữ ký ấy đổi lấy thời gian hòa hoãn và việc quân Tưởng sớm rút về nước (xem chuyên đề Ký Hiệp định Sơ bộ 6/3/1946, gian Hà Nội 1945 – Ba Đình). Sáu tháng sau, khi cuộc đàm phán ở Fontainebleau không đạt kết quả, ngày 14/9/1946 tại Paris, Người ký với Bộ trưởng Marius Moutet bản Tạm ước. Người chấp nhận nhân nhượng cho Pháp một số quyền lợi kinh tế, văn hóa để có thêm thời gian hòa bình.\n\nĐó là nhân nhượng về bước đi, không nhân nhượng về độc lập và thống nhất. Điều không bao giờ đem ra đổi chác, Người đã viết rõ trong bức thư gửi đồng bào Nam Bộ đề ngày 31/5/1946, đúng ngày Người rời Hà Nội sang Pháp. Khi ấy, Nam Bộ đã kháng chiến hơn tám tháng, và thực dân Pháp đang tìm cách tách Nam Bộ khỏi Việt Nam.","doc":9},{"loai":"trich","text":"Đồng bào Nam Bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi!","nguoi":"Hồ Chí Minh","nguon_ten":"Thư gửi đồng bào Nam Bộ, 31/5/1946","doc":10},{"loai":"doan","tieu_de":"Hiến pháp và lời kêu gọi cuối năm","text":"Ngày 20/10/1946, Người về tới Hải Phòng và lập tức trở lại với những việc lớn của cuối năm. Ngày 9/11/1946, Quốc hội thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa. Chính Người từng làm Trưởng ban dự thảo Hiến pháp gồm bảy thành viên, do Chính phủ lâm thời lập ra chỉ vài tuần sau ngày độc lập.\n\nNhưng hòa bình không giữ được lâu hơn. Thực dân Pháp liên tiếp gây hấn ở Hải Phòng, Lạng Sơn, rồi ngay giữa Hà Nội. Lời kêu gọi toàn quốc kháng chiến, được Người viết tại làng Vạn Phúc, Hà Đông, ra đời ngày 19/12/1946. Chữ ký Hồ Chí Minh dưới lời kêu gọi ấy khép lại năm 1946 bằng một quyết định không thể lùi: thà hy sinh tất cả, chứ nhất định không chịu mất nước, không chịu làm nô lệ. Hơn chín tháng trước, cũng bàn tay ấy đã ký một hiệp định để giữ hòa bình. Giữa hai chữ ký là cả một năm Người kiên nhẫn tìm mọi con đường tránh cho dân tộc một cuộc chiến tranh.","doc":11},{"loai":"anh","src":"textures/bang_w/G00_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chủ tịch Hồ Chí Minh năm 1946 và chữ ký của Người”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Những dấu vết của năm 1946 hôm nay nằm ở nhiều nơi. Pho tượng đồng của Nguyễn Thị Kim thuộc sưu tập Bảo tàng Lịch sử quốc gia. Tập sắc lệnh 1945 – 1946 được bảo quản tại Trung tâm Lưu trữ quốc gia III; bản gốc đã được số hóa để hạn chế việc lật giở trực tiếp. Tháng 5/2023, Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch phối hợp với Trung tâm Lưu trữ quốc gia III trưng bày hơn hai trăm sắc lệnh, lệnh cùng khoảng tám mươi bức ảnh giai đoạn 1945 – 1969. Trong số tài liệu được giới thiệu có Lời kêu gọi toàn quốc kháng chiến.\n\nCòn bức ảnh trên bảng này, dù không rõ người chụp, vẫn được in lại ở rất nhiều nơi. Trong Sảnh Hành trình, chân dung năm 1946 cũng được đặt ở tường danh dự, mặt duy nhất trong mười tám mặt sảnh không dẫn vào một gian trưng bày nào. Gương mặt ấy thuộc về một năm không hề yên ả, và nét chữ ký ấy từng đặt dưới những quyết định sống còn của cả dân tộc.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Bảo tàng Lịch sử quốc gia – Tượng “Chân dung Chủ tịch Hồ Chí Minh” năm 1946, bảo vật quốc gia: https://baotanglichsu.vn/vi/Articles/1001/73683/tuong-chan-dung-chu-tich-ho-chi-minh-nam-1946-bao-vat-quoc-gia-tai-bao-tang-lich-su-quoc-gia.html","Báo Công an nhân dân – Thông tin ít biết về Tập Sắc lệnh, bảo vật quốc gia: https://cand.vn/thong-tin-it-biet-ve-tap-sac-lenh-bao-vat-quoc-gia-post666021.html","Bảo tàng Hồ Chí Minh – Hiện vật kể chuyện: Bút tích chữ ký của Chủ tịch Hồ Chí Minh trong trang Sổ vàng của Tòa Thị chính Paris ngày 4/7/1946: https://baotanghochiminh.vn/hien-vat-ke-chuyen-tai-lieu-but-tich-chu-ky-cua-chu-tich-ho-chi-minh-trong-trang-so-vang-cua-toa-thi-chinh-tai-thanh-pho-paris-ngay-4-7-1946.htm","Báo Pháp luật Việt Nam – Bức chân dung ánh sáng của Chủ tịch Hồ Chí Minh (15/5/2020): https://baophapluat.vn/buc-chan-dung-anh-sang-cua-chu-tich-ho-chi-minh-post346164.html","Bộ Văn hóa, Thể thao và Du lịch – Trưng bày chữ ký và bút tích của Chủ tịch Hồ Chí Minh giai đoạn 1945 – 1969: https://bvhttdl.gov.vn/trung-bay-chu-ky-va-but-tich-cua-chu-tich-ho-chi-minh-giai-doan-1945-1969-20230517153452443.htm"],"doc":[{"t":"Năm 1946 qua một gương mặt và một nét bút. Người chụp bức ảnh này không để lại tên, nhưng năm 1946 thì để lại rất nhiều dấu vết của vị Chủ tịch 56 tuổi. Có một pho tượng được nặn trong hơn hai mươi buổi sáng ở Bắc Bộ phủ, rồi nằm dưới gầm bàn thờ suốt những năm kháng chiến. Có những bản sắc lệnh còn nguyên nét mực, một trang sổ vàng ở Paris, một tấm ảnh ký tặng người họa sĩ xa quê. Lần theo chữ ký “Hồ Chí Minh”, ta đi lại một năm đầy giông bão."},{"t":"Một gương mặt, một nét bút. Bức ảnh trên bảng được lưu hành rộng rãi với một chú thích ngắn: Chủ tịch Hồ Chí Minh, chụp khoảng năm 1946. Người bấm máy không để lại tên, và bức ảnh nay thuộc phạm vi công cộng, ai cũng có thể in lại. Đi cùng gương mặt ấy là chữ ký của Người, chính là ba chữ Hồ Chí Minh. Cái tên này mới được dùng từ tháng 8/1942, vậy mà chỉ vài năm sau đã đứng dưới những văn bản quyết định vận mệnh một quốc gia. Năm 1946, Người bước sang tuổi 56. Sinh nhật ngày 19 tháng 5 năm ấy rơi vào quãng bận rộn nhất, chưa đầy hai tuần trước khi Người lên đường sang Pháp. Đặt gương mặt và chữ ký cạnh nhau, bảng ảnh gợi một cách đọc lại năm 1946: không chỉ qua các sự kiện lớn, mà qua những dấu vết vật chất còn giữ được đến hôm nay. Đó là một pho tượng đồng, một tập sắc lệnh, một trang sổ vàng, một tấm ảnh ký tặng."},{"t":"Năm thứ hai của nước Việt Nam mới. Năm 1946 mở ra khi nước Việt Nam Dân chủ Cộng hòa mới tròn bốn tháng tuổi. Ở miền Bắc, khoảng hai mươi vạn quân Tưởng Giới Thạch đóng quân với danh nghĩa giải giáp quân Nhật, kéo theo các nhóm chính trị đối lập. Ở Nam Bộ, cuộc kháng chiến chống thực dân Pháp trở lại xâm lược đã sang tháng thứ tư. Nạn đói năm trước vừa qua, ngân khố gần như trống rỗng, phần đông dân chúng chưa biết chữ. Trong hoàn cảnh ấy, Người lần lượt nhận những trọng trách mới. Ngày 1/1/1946, Chính phủ lâm thời được mở rộng thành Chính phủ liên hiệp lâm thời. Ngày 2/3/1946, tại kỳ họp thứ nhất của Quốc hội khóa I, Người được bầu làm Chủ tịch Chính phủ Liên hiệp kháng chiến. Từ đó đến cuối năm, Người vừa điều hành việc nước, vừa đàm phán, vừa xa Tổ quốc gần năm tháng trên đường sang Pháp và trở về. Một pho tượng nặn giữa năm ấy đã giữ lại dấu vết của chúng trên gương mặt Người: nét mặt đăm chiêu, vầng trán rộng hơi nhíu lại."},{"t":"Hơn hai mươi buổi sáng ở Bắc Bộ phủ. Tháng 5/1946, Ban lãnh đạo Hội Văn hóa cứu quốc cử các họa sĩ Tô Ngọc Vân, Nguyễn Đỗ Cung và Nguyễn Thị Kim đến Bắc Bộ phủ để vẽ và nặn tượng Chủ tịch Hồ Chí Minh. Bắc Bộ phủ, nay là Nhà khách Chính phủ trên phố Ngô Quyền, Hà Nội, khi ấy là nơi Người làm việc. Bà Nguyễn Thị Kim, người được coi là nữ điêu khắc gia đầu tiên của Việt Nam, được ngồi gần Người ngay trong phòng làm việc. Hơn hai mươi ngày liền, mỗi ngày hai tiếng, từ sáu giờ đến tám giờ sáng, bà quan sát và nặn. Pho tượng ghi lại một tư thế rất thật: đầu hơi cúi về phía trước, thể hiện sự tập trung cao độ vào công việc. Bà nặn tượng bằng đất sét, sau đó làm khuôn thạch cao, khuôn âm bản rồi đổ đồng. Tượng đúc liền khối, rỗng ruột, cao 46 cm, rộng vai 45 cm, nặng 17 kg. Dưới vai phải, tác giả khắc chữ Hán “Kim” và dòng chữ Việt “Ng.T. Kim – 1946”, như một chữ ký của nghệ sĩ đặt cạnh chân dung vị Chủ tịch."},{"t":"Bạn có biết? Pho tượng chân dung Chủ tịch Hồ Chí Minh năm 1946 của nhà điêu khắc Nguyễn Thị Kim đã được công nhận là bảo vật quốc gia trong đợt thứ 11, theo Quyết định số 41/QĐ-TTg ngày 30/1/2023 của Thủ tướng Chính phủ."},{"t":"Pho tượng dưới gầm bàn thờ. Chỉ vài tháng sau những buổi sáng ở Bắc Bộ phủ, chiến tranh lan ra cả nước. Tháng 12/1946, cũng là tháng cuộc kháng chiến toàn quốc bùng nổ, chồng bà Kim đào một cái hầm ngay dưới gầm bàn thờ họ của gia đình để chôn giấu bức tượng. Suốt những năm kháng chiến chống Pháp, gương mặt vị Chủ tịch bằng đồng nằm lặng lẽ dưới lòng đất. Sau chiến thắng Điện Biên Phủ, gia đình nhà điêu khắc tìm lại đúng vị trí cất giấu và đào bức tượng lên. Năm 1959, khi Bảo tàng Cách mạng Việt Nam được thành lập, vợ chồng bà quyết định trao tặng bức tượng cho bảo tàng. Ngày nay, tượng thuộc sưu tập của Bảo tàng Lịch sử quốc gia ở Hà Nội. Qua bàn tay nhà điêu khắc, gương mặt Người hiện lên với chòm râu dài và vầng trán rộng của tuổi năm mươi sáu."},{"t":"Chữ ký tươi trên những sắc lệnh đầu tiên. Nếu pho tượng giữ lại gương mặt, thì các kho lưu trữ giữ lại nét bút. Tại Trung tâm Lưu trữ quốc gia III ở Hà Nội, trong một tầng hầm sâu khoảng mười hai mét, nhiệt độ luôn được giữ trong khoảng 18 đến 22 độ C, có một tập hồ sơ đặc biệt. Đó là Tập Sắc lệnh của Chủ tịch Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa, gồm 118 sắc lệnh ban hành trong khoảng nửa năm đầu tiên của chính quyền mới, từ mùa thu 1945 sang đầu năm 1946. Hơn tám mươi sắc lệnh trong đó do chính Chủ tịch Hồ Chí Minh ký; 25 sắc lệnh do Bộ trưởng Bộ Nội vụ Võ Nguyên Giáp thay mặt Chủ tịch ký. Các bản đều đánh máy, nhiều bản còn bút tích sửa chữa câu chữ, và mang chữ ký “tươi”, tức chữ ký viết tay trực tiếp của người có thẩm quyền. Nội dung là những việc nền móng: tổng tuyển cử, chống đói, chống nạn mù chữ, tổ chức bộ máy nhà nước. Trong những năm 1990, cả tập được tu bổ, gia cố bằng giấy và keo chuyên dụng. Ngày 22/12/2016, tập sắc lệnh được công nhận là bảo vật quốc gia."},{"t":"Trang sổ vàng Paris và tấm ảnh ký tặng. Mùa hè năm 1946, chữ ký của Người theo Người sang nước Pháp. Ngày 22/6/1946, Chủ tịch Hồ Chí Minh tới Paris; mười ngày sau, chính phủ Pháp mới tổ chức lễ đón chính thức kéo dài ba ngày, từ 2 đến 4/7/1946, theo nghi thức dành cho nguyên thủ quốc gia. Ngày 4/7, tại Tòa Thị chính Paris, Người viết mười bốn dòng chữ tiếng Pháp vào sổ vàng của thành phố. Lời đề gửi tới ông Chủ tịch Hội đồng thành phố, ông Tỉnh trưởng thành Seine, ông Tỉnh trưởng cảnh sát cùng các đại diện, rồi kết thúc bằng chữ ký Hồ Chí Minh. Trang sổ dài 30 cm, rộng 23 cm ấy là tài liệu Bảo tàng Hồ Chí Minh thu thập được trong chuyến công tác nghiên cứu tại Paris cuối năm 2024. Cũng năm ấy ở Paris, nhiếp ảnh gia Laure Albin Guillot, một tên tuổi của ảnh chân dung Pháp, đã chụp chân dung Người. Bức ảnh được in thành nhiều bản để Chủ tịch ký tặng kiều bào và khách mời trong các cuộc tiếp xúc. Một bản mang dòng đề tặng họa sĩ Lê Phổ: “Tặng chú Lê Phổ, Chào thân ái! Tháng 8/1946”. Chân dung kèm chữ ký từng là một cử chỉ thân tình của vị Chủ tịch nơi đất khách."},{"t":"Bạn có biết? Năm 2015, Bảo tàng Hồ Chí Minh – Chi nhánh Gia Lai – Kon Tum giới thiệu sưu tập 79 chữ ký của Chủ tịch Hồ Chí Minh thời kỳ 1945 – 1969. Các chữ ký được chọn lọc từ hàng nghìn văn bản lưu tại Cục Văn thư và Lưu trữ nhà nước; con số 79 trùng với tuổi thọ của Người."},{"t":"Những chữ ký của sự nhân nhượng có nguyên tắc. Có những chữ ký năm 1946 được đặt xuống sau những tính toán rất nặng nề. Chiều 6/3/1946, Người cùng ông Vũ Hồng Khanh ký Hiệp định Sơ bộ với đại diện Chính phủ Pháp là ông Jean Sainteny. Chữ ký ấy đổi lấy thời gian hòa hoãn và việc quân Tưởng sớm rút về nước (xem chuyên đề Ký Hiệp định Sơ bộ 6/3/1946, gian Hà Nội 1945 – Ba Đình). Sáu tháng sau, khi cuộc đàm phán ở Fontainebleau không đạt kết quả, ngày 14/9/1946 tại Paris, Người ký với Bộ trưởng Marius Moutet bản Tạm ước. Người chấp nhận nhân nhượng cho Pháp một số quyền lợi kinh tế, văn hóa để có thêm thời gian hòa bình. Đó là nhân nhượng về bước đi, không nhân nhượng về độc lập và thống nhất. Điều không bao giờ đem ra đổi chác, Người đã viết rõ trong bức thư gửi đồng bào Nam Bộ đề ngày 31/5/1946, đúng ngày Người rời Hà Nội sang Pháp. Khi ấy, Nam Bộ đã kháng chiến hơn tám tháng, và thực dân Pháp đang tìm cách tách Nam Bộ khỏi Việt Nam."},{"t":"Đồng bào Nam Bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi! — Hồ Chí Minh"},{"t":"Hiến pháp và lời kêu gọi cuối năm. Ngày 20/10/1946, Người về tới Hải Phòng và lập tức trở lại với những việc lớn của cuối năm. Ngày 9/11/1946, Quốc hội thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa. Chính Người từng làm Trưởng ban dự thảo Hiến pháp gồm bảy thành viên, do Chính phủ lâm thời lập ra chỉ vài tuần sau ngày độc lập. Nhưng hòa bình không giữ được lâu hơn. Thực dân Pháp liên tiếp gây hấn ở Hải Phòng, Lạng Sơn, rồi ngay giữa Hà Nội. Lời kêu gọi toàn quốc kháng chiến, được Người viết tại làng Vạn Phúc, Hà Đông, ra đời ngày 19/12/1946. Chữ ký Hồ Chí Minh dưới lời kêu gọi ấy khép lại năm 1946 bằng một quyết định không thể lùi: thà hy sinh tất cả, chứ nhất định không chịu mất nước, không chịu làm nô lệ. Hơn chín tháng trước, cũng bàn tay ấy đã ký một hiệp định để giữ hòa bình. Giữa hai chữ ký là cả một năm Người kiên nhẫn tìm mọi con đường tránh cho dân tộc một cuộc chiến tranh."},{"t":"Dấu tích hôm nay. Những dấu vết của năm 1946 hôm nay nằm ở nhiều nơi. Pho tượng đồng của Nguyễn Thị Kim thuộc sưu tập Bảo tàng Lịch sử quốc gia. Tập sắc lệnh 1945 – 1946 được bảo quản tại Trung tâm Lưu trữ quốc gia III; bản gốc đã được số hóa để hạn chế việc lật giở trực tiếp. Tháng 5/2023, Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch phối hợp với Trung tâm Lưu trữ quốc gia III trưng bày hơn hai trăm sắc lệnh, lệnh cùng khoảng tám mươi bức ảnh giai đoạn 1945 – 1969. Trong số tài liệu được giới thiệu có Lời kêu gọi toàn quốc kháng chiến. Còn bức ảnh trên bảng này, dù không rõ người chụp, vẫn được in lại ở rất nhiều nơi. Trong Sảnh Hành trình, chân dung năm 1946 cũng được đặt ở tường danh dự, mặt duy nhất trong mười tám mặt sảnh không dẫn vào một gian trưng bày nào. Gương mặt ấy thuộc về một năm không hề yên ả, và nét chữ ký ấy từng đặt dưới những quyết định sống còn của cả dân tộc."}],"so_chu":1957},{"i":5,"tieu_de_bang":"Chân dung Bác trong sách Trang sử mới, 1945","tieu_de":"“Trang sử mới”: gương mặt vị Chủ tịch trên những trang sách mùa thu 1945","sapo":"Mùa thu năm 1945, một cuốn sách mang tên “Trang sử mới” ra đời, in lại bản Tuyên ngôn Độc lập cùng những lời phát biểu tại lễ Độc lập ở Ba Đình. Người làm sách là những nhà văn, nhà thơ, họa sĩ của Hội Văn hóa cứu quốc, vừa bước ra khỏi thời hoạt động bí mật. Trong sách có chân dung vị Chủ tịch nước mà phần đông đồng bào chưa từng gặp mặt. Câu chuyện của trang sách ấy cũng là câu chuyện gương mặt Người đến với nhân dân.","bia":{"src":"textures/ht/ht_anh_portrait_of_ho_chi_minh_from_the_book_trang_su_m.jpg","credit":"Ảnh: Hội Văn hóa cứu quốc Việt Nam · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Tập văn kiện đầu tiên của Chính phủ lâm thời","text":"Trong số những ấn phẩm ra đời mùa thu năm 1945, có một cuốn sách mang cái tên nói đúng tâm thế của cả dân tộc: “Trang sử mới”. Theo nhà nghiên cứu Lại Nguyên Ân, đây là tập văn kiện đầu tiên của Chính phủ lâm thời, do Hội Văn hóa cứu quốc Việt Nam xuất bản. Sách in bản Tuyên ngôn Độc lập của Chủ tịch Hồ Chí Minh cùng những bài phát biểu tại lễ Độc lập chiều 2/9/1945 ở Quảng trường Ba Đình.\n\nBức chân dung mà bảng ảnh này giới thiệu được in trong chính cuốn sách ấy. Với đồng bào ở xa Hà Nội, những trang in như thế là cách đầu tiên để đọc lại lời tuyên bố của ngày độc lập và nhìn thấy gương mặt người đã đọc bản Tuyên ngôn. Sau hơn tám mươi năm bị thực dân đô hộ, lịch sử Việt Nam lật sang một trang khác, và tên sách là một lời khẳng định ngắn gọn về điều ấy. Bức chân dung in năm 1945 nay thuộc phạm vi công cộng, được ghi nguồn là Hội Văn hóa cứu quốc Việt Nam.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_portrait_of_ho_chi_minh_from_the_book_trang_su_m.jpg","chu_thich":"Chân dung Chủ tịch Hồ Chí Minh in trong sách “Trang sử mới” do Hội Văn hóa cứu quốc Việt Nam xuất bản năm 1945.","credit":"Ảnh: Hội Văn hóa cứu quốc Việt Nam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bốn tiếng nói của buổi chiều độc lập","text":"Theo mô tả của Lại Nguyên Ân, “Trang sử mới” không chỉ in bản Tuyên ngôn. Sách còn in Lời hô hào quốc dân của Tổng bộ Việt Minh, do ông Nguyễn Lương Bằng đọc tại buổi lễ. Tiếp đó là bản báo cáo của trưởng đoàn đại biểu vào giao thiệp với triều đình Huế, do ông Trần Huy Liệu đọc. Sách còn có bài diễn văn về chính sách của Chính phủ lâm thời, do ông Võ Nguyên Giáp đọc.\n\nGộp lại, bốn văn bản dựng nên trọn vẹn buổi chiều lịch sử ấy. Đó là lời tuyên bố với thế giới, lời hiệu triệu quốc dân, lời tường thuật về sự cáo chung của chế độ quân chủ, và chương trình hành động của chính quyền mới. Người không có mặt ở Ba Đình, cầm cuốn sách trên tay, có thể hình dung đầy đủ những gì đã được nói ra trước hàng chục vạn đồng bào. Trong những ngày báo chí, nhà in còn thiếu thốn đủ bề, một tập văn kiện như vậy có giá trị đặc biệt. Nó biến những lời nói trên lễ đài thành văn bản có thể lưu giữ và chuyền tay.","doc":2},{"loai":"doan","tieu_de":"Bản báo cáo từ kinh thành Huế","text":"Bản báo cáo của ông Trần Huy Liệu kể về một sự kiện vừa diễn ra ba ngày trước lễ Độc lập. Chiều 30/8/1945, tại lầu Ngọ Môn, kinh thành Huế, vua Bảo Đại đọc chiếu thoái vị và trao ấn, kiếm cho phái đoàn của Chính phủ lâm thời gồm Trần Huy Liệu, Nguyễn Lương Bằng và Cù Huy Cận. Chế độ quân chủ tồn tại hàng nghìn năm trên đất nước ta chấm dứt; nhà vua cuối cùng trở thành công dân Vĩnh Thụy.\n\nViệc in bản báo cáo ấy vào “Trang sử mới” có ý nghĩa riêng. Người đọc thấy rõ chính quyền đã được chuyển giao trọn vẹn, không chỉ từ tay phát xít Nhật mà cả từ triều đình phong kiến. Chính bản Tuyên ngôn cũng tổng kết bằng một câu ngắn: “Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị”. Đặt cạnh bức chân dung vị Chủ tịch, bản báo cáo giúp người đọc năm 1945 hiểu rằng người trong ảnh không kế vị một ngai vàng. Người đứng đầu nhà nước mới là người được nhân dân trao gửi trách nhiệm.","doc":3},{"loai":"anh","src":"textures/bang_w/G00_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chân dung Bác trong sách Trang sử mới, 1945”, nhìn từ xa."},{"loai":"doan","tieu_de":"Những người làm sách: Hội Văn hóa cứu quốc","text":"Người làm ra “Trang sử mới” là Hội Văn hóa cứu quốc Việt Nam. Giữa năm 1943, trong một cuộc họp bí mật do Trung ương Đảng triệu tập, một số văn nghệ sĩ đã thảo luận và thông qua Điều lệ của Hội. Bốn người ký tên sáng lập là Nguyễn Hữu Đang, Nguyễn Đình Thi, Vũ Quốc Uy và Như Phong. Điều lệ nêu mục đích liên lạc hết thảy những nhà văn hóa Việt Nam, để kiến thiết một nền văn hóa mới có đủ ba tính chất khoa học, đại chúng và dân tộc. Đó cũng là tinh thần của bản Đề cương về văn hóa Việt Nam ra đời cùng năm.\n\nSau Cách mạng Tháng Tám, Hội bước ra hoạt động công khai. Ngày 4/9/1945, hai ngày sau lễ Độc lập, Hội họp Ban chấp hành mở rộng tại Hà Nội do nhà văn Nguyễn Đình Thi chủ trì. Cuộc họp đề ra kế hoạch tổ chức một hội nghị văn hóa toàn quốc và ra tạp chí Tiên phong. Tạp chí này ra nửa tháng một kỳ, mỗi số khoảng 24 đến 40 trang, trở thành diễn đàn cổ vũ cho nền văn hóa mới.","doc":4},{"loai":"ban_co_biet","text":"Chỉ trong một năm, từ tháng 8/1945 đến tháng 8/1946, Hội Văn hóa cứu quốc đã xuất bản 37 đầu sách với tổng cộng 199.880 bản in. Trong đó có tập thơ “Hội nghị non sông” của Xuân Diệu, tập “Thơ” của Tố Hữu và vở kịch “Bắc Sơn” của Nguyễn Huy Tưởng.","nguon_ten":"Lại Nguyên Ân, “Đầu nguồn của Liên hiệp Văn học nghệ thuật Việt Nam: Hội Văn hóa cứu quốc Việt Nam (1943 – 1948)”, Thời báo Văn học nghệ thuật, 2023","doc":5},{"loai":"doan","tieu_de":"Một gương mặt bước ra từ bí mật","text":"Trước Cách mạng Tháng Tám, người lãnh đạo cách mạng hoạt động trong vòng bí mật, phần lớn thời gian ở núi rừng Việt Bắc. Cái tên Hồ Chí Minh mới được dùng từ tháng 8/1942, và chỉ thực sự quen thuộc với toàn dân từ mùa thu năm 1945 (xem chuyên đề Một đời người, nhiều tên gọi). Chiều 2/9/1945, hàng chục vạn người ở Quảng trường Ba Đình được tận mắt thấy vị Chủ tịch giản dị. Nhưng đồng bào các tỉnh xa chỉ có thể biết đến gương mặt ấy qua báo chí, tranh ảnh và sách in.\n\nHội Văn hóa cứu quốc góp phần quan trọng trong việc đưa hình ảnh ấy đi xa. Ngày 7/10/1945, Chủ tịch Hồ Chí Minh dự lễ khai mạc Triển lãm Văn hóa do Hội tổ chức tại trụ sở cũ của Hội Khai trí Tiến Đức ở Hà Nội. Triển lãm giới thiệu các ấn phẩm công khai lẫn bí mật thời Pháp – Nhật cùng tranh của nhiều họa sĩ. Tháng 5/1946, Hội lại cử các họa sĩ Tô Ngọc Vân, Nguyễn Đỗ Cung và nhà điêu khắc Nguyễn Thị Kim tới Bắc Bộ phủ vẽ và nặn tượng Người (xem chuyên đề Chủ tịch Hồ Chí Minh năm 1946 và chữ ký của Người). Bức chân dung trong “Trang sử mới” đứng ở khởi đầu của hành trình ấy.","doc":6},{"loai":"anh","src":"textures/bang_w/G00_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chân dung Bác trong sách Trang sử mới, 1945”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ trang sách đến tờ giấy bạc","text":"Chỉ vài tháng sau trang sách, gương mặt Người còn đi vào túi tiền của từng người dân. Ngày 31/1/1946, Chủ tịch Hồ Chí Minh ký sắc lệnh cho phép phát hành đồng bạc giấy Việt Nam ở các tỉnh từ vĩ tuyến 16 trở vào. Một mặt tờ bạc in dòng chữ Việt Nam Dân chủ Cộng hòa cùng hình Chủ tịch Hồ Chí Minh. Trên tờ bạc có chữ ký của Bộ trưởng Bộ Tài chính, là ông Phạm Văn Đồng hoặc ông Lê Văn Hiến, cùng chữ ký của Giám đốc Ngân khố Trung ương.\n\nNhững đợt tiền đầu tiên được in ở các nhà in Hà Nội như Nguyễn Ninh, Việt Hưng, Ngô Tử Hạ, Taupin. Về sau, xưởng in phải chuyển lên đồn điền Chi Nê ở Hòa Bình, rồi lên Chiêm Hóa ở Tuyên Quang. Tại kỳ họp thứ hai tháng 11/1946, Quốc hội khóa I quyết định cho phát hành rộng rãi đồng bạc giấy trong toàn quốc. Người dân quen gọi đó là giấy bạc Cụ Hồ. Từ trang sách năm 1945 đến tờ bạc năm 1946, gương mặt vị Chủ tịch đã trở thành một biểu tượng của nền độc lập.","doc":7},{"loai":"ban_co_biet","text":"Nơi đầu tiên đồng bạc giấy Việt Nam in hình Chủ tịch Hồ Chí Minh được phát hành thí điểm là thị xã Quảng Ngãi, vào ngày 3/2/1946, đúng dịp tròn mười sáu năm ngày thành lập Đảng.","nguon_ten":"Thời báo Tài chính Việt Nam, “Điều ít biết về giấy bạc Tài chính – giấy bạc Cụ Hồ”","doc":8},{"loai":"doan","tieu_de":"Văn hóa soi đường","text":"Mối gắn bó giữa Hội Văn hóa cứu quốc và vị Chủ tịch đạt tới một dấu mốc vào cuối năm 1946. Hội góp phần quan trọng giúp Chính phủ tổ chức Hội nghị Văn hóa toàn quốc lần thứ nhất, khai mạc ngày 24/11/1946 tại Hà Nội. Đó chính là hội nghị mà Hội đã đặt vào kế hoạch từ tháng 9/1945. Chủ tịch Hồ Chí Minh đến dự và đọc một bài diễn văn dài khoảng bốn mươi phút.\n\nNgười mong văn hóa đi sâu vào tâm lý quốc dân, giúp sửa đổi những thói xấu như tham nhũng, lười biếng, phù hoa, xa xỉ, và làm cho ai cũng có lý tưởng tự chủ, độc lập, tự do. Trong bài nói ấy có một câu ngắn về sau được nhắc lại rất nhiều lần. Đọc câu nói ấy, ta hiểu vì sao những trang sách như “Trang sử mới” lại được coi trọng đến thế ngay từ những ngày đầu của chính quyền mới.","doc":9},{"loai":"trich","text":"Văn hóa phải soi đường cho quốc dân đi.","nguoi":"Hồ Chí Minh","nguon_ten":"Bài nói tại Hội nghị Văn hóa toàn quốc lần thứ nhất, Hà Nội, 24/11/1946","doc":10},{"loai":"doan","tieu_de":"Số phận của một hội văn hóa và một trang sách","text":"Chưa đầy một tháng sau hội nghị, cuộc kháng chiến toàn quốc bùng nổ. Nhiều văn nghệ sĩ rời Hà Nội lên chiến khu, tiếp tục viết, vẽ, biểu diễn giữa núi rừng. Tháng 7/1948, tại Việt Bắc, hai hội nghị lớn diễn ra: Hội nghị Văn hóa toàn quốc lần thứ hai thành lập Hội Văn hóa Việt Nam, còn Hội nghị Văn nghệ toàn quốc thành lập Hội Văn nghệ Việt Nam. Hội Văn hóa cứu quốc khép lại sứ mệnh lịch sử của mình. Nhà nghiên cứu Lại Nguyên Ân gọi Hội là “đầu nguồn” của Liên hiệp các Hội Văn học nghệ thuật Việt Nam ngày nay.\n\nNhững ấn phẩm của Hội năm 1945, trong đó có “Trang sử mới”, trở thành tư liệu quý về buổi đầu của nền xuất bản cách mạng công khai. Bức chân dung in trong sách hôm nay vẫn được in lại ở nhiều nơi, và có mặt trên bảng ảnh này trong Sảnh Hành trình. Người xem đứng trước nó đang nhìn đúng gương mặt mà đồng bào mùa thu năm 1945 lần đầu được thấy trên trang giấy.","doc":11},{"loai":"anh","src":"textures/bang_w/G00_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chân dung Bác trong sách Trang sử mới, 1945”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Đọc lại một trang sử","text":"Tên sách “Trang sử mới” hôm nay đọc lên vẫn nguyên sức gợi. Lần đầu tiên, người Việt Nam đọc lịch sử của mình qua văn kiện của chính nhà nước mình. Trong cùng một cuốn sách có bản Tuyên ngôn mở đầu bằng quyền sống, quyền tự do và quyền mưu cầu hạnh phúc. Có bản báo cáo ghi lại sự cáo chung của ngai vàng ở Huế. Có bài diễn văn vạch ra những việc Chính phủ lâm thời phải làm ngay. Và có gương mặt của người đứng ra gánh vác tất cả những việc ấy.\n\nVới bảo tàng hôm nay, bức chân dung nhắc lại một sự thật giản dị: nền độc lập không chỉ được tuyên bố trên lễ đài, mà còn phải được in ra và truyền đi. Những cuốn sách đầu tiên của Hội Văn hóa cứu quốc là một phần của công việc ấy. Chúng đưa lời Tuyên ngôn và gương mặt vị Chủ tịch đến gần hơn với đồng bào cả nước, kể cả những người chưa một lần về Hà Nội.","doc":12}],"nguon":["Lại Nguyên Ân, “Đầu nguồn của Liên hiệp Văn học nghệ thuật Việt Nam: Hội Văn hóa cứu quốc Việt Nam (1943 – 1948)”, Thời báo Văn học nghệ thuật, 27/4/2023: https://arttimes.vn/van-tho/dau-nguon-cua-lien-hiep-van-hoc-nghe-thuat-viet-nam-hoi-van-hoa-cuu-quoc-viet-nam-1943-1948-c55a27216.html","Thời báo Tài chính Việt Nam – Điều ít biết về giấy bạc Tài chính – giấy bạc Cụ Hồ: https://thoibaotaichinhvietnam.vn/dieu-it-biet-ve-giay-bac-tai-chinh-giay-bac-cu-ho-111884.html","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Đề cương về văn hóa Việt Nam (1943)","Bảo tàng Lịch sử quốc gia – Tượng “Chân dung Chủ tịch Hồ Chí Minh” năm 1946: https://baotanglichsu.vn/vi/Articles/1001/73683/tuong-chan-dung-chu-tich-ho-chi-minh-nam-1946-bao-vat-quoc-gia-tai-bao-tang-lich-su-quoc-gia.html"],"doc":[{"t":"“Trang sử mới”: gương mặt vị Chủ tịch trên những trang sách mùa thu 1945. Mùa thu năm 1945, một cuốn sách mang tên “Trang sử mới” ra đời, in lại bản Tuyên ngôn Độc lập cùng những lời phát biểu tại lễ Độc lập ở Ba Đình. Người làm sách là những nhà văn, nhà thơ, họa sĩ của Hội Văn hóa cứu quốc, vừa bước ra khỏi thời hoạt động bí mật. Trong sách có chân dung vị Chủ tịch nước mà phần đông đồng bào chưa từng gặp mặt. Câu chuyện của trang sách ấy cũng là câu chuyện gương mặt Người đến với nhân dân."},{"t":"Tập văn kiện đầu tiên của Chính phủ lâm thời. Trong số những ấn phẩm ra đời mùa thu năm 1945, có một cuốn sách mang cái tên nói đúng tâm thế của cả dân tộc: “Trang sử mới”. Theo nhà nghiên cứu Lại Nguyên Ân, đây là tập văn kiện đầu tiên của Chính phủ lâm thời, do Hội Văn hóa cứu quốc Việt Nam xuất bản. Sách in bản Tuyên ngôn Độc lập của Chủ tịch Hồ Chí Minh cùng những bài phát biểu tại lễ Độc lập chiều 2/9/1945 ở Quảng trường Ba Đình. Bức chân dung mà bảng ảnh này giới thiệu được in trong chính cuốn sách ấy. Với đồng bào ở xa Hà Nội, những trang in như thế là cách đầu tiên để đọc lại lời tuyên bố của ngày độc lập và nhìn thấy gương mặt người đã đọc bản Tuyên ngôn. Sau hơn tám mươi năm bị thực dân đô hộ, lịch sử Việt Nam lật sang một trang khác, và tên sách là một lời khẳng định ngắn gọn về điều ấy. Bức chân dung in năm 1945 nay thuộc phạm vi công cộng, được ghi nguồn là Hội Văn hóa cứu quốc Việt Nam."},{"t":"Bốn tiếng nói của buổi chiều độc lập. Theo mô tả của Lại Nguyên Ân, “Trang sử mới” không chỉ in bản Tuyên ngôn. Sách còn in Lời hô hào quốc dân của Tổng bộ Việt Minh, do ông Nguyễn Lương Bằng đọc tại buổi lễ. Tiếp đó là bản báo cáo của trưởng đoàn đại biểu vào giao thiệp với triều đình Huế, do ông Trần Huy Liệu đọc. Sách còn có bài diễn văn về chính sách của Chính phủ lâm thời, do ông Võ Nguyên Giáp đọc. Gộp lại, bốn văn bản dựng nên trọn vẹn buổi chiều lịch sử ấy. Đó là lời tuyên bố với thế giới, lời hiệu triệu quốc dân, lời tường thuật về sự cáo chung của chế độ quân chủ, và chương trình hành động của chính quyền mới. Người không có mặt ở Ba Đình, cầm cuốn sách trên tay, có thể hình dung đầy đủ những gì đã được nói ra trước hàng chục vạn đồng bào. Trong những ngày báo chí, nhà in còn thiếu thốn đủ bề, một tập văn kiện như vậy có giá trị đặc biệt. Nó biến những lời nói trên lễ đài thành văn bản có thể lưu giữ và chuyền tay."},{"t":"Bản báo cáo từ kinh thành Huế. Bản báo cáo của ông Trần Huy Liệu kể về một sự kiện vừa diễn ra ba ngày trước lễ Độc lập. Chiều 30/8/1945, tại lầu Ngọ Môn, kinh thành Huế, vua Bảo Đại đọc chiếu thoái vị và trao ấn, kiếm cho phái đoàn của Chính phủ lâm thời gồm Trần Huy Liệu, Nguyễn Lương Bằng và Cù Huy Cận. Chế độ quân chủ tồn tại hàng nghìn năm trên đất nước ta chấm dứt; nhà vua cuối cùng trở thành công dân Vĩnh Thụy. Việc in bản báo cáo ấy vào “Trang sử mới” có ý nghĩa riêng. Người đọc thấy rõ chính quyền đã được chuyển giao trọn vẹn, không chỉ từ tay phát xít Nhật mà cả từ triều đình phong kiến. Chính bản Tuyên ngôn cũng tổng kết bằng một câu ngắn: “Pháp chạy, Nhật hàng, vua Bảo Đại thoái vị”. Đặt cạnh bức chân dung vị Chủ tịch, bản báo cáo giúp người đọc năm 1945 hiểu rằng người trong ảnh không kế vị một ngai vàng. Người đứng đầu nhà nước mới là người được nhân dân trao gửi trách nhiệm."},{"t":"Những người làm sách: Hội Văn hóa cứu quốc. Người làm ra “Trang sử mới” là Hội Văn hóa cứu quốc Việt Nam. Giữa năm 1943, trong một cuộc họp bí mật do Trung ương Đảng triệu tập, một số văn nghệ sĩ đã thảo luận và thông qua Điều lệ của Hội. Bốn người ký tên sáng lập là Nguyễn Hữu Đang, Nguyễn Đình Thi, Vũ Quốc Uy và Như Phong. Điều lệ nêu mục đích liên lạc hết thảy những nhà văn hóa Việt Nam, để kiến thiết một nền văn hóa mới có đủ ba tính chất khoa học, đại chúng và dân tộc. Đó cũng là tinh thần của bản Đề cương về văn hóa Việt Nam ra đời cùng năm. Sau Cách mạng Tháng Tám, Hội bước ra hoạt động công khai. Ngày 4/9/1945, hai ngày sau lễ Độc lập, Hội họp Ban chấp hành mở rộng tại Hà Nội do nhà văn Nguyễn Đình Thi chủ trì. Cuộc họp đề ra kế hoạch tổ chức một hội nghị văn hóa toàn quốc và ra tạp chí Tiên phong. Tạp chí này ra nửa tháng một kỳ, mỗi số khoảng 24 đến 40 trang, trở thành diễn đàn cổ vũ cho nền văn hóa mới."},{"t":"Bạn có biết? Chỉ trong một năm, từ tháng 8/1945 đến tháng 8/1946, Hội Văn hóa cứu quốc đã xuất bản 37 đầu sách với tổng cộng 199.880 bản in. Trong đó có tập thơ “Hội nghị non sông” của Xuân Diệu, tập “Thơ” của Tố Hữu và vở kịch “Bắc Sơn” của Nguyễn Huy Tưởng."},{"t":"Một gương mặt bước ra từ bí mật. Trước Cách mạng Tháng Tám, người lãnh đạo cách mạng hoạt động trong vòng bí mật, phần lớn thời gian ở núi rừng Việt Bắc. Cái tên Hồ Chí Minh mới được dùng từ tháng 8/1942, và chỉ thực sự quen thuộc với toàn dân từ mùa thu năm 1945 (xem chuyên đề Một đời người, nhiều tên gọi). Chiều 2/9/1945, hàng chục vạn người ở Quảng trường Ba Đình được tận mắt thấy vị Chủ tịch giản dị. Nhưng đồng bào các tỉnh xa chỉ có thể biết đến gương mặt ấy qua báo chí, tranh ảnh và sách in. Hội Văn hóa cứu quốc góp phần quan trọng trong việc đưa hình ảnh ấy đi xa. Ngày 7/10/1945, Chủ tịch Hồ Chí Minh dự lễ khai mạc Triển lãm Văn hóa do Hội tổ chức tại trụ sở cũ của Hội Khai trí Tiến Đức ở Hà Nội. Triển lãm giới thiệu các ấn phẩm công khai lẫn bí mật thời Pháp – Nhật cùng tranh của nhiều họa sĩ. Tháng 5/1946, Hội lại cử các họa sĩ Tô Ngọc Vân, Nguyễn Đỗ Cung và nhà điêu khắc Nguyễn Thị Kim tới Bắc Bộ phủ vẽ và nặn tượng Người (xem chuyên đề Chủ tịch Hồ Chí Minh năm 1946 và chữ ký của Người). Bức chân dung trong “Trang sử mới” đứng ở khởi đầu của hành trình ấy."},{"t":"Từ trang sách đến tờ giấy bạc. Chỉ vài tháng sau trang sách, gương mặt Người còn đi vào túi tiền của từng người dân. Ngày 31/1/1946, Chủ tịch Hồ Chí Minh ký sắc lệnh cho phép phát hành đồng bạc giấy Việt Nam ở các tỉnh từ vĩ tuyến 16 trở vào. Một mặt tờ bạc in dòng chữ Việt Nam Dân chủ Cộng hòa cùng hình Chủ tịch Hồ Chí Minh. Trên tờ bạc có chữ ký của Bộ trưởng Bộ Tài chính, là ông Phạm Văn Đồng hoặc ông Lê Văn Hiến, cùng chữ ký của Giám đốc Ngân khố Trung ương. Những đợt tiền đầu tiên được in ở các nhà in Hà Nội như Nguyễn Ninh, Việt Hưng, Ngô Tử Hạ, Taupin. Về sau, xưởng in phải chuyển lên đồn điền Chi Nê ở Hòa Bình, rồi lên Chiêm Hóa ở Tuyên Quang. Tại kỳ họp thứ hai tháng 11/1946, Quốc hội khóa I quyết định cho phát hành rộng rãi đồng bạc giấy trong toàn quốc. Người dân quen gọi đó là giấy bạc Cụ Hồ. Từ trang sách năm 1945 đến tờ bạc năm 1946, gương mặt vị Chủ tịch đã trở thành một biểu tượng của nền độc lập."},{"t":"Bạn có biết? Nơi đầu tiên đồng bạc giấy Việt Nam in hình Chủ tịch Hồ Chí Minh được phát hành thí điểm là thị xã Quảng Ngãi, vào ngày 3/2/1946, đúng dịp tròn mười sáu năm ngày thành lập Đảng."},{"t":"Văn hóa soi đường. Mối gắn bó giữa Hội Văn hóa cứu quốc và vị Chủ tịch đạt tới một dấu mốc vào cuối năm 1946. Hội góp phần quan trọng giúp Chính phủ tổ chức Hội nghị Văn hóa toàn quốc lần thứ nhất, khai mạc ngày 24/11/1946 tại Hà Nội. Đó chính là hội nghị mà Hội đã đặt vào kế hoạch từ tháng 9/1945. Chủ tịch Hồ Chí Minh đến dự và đọc một bài diễn văn dài khoảng bốn mươi phút. Người mong văn hóa đi sâu vào tâm lý quốc dân, giúp sửa đổi những thói xấu như tham nhũng, lười biếng, phù hoa, xa xỉ, và làm cho ai cũng có lý tưởng tự chủ, độc lập, tự do. Trong bài nói ấy có một câu ngắn về sau được nhắc lại rất nhiều lần. Đọc câu nói ấy, ta hiểu vì sao những trang sách như “Trang sử mới” lại được coi trọng đến thế ngay từ những ngày đầu của chính quyền mới."},{"t":"Văn hóa phải soi đường cho quốc dân đi. — Hồ Chí Minh"},{"t":"Số phận của một hội văn hóa và một trang sách. Chưa đầy một tháng sau hội nghị, cuộc kháng chiến toàn quốc bùng nổ. Nhiều văn nghệ sĩ rời Hà Nội lên chiến khu, tiếp tục viết, vẽ, biểu diễn giữa núi rừng. Tháng 7/1948, tại Việt Bắc, hai hội nghị lớn diễn ra: Hội nghị Văn hóa toàn quốc lần thứ hai thành lập Hội Văn hóa Việt Nam, còn Hội nghị Văn nghệ toàn quốc thành lập Hội Văn nghệ Việt Nam. Hội Văn hóa cứu quốc khép lại sứ mệnh lịch sử của mình. Nhà nghiên cứu Lại Nguyên Ân gọi Hội là “đầu nguồn” của Liên hiệp các Hội Văn học nghệ thuật Việt Nam ngày nay. Những ấn phẩm của Hội năm 1945, trong đó có “Trang sử mới”, trở thành tư liệu quý về buổi đầu của nền xuất bản cách mạng công khai. Bức chân dung in trong sách hôm nay vẫn được in lại ở nhiều nơi, và có mặt trên bảng ảnh này trong Sảnh Hành trình. Người xem đứng trước nó đang nhìn đúng gương mặt mà đồng bào mùa thu năm 1945 lần đầu được thấy trên trang giấy."},{"t":"Đọc lại một trang sử. Tên sách “Trang sử mới” hôm nay đọc lên vẫn nguyên sức gợi. Lần đầu tiên, người Việt Nam đọc lịch sử của mình qua văn kiện của chính nhà nước mình. Trong cùng một cuốn sách có bản Tuyên ngôn mở đầu bằng quyền sống, quyền tự do và quyền mưu cầu hạnh phúc. Có bản báo cáo ghi lại sự cáo chung của ngai vàng ở Huế. Có bài diễn văn vạch ra những việc Chính phủ lâm thời phải làm ngay. Và có gương mặt của người đứng ra gánh vác tất cả những việc ấy. Với bảo tàng hôm nay, bức chân dung nhắc lại một sự thật giản dị: nền độc lập không chỉ được tuyên bố trên lễ đài, mà còn phải được in ra và truyền đi. Những cuốn sách đầu tiên của Hội Văn hóa cứu quốc là một phần của công việc ấy. Chúng đưa lời Tuyên ngôn và gương mặt vị Chủ tịch đến gần hơn với đồng bào cả nước, kể cả những người chưa một lần về Hà Nội."}],"so_chu":1949},{"i":6,"tieu_de_bang":"Lời Bác: “Ham muốn tột bậc”","tieu_de":"“Ham muốn tột bậc”: lời tự bạch của một vị Chủ tịch nước","sapo":"Tháng Giêng năm 1946, các nhà báo nước ngoài hỏi vị Chủ tịch nước Việt Nam Dân chủ Cộng hòa về chính con người ông. Người không nói về quyền lực hay dự tính riêng, mà nói về một ham muốn duy nhất, rồi về một ngôi nhà nhỏ bên non xanh nước biếc. Ít ai biết lời tự bạch ấy còn nhắc tới đảng phái, tới kẻ phản quốc và kẻ tham ô. Đọc trọn văn bản, ta hiểu vì sao câu nói ấy sống mãi.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_1946_and_signature_cropped.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một lời đáp chung cho trong nước và thế giới","text":"Ngày 21/1/1946, báo Cứu quốc số 147 đăng một văn bản ngắn của Chủ tịch Hồ Chí Minh, về sau được in trong bộ Hồ Chí Minh Toàn tập với tên gọi “Trả lời các nhà báo nước ngoài”. Mở đầu, Người viết rằng nhân dịp các bạn tân văn ký giả ngoại quốc hỏi đến, Người xin trả lời chung để đồng bào trong nước và nhân sĩ nước ngoài cùng hiểu rõ. “Tân văn ký giả” là cách gọi nhà báo thời ấy.\n\nNgười chọn cách trả lời chung, công khai trên mặt báo, như một lời tự bạch trước công luận. Văn bản chỉ vài đoạn ngắn, lời lẽ giản dị, không một chữ khoa trương. Thế nhưng câu nói về “ham muốn tột bậc” nằm trong đó đã trở thành một trong những lời nổi tiếng nhất của Người. Trong Sảnh Hành trình, câu nói ấy được chọn đặt ở tường danh dự, cạnh chân dung Người năm 1946.","doc":1},{"loai":"trich","text":"Tôi chỉ có một sự ham muốn, ham muốn tột bậc, là làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành.","nguoi":"Hồ Chí Minh","nguon_ten":"Trả lời các nhà báo nước ngoài, báo Cứu quốc số 147, 21/1/1946 — Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia, 2011, tr. 187","doc":2},{"loai":"doan","tieu_de":"Tháng Giêng năm 1946","text":"Lời tự bạch ra đời vào một thời điểm đặc biệt. Chỉ hai tuần trước, ngày 6/1/1946, cử tri cả nước lần đầu đi bầu Quốc hội; Chủ tịch Hồ Chí Minh ứng cử ở Hà Nội và trúng cử với số phiếu rất cao. Trước đó, ngày 1/1/1946, Chính phủ lâm thời đã được mở rộng thành Chính phủ liên hiệp lâm thời, có thêm đại diện các đảng phái khác. Quân Tưởng Giới Thạch vẫn đóng ở miền Bắc; dựa vào đó, các nhóm Việt Nam Quốc dân Đảng và Việt Nam Cách mạng Đồng minh hội ra sức công kích chính quyền.\n\nNgày 11/11/1945, Đảng Cộng sản Đông Dương đã ra thông cáo tự giải tán, thực chất là rút vào hoạt động bí mật, để tránh mũi nhọn công kích và giữ khối đoàn kết dân tộc. Trong hoàn cảnh ấy, câu hỏi về con người và ý định của vị Chủ tịch không chỉ là sự tò mò của báo chí nước ngoài. Lời đáp của Người vì thế vừa gửi tới dư luận quốc tế, vừa là lời bày tỏ công khai với quốc dân về động cơ của chính mình.","doc":3},{"loai":"ban_co_biet","text":"Trong cuộc Tổng tuyển cử ngày 6/1/1946, Chủ tịch Hồ Chí Minh ứng cử tại Hà Nội và trúng cử với 98,4% số phiếu, tỷ lệ cao nhất trong số các đại biểu của Thủ đô.","nguon_ten":"Quốc hội Việt Nam – Lịch sử Quốc hội Việt Nam","doc":4},{"loai":"anh","src":"textures/bang_w/G00_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời Bác: “Ham muốn tột bậc””, nhìn từ xa."},{"loai":"doan","tieu_de":"Người lính vâng lệnh quốc dân","text":"Câu mở đầu lời tự bạch là một lời phủ nhận dứt khoát: Người tuyệt nhiên không ham muốn công danh phú quý chút nào. Chức Chủ tịch, Người viết, là do đồng bào ủy thác, nên phải gắng sức làm, cũng như một người lính vâng mệnh lệnh của quốc dân ra trước mặt trận. Bao giờ đồng bào cho lui, Người rất vui lòng lui.\n\nHình ảnh người lính ở đây không phải phép tu từ. Suốt ba mươi năm trước đó, Người đã sống đúng như một chiến sĩ: làm thuê ở nhiều bến cảng xứ người, ngồi tù ở Hồng Kông rồi ở Quảng Tây, ăn cháo bẹ rau măng ở Pác Bó. Chức vụ cao nhất nước đến với Người ở tuổi năm mươi lăm, và Người nhìn nó như một nhiệm vụ được giao, có thể trả lại bất cứ lúc nào. Với nhiều người dân vừa thoát khỏi chế độ quân chủ, lời tuyên bố sẵn sàng rút lui khi dân không cần nữa là một quan niệm mới mẻ về quyền lực. Quyền lực là sự ủy thác của nhân dân, không phải của riêng người nắm giữ.","doc":5},{"loai":"doan","tieu_de":"Bốn vế, bốn món nợ của chế độ cũ","text":"Câu nói về ham muốn tột bậc có bốn vế, đi từ việc lớn của quốc gia đến bữa cơm của từng nhà. Đó là nước hoàn toàn độc lập, dân hoàn toàn tự do, ai cũng có cơm ăn áo mặc, ai cũng được học hành. Mỗi vế là một món nợ mà chế độ cũ để lại. Hơn tám mươi năm, đất nước mất độc lập dưới ách thực dân, người dân không có những quyền tự do tối thiểu. Nạn đói năm Ất Dậu vừa qua; chính bản Tuyên ngôn Độc lập đã ghi rằng từ Quảng Trị đến Bắc Kỳ, hơn hai triệu đồng bào ta bị chết đói. Hơn chín mươi phần trăm dân số không biết chữ.\n\nHai chữ “hoàn toàn” được nhắc tới hai lần cũng mang sức nặng riêng. Đầu năm 1946, nền độc lập còn bị bao vây, thực dân Pháp đang đánh chiếm Nam Bộ, và một thứ độc lập nửa vời không phải là điều Người chấp nhận. Còn hai vế sau thì giản dị như lời một người cha trong nhà: có cơm ăn, có áo mặc, được đi học.","doc":6},{"loai":"ban_co_biet","text":"Để cứu đói, ngày 28/9/1945, Chủ tịch Hồ Chí Minh viết thư kêu gọi đồng bào cả nước cứ mười ngày nhịn ăn một bữa, mỗi tháng nhịn ba bữa, đem số gạo ấy cứu dân nghèo. Người nói rõ chính mình xin thực hành trước.","nguon_ten":"Hồ Chí Minh, thư kêu gọi đồng bào toàn quốc cứu đói, 28/9/1945 — Hồ Chí Minh Toàn tập, tập 4","doc":7},{"loai":"doan","tieu_de":"Độc lập phải mang lại hạnh phúc","text":"Vì sao Người đặt bát cơm và con chữ ngang hàng với độc lập, tự do? Ba tháng trước lời tự bạch, ngày 17/10/1945, Người gửi thư cho Ủy ban nhân dân các kỳ, tỉnh, huyện và làng. Trong thư, Người viết rằng nếu nước độc lập mà dân không được hưởng hạnh phúc, tự do, thì độc lập cũng chẳng có nghĩa lý gì. Độc lập là điều kiện đầu tiên, hạnh phúc của dân mới là thước đo cuối cùng.\n\nChính quyền mới hành động theo đúng tinh thần ấy. Ngay phiên họp đầu tiên của Chính phủ ngày 3/9/1945, Người đề ra những nhiệm vụ cấp bách: chống đói, chống nạn mù chữ, sớm tổ chức tổng tuyển cử, bỏ các thứ thuế vô lý. Khắp nơi dấy lên phong trào tăng gia sản xuất, hũ gạo cứu đói, và những lớp Bình dân học vụ mở trong đình làng, sân chùa (xem chuyên đề Diệt giặc dốt, gian Hà Nội 1945 – Ba Đình). Bốn vế của câu nói năm 1946 vì thế không phải lời hứa suông, mà là bản tóm tắt chương trình hành động chính quyền đang làm từng ngày.","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_1946_and_signature_cropped.jpg","chu_thich":"Chủ tịch Hồ Chí Minh, ảnh chụp khoảng năm 1946, năm Người nói về “ham muốn tột bậc” của mình.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một cái nhà nho nhỏ bên non xanh nước biếc","text":"Ngay sau câu nói về ham muốn tột bậc là một đoạn rất đời thường, ít được trích dẫn hơn. Riêng phần mình, Người chỉ mong làm một cái nhà nho nhỏ, nơi có non xanh nước biếc để câu cá, trồng hoa, sớm chiều làm bạn với các cụ già hái củi, em trẻ chăn trâu, không dính líu gì với vòng danh lợi. Đó là ước mơ của một người đã xa quê ba mươi năm, đã đi qua nhiều thành phố lớn trên thế giới, và chỉ mong được sống giữa những người lao động bình dị.\n\nƯớc mơ ấy chưa bao giờ thành hiện thực. Chưa đầy một năm sau, Người rời Hà Nội lên chiến khu, sống và làm việc trong những căn lán nơi núi rừng Việt Bắc suốt cuộc kháng chiến chống Pháp. Từ tháng 5/1958, Người ở ngôi nhà sàn nhỏ trong khu Phủ Chủ tịch, có vườn cây, có ao cá, như một phần của mong ước năm nào. Nhưng ở đó Người vẫn làm việc cho đến những ngày cuối đời (xem chuyên đề gian Phủ Chủ tịch – Nhà sàn).","doc":9},{"loai":"doan","tieu_de":"Đứng ngoài mọi đảng phái","text":"Phần cuối của lời tự bạch lại càng ít người biết. Người viết rằng trong một nước dân chủ, mọi người đều có tự do tín ngưỡng, tự do tổ chức; còn riêng mình thì phải đứng ra ngoài mọi đảng phái. Nếu cần có đảng phái, thì đó sẽ là Đảng dân tộc Việt Nam, một đảng chỉ có một mục đích là làm cho dân tộc hoàn toàn độc lập. Đảng viên của đảng ấy sẽ là tất cả quốc dân Việt Nam, trừ những kẻ phản quốc và những kẻ tham ô.\n\nĐặt trong bối cảnh đầu năm 1946, những lời này là một thông điệp đoàn kết rõ ràng. Giữa lúc các phe phái công kích lẫn nhau, vị Chủ tịch khẳng định mình là người của cả dân tộc, và thước đo để phân biệt chỉ là lòng yêu nước. Đáng chú ý, ngay từ năm 1946, Người đã đặt kẻ tham ô bên cạnh kẻ phản quốc.","doc":10},{"loai":"anh","src":"textures/bang_w/G00_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời Bác: “Ham muốn tột bậc””, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Một mục đích, bất kỳ bao giờ, bất kỳ ở đâu","text":"Lời tự bạch tháng Giêng năm 1946 không phải là một câu nói đơn lẻ. Suốt năm ấy, Người nhiều lần nhắc lại cùng một ý bằng những lời khác nhau. Tại cuộc mít tinh tiễn Người và đoàn đại biểu Chính phủ sang Pháp ngày 30/5/1946, Người nói với đồng bào rằng cả đời mình chỉ có một mục đích, là phấn đấu cho quyền lợi của Tổ quốc và hạnh phúc của quốc dân. Bất kỳ bao giờ, bất kỳ ở đâu, Người cũng chỉ theo đuổi một mục đích, làm cho ích quốc lợi dân.\n\nGần năm tháng sau, Người trở về khi nước Pháp vẫn chưa chịu công nhận độc lập và thống nhất của Việt Nam. Ngày 23/10/1946, trong lời tuyên bố với quốc dân sau khi đi Pháp về, Người nói về nỗi lòng của mình với đồng bào miền Nam đang chìm trong khói lửa.","doc":11},{"loai":"trich","text":"Một ngày mà Tổ quốc chưa thống nhất, đồng bào còn chịu khổ, là một ngày tôi ăn không ngon, ngủ không yên.","nguoi":"Hồ Chí Minh","nguon_ten":"Lời tuyên bố với quốc dân sau khi đi Pháp về, 23/10/1946","doc":12},{"loai":"doan","tieu_de":"Tiếng vọng đến hôm nay","text":"Hơn hai mươi ba năm sau lời tự bạch, trong bản Di chúc, Người vẫn dặn lại mong muốn cuối cùng về một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh (xem chuyên đề Sảnh Hành trình). Từ năm 1946 đến năm 1969, ham muốn ấy không đổi; chỉ những việc phải làm để đạt tới nó là thay đổi theo từng chặng đường.\n\nNgày nay, dưới quốc hiệu trên các văn bản nhà nước vẫn là tiêu ngữ Độc lập – Tự do – Hạnh phúc. Ba cụm từ ngắn gọn ấy như thu gọn bốn vế của câu nói năm 1946: độc lập cho nước, tự do cho dân, và hạnh phúc là cơm ăn, áo mặc, được học hành. Trong Sảnh Hành trình, câu nói được đặt ở tường danh dự, mặt duy nhất trong mười tám mặt sảnh không dẫn vào một gian trưng bày nào. Có lẽ không lời giới thiệu nào về cuộc đời Người ngắn gọn hơn thế: một ham muốn, và cả một đời người dành trọn cho nó.","doc":13},{"loai":"anh","src":"textures/bang_w/G00_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời Bác: “Ham muốn tột bậc””, nhìn sang bên phải."}],"nguon":["Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia Sự thật, 2011 (Trả lời các nhà báo nước ngoài, tr. 187)","Báo Cứu quốc, số 147, ngày 21/1/1946","Báo Nhân Dân – “Ham muốn tột bậc” của Bác Hồ: https://nhandan.vn/ham-muon-tot-bac-cua-bac-ho-post421662.html","Cổng Thông tin điện tử về Chủ tịch Hồ Chí Minh – Chủ tịch Hồ Chí Minh với khát vọng độc lập, tự do, hạnh phúc cho dân tộc, cho nhân dân: https://hochiminh.vn/tu-tuong-dao-duc-ho-chi-minh/nghien-cuu-tu-tuong-dao-duc-ho-chi-minh/chu-tich-ho-chi-minh-voi-khat-vong-doc-lap-tu-do-hanh-phuc-cho-dan-toc-cho-nhan-dan-8897","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Quốc hội Việt Nam – Lịch sử Quốc hội Việt Nam"],"doc":[{"t":"“Ham muốn tột bậc”: lời tự bạch của một vị Chủ tịch nước. Tháng Giêng năm 1946, các nhà báo nước ngoài hỏi vị Chủ tịch nước Việt Nam Dân chủ Cộng hòa về chính con người ông. Người không nói về quyền lực hay dự tính riêng, mà nói về một ham muốn duy nhất, rồi về một ngôi nhà nhỏ bên non xanh nước biếc. Ít ai biết lời tự bạch ấy còn nhắc tới đảng phái, tới kẻ phản quốc và kẻ tham ô. Đọc trọn văn bản, ta hiểu vì sao câu nói ấy sống mãi."},{"t":"Một lời đáp chung cho trong nước và thế giới. Ngày 21/1/1946, báo Cứu quốc số 147 đăng một văn bản ngắn của Chủ tịch Hồ Chí Minh, về sau được in trong bộ Hồ Chí Minh Toàn tập với tên gọi “Trả lời các nhà báo nước ngoài”. Mở đầu, Người viết rằng nhân dịp các bạn tân văn ký giả ngoại quốc hỏi đến, Người xin trả lời chung để đồng bào trong nước và nhân sĩ nước ngoài cùng hiểu rõ. “Tân văn ký giả” là cách gọi nhà báo thời ấy. Người chọn cách trả lời chung, công khai trên mặt báo, như một lời tự bạch trước công luận. Văn bản chỉ vài đoạn ngắn, lời lẽ giản dị, không một chữ khoa trương. Thế nhưng câu nói về “ham muốn tột bậc” nằm trong đó đã trở thành một trong những lời nổi tiếng nhất của Người. Trong Sảnh Hành trình, câu nói ấy được chọn đặt ở tường danh dự, cạnh chân dung Người năm 1946."},{"t":"Tôi chỉ có một sự ham muốn, ham muốn tột bậc, là làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành. — Hồ Chí Minh"},{"t":"Tháng Giêng năm 1946. Lời tự bạch ra đời vào một thời điểm đặc biệt. Chỉ hai tuần trước, ngày 6/1/1946, cử tri cả nước lần đầu đi bầu Quốc hội; Chủ tịch Hồ Chí Minh ứng cử ở Hà Nội và trúng cử với số phiếu rất cao. Trước đó, ngày 1/1/1946, Chính phủ lâm thời đã được mở rộng thành Chính phủ liên hiệp lâm thời, có thêm đại diện các đảng phái khác. Quân Tưởng Giới Thạch vẫn đóng ở miền Bắc; dựa vào đó, các nhóm Việt Nam Quốc dân Đảng và Việt Nam Cách mạng Đồng minh hội ra sức công kích chính quyền. Ngày 11/11/1945, Đảng Cộng sản Đông Dương đã ra thông cáo tự giải tán, thực chất là rút vào hoạt động bí mật, để tránh mũi nhọn công kích và giữ khối đoàn kết dân tộc. Trong hoàn cảnh ấy, câu hỏi về con người và ý định của vị Chủ tịch không chỉ là sự tò mò của báo chí nước ngoài. Lời đáp của Người vì thế vừa gửi tới dư luận quốc tế, vừa là lời bày tỏ công khai với quốc dân về động cơ của chính mình."},{"t":"Bạn có biết? Trong cuộc Tổng tuyển cử ngày 6/1/1946, Chủ tịch Hồ Chí Minh ứng cử tại Hà Nội và trúng cử với 98,4% số phiếu, tỷ lệ cao nhất trong số các đại biểu của Thủ đô."},{"t":"Người lính vâng lệnh quốc dân. Câu mở đầu lời tự bạch là một lời phủ nhận dứt khoát: Người tuyệt nhiên không ham muốn công danh phú quý chút nào. Chức Chủ tịch, Người viết, là do đồng bào ủy thác, nên phải gắng sức làm, cũng như một người lính vâng mệnh lệnh của quốc dân ra trước mặt trận. Bao giờ đồng bào cho lui, Người rất vui lòng lui. Hình ảnh người lính ở đây không phải phép tu từ. Suốt ba mươi năm trước đó, Người đã sống đúng như một chiến sĩ: làm thuê ở nhiều bến cảng xứ người, ngồi tù ở Hồng Kông rồi ở Quảng Tây, ăn cháo bẹ rau măng ở Pác Bó. Chức vụ cao nhất nước đến với Người ở tuổi năm mươi lăm, và Người nhìn nó như một nhiệm vụ được giao, có thể trả lại bất cứ lúc nào. Với nhiều người dân vừa thoát khỏi chế độ quân chủ, lời tuyên bố sẵn sàng rút lui khi dân không cần nữa là một quan niệm mới mẻ về quyền lực. Quyền lực là sự ủy thác của nhân dân, không phải của riêng người nắm giữ."},{"t":"Bốn vế, bốn món nợ của chế độ cũ. Câu nói về ham muốn tột bậc có bốn vế, đi từ việc lớn của quốc gia đến bữa cơm của từng nhà. Đó là nước hoàn toàn độc lập, dân hoàn toàn tự do, ai cũng có cơm ăn áo mặc, ai cũng được học hành. Mỗi vế là một món nợ mà chế độ cũ để lại. Hơn tám mươi năm, đất nước mất độc lập dưới ách thực dân, người dân không có những quyền tự do tối thiểu. Nạn đói năm Ất Dậu vừa qua; chính bản Tuyên ngôn Độc lập đã ghi rằng từ Quảng Trị đến Bắc Kỳ, hơn hai triệu đồng bào ta bị chết đói. Hơn chín mươi phần trăm dân số không biết chữ. Hai chữ “hoàn toàn” được nhắc tới hai lần cũng mang sức nặng riêng. Đầu năm 1946, nền độc lập còn bị bao vây, thực dân Pháp đang đánh chiếm Nam Bộ, và một thứ độc lập nửa vời không phải là điều Người chấp nhận. Còn hai vế sau thì giản dị như lời một người cha trong nhà: có cơm ăn, có áo mặc, được đi học."},{"t":"Bạn có biết? Để cứu đói, ngày 28/9/1945, Chủ tịch Hồ Chí Minh viết thư kêu gọi đồng bào cả nước cứ mười ngày nhịn ăn một bữa, mỗi tháng nhịn ba bữa, đem số gạo ấy cứu dân nghèo. Người nói rõ chính mình xin thực hành trước."},{"t":"Độc lập phải mang lại hạnh phúc. Vì sao Người đặt bát cơm và con chữ ngang hàng với độc lập, tự do? Ba tháng trước lời tự bạch, ngày 17/10/1945, Người gửi thư cho Ủy ban nhân dân các kỳ, tỉnh, huyện và làng. Trong thư, Người viết rằng nếu nước độc lập mà dân không được hưởng hạnh phúc, tự do, thì độc lập cũng chẳng có nghĩa lý gì. Độc lập là điều kiện đầu tiên, hạnh phúc của dân mới là thước đo cuối cùng. Chính quyền mới hành động theo đúng tinh thần ấy. Ngay phiên họp đầu tiên của Chính phủ ngày 3/9/1945, Người đề ra những nhiệm vụ cấp bách: chống đói, chống nạn mù chữ, sớm tổ chức tổng tuyển cử, bỏ các thứ thuế vô lý. Khắp nơi dấy lên phong trào tăng gia sản xuất, hũ gạo cứu đói, và những lớp Bình dân học vụ mở trong đình làng, sân chùa (xem chuyên đề Diệt giặc dốt, gian Hà Nội 1945 – Ba Đình). Bốn vế của câu nói năm 1946 vì thế không phải lời hứa suông, mà là bản tóm tắt chương trình hành động chính quyền đang làm từng ngày."},{"t":"Một cái nhà nho nhỏ bên non xanh nước biếc. Ngay sau câu nói về ham muốn tột bậc là một đoạn rất đời thường, ít được trích dẫn hơn. Riêng phần mình, Người chỉ mong làm một cái nhà nho nhỏ, nơi có non xanh nước biếc để câu cá, trồng hoa, sớm chiều làm bạn với các cụ già hái củi, em trẻ chăn trâu, không dính líu gì với vòng danh lợi. Đó là ước mơ của một người đã xa quê ba mươi năm, đã đi qua nhiều thành phố lớn trên thế giới, và chỉ mong được sống giữa những người lao động bình dị. Ước mơ ấy chưa bao giờ thành hiện thực. Chưa đầy một năm sau, Người rời Hà Nội lên chiến khu, sống và làm việc trong những căn lán nơi núi rừng Việt Bắc suốt cuộc kháng chiến chống Pháp. Từ tháng 5/1958, Người ở ngôi nhà sàn nhỏ trong khu Phủ Chủ tịch, có vườn cây, có ao cá, như một phần của mong ước năm nào. Nhưng ở đó Người vẫn làm việc cho đến những ngày cuối đời (xem chuyên đề gian Phủ Chủ tịch – Nhà sàn)."},{"t":"Đứng ngoài mọi đảng phái. Phần cuối của lời tự bạch lại càng ít người biết. Người viết rằng trong một nước dân chủ, mọi người đều có tự do tín ngưỡng, tự do tổ chức; còn riêng mình thì phải đứng ra ngoài mọi đảng phái. Nếu cần có đảng phái, thì đó sẽ là Đảng dân tộc Việt Nam, một đảng chỉ có một mục đích là làm cho dân tộc hoàn toàn độc lập. Đảng viên của đảng ấy sẽ là tất cả quốc dân Việt Nam, trừ những kẻ phản quốc và những kẻ tham ô. Đặt trong bối cảnh đầu năm 1946, những lời này là một thông điệp đoàn kết rõ ràng. Giữa lúc các phe phái công kích lẫn nhau, vị Chủ tịch khẳng định mình là người của cả dân tộc, và thước đo để phân biệt chỉ là lòng yêu nước. Đáng chú ý, ngay từ năm 1946, Người đã đặt kẻ tham ô bên cạnh kẻ phản quốc."},{"t":"Một mục đích, bất kỳ bao giờ, bất kỳ ở đâu. Lời tự bạch tháng Giêng năm 1946 không phải là một câu nói đơn lẻ. Suốt năm ấy, Người nhiều lần nhắc lại cùng một ý bằng những lời khác nhau. Tại cuộc mít tinh tiễn Người và đoàn đại biểu Chính phủ sang Pháp ngày 30/5/1946, Người nói với đồng bào rằng cả đời mình chỉ có một mục đích, là phấn đấu cho quyền lợi của Tổ quốc và hạnh phúc của quốc dân. Bất kỳ bao giờ, bất kỳ ở đâu, Người cũng chỉ theo đuổi một mục đích, làm cho ích quốc lợi dân. Gần năm tháng sau, Người trở về khi nước Pháp vẫn chưa chịu công nhận độc lập và thống nhất của Việt Nam. Ngày 23/10/1946, trong lời tuyên bố với quốc dân sau khi đi Pháp về, Người nói về nỗi lòng của mình với đồng bào miền Nam đang chìm trong khói lửa."},{"t":"Một ngày mà Tổ quốc chưa thống nhất, đồng bào còn chịu khổ, là một ngày tôi ăn không ngon, ngủ không yên. — Hồ Chí Minh"},{"t":"Tiếng vọng đến hôm nay. Hơn hai mươi ba năm sau lời tự bạch, trong bản Di chúc, Người vẫn dặn lại mong muốn cuối cùng về một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh (xem chuyên đề Sảnh Hành trình). Từ năm 1946 đến năm 1969, ham muốn ấy không đổi; chỉ những việc phải làm để đạt tới nó là thay đổi theo từng chặng đường. Ngày nay, dưới quốc hiệu trên các văn bản nhà nước vẫn là tiêu ngữ Độc lập – Tự do – Hạnh phúc. Ba cụm từ ngắn gọn ấy như thu gọn bốn vế của câu nói năm 1946: độc lập cho nước, tự do cho dân, và hạnh phúc là cơm ăn, áo mặc, được học hành. Trong Sảnh Hành trình, câu nói được đặt ở tường danh dự, mặt duy nhất trong mười tám mặt sảnh không dẫn vào một gian trưng bày nào. Có lẽ không lời giới thiệu nào về cuộc đời Người ngắn gọn hơn thế: một ham muốn, và cả một đời người dành trọn cho nó."}],"so_chu":1869}],"do_vat":[]};
